window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0159", [{"word":"marginalize","ipa_uk":"/ˈmɑːdʒɪnəlaɪz/","ipa_us":"/ˈmɑːrdʒɪnəlaɪz/","definition_zh":"使边缘化；把某人或某群体排挤到主流之外；贬低某事的重要性","definition_en":"to push a person, group or issue to the edge of a society, institution or discussion so that it has little influence","core_image":"长桌中央的人不断向前挪，靠墙那一排椅子被留在阴影里，坐在那里的人只看得见别人的背影","scene":"会场里的座椅一排排向前移，靠墙那一排被留在阴影中，坐在那里的人只看得见别人的背影。A housing policy that ignores tenants' complaints can marginalize the poorest families in the district.","sceneCN":"这里指「把某些人排挤到主流决策与资源之外」（第 1 个义项：使一个群体处于社会边缘）；句意为忽视租户诉求的住房政策会把区内最贫困的家庭挤到边缘。可辨识物件：靠墙座椅、阴影、长桌、门口、文件。","pos":[{"tag":"vt.","zh":"使边缘化；把（人或群体）排挤到主流之外"},{"tag":"vt.","zh":"贬低（议题、观点）的重要性，使之处于讨论边缘"}],"collocations":[{"phrase":"marginalize a group","zh":"使一个群体边缘化"},{"phrase":"marginalize the poor","zh":"把穷人排挤到边缘"},{"phrase":"marginalize dissent","zh":"压制不同意见，使其无足轻重"},{"phrase":"feel marginalized","zh":"感到被排挤"},{"phrase":"politically marginalized","zh":"在政治上被边缘化的"},{"phrase":"marginalize an issue","zh":"把某个议题贬到次要位置"}],"forms":[{"label":"三单（第三人称单数）","form":"marginalizes"},{"label":"过去式","form":"marginalized"},{"label":"过去分词","form":"marginalized"},{"label":"现在分词","form":"marginalizing"},{"label":"名词（边缘化）","form":"marginalization"},{"label":"形容词（被边缘化的）","form":"marginalized"},{"label":"形容词（边缘的；微小的）","form":"marginal"}],"derivatives":[{"word":"marginal","pos":"adj.","zh":"边缘的；页边的；微不足道的"},{"word":"margin","pos":"n.","zh":"页边空白；边缘；差额；余地"},{"word":"marginalization","pos":"n.","zh":"边缘化；被排挤的状态"},{"word":"marginalized","pos":"adj.","zh":"被边缘化的"},{"word":"marginality","pos":"n.","zh":"边缘性；处于边缘的状态"},{"word":"marginally","pos":"adv.","zh":"稍微；在边缘地"}],"senses":[{"no":"01","title":"Push a group to the edge of society","titleCN":"把某个群体推到社会边缘","definition":"to make a group live or work at the edge of society, with little access to resources, decisions or public attention","definitionCN":"使某个群体在社会边缘生活或工作，难以获得资源、决策权与公众关注","example":"A housing policy that ignores tenants' complaints can marginalize the poorest families in the district.","exampleCN":"忽视租户诉求的住房政策会把区内最贫困的家庭挤到边缘。","why":"The base noun is the edge of a page; adding a verb suffix turns the edge into a place where people are made to stand.","whyCN":"基础名词本指书页的边缘；加上动词后缀后，边缘就变成一个人被要求站住的位置。"},{"no":"02","title":"Treat an issue as minor","titleCN":"把某个议题当作次要问题","definition":"to give an issue so little attention or space that it counts as unimportant","definitionCN":"给某个议题的关注或篇幅少到使它显得不重要","example":"The annual report marginalizes mental health, giving it one short paragraph near the end.","exampleCN":"年度报告把心理健康放到次要位置，只在末尾给了一小段。","why":"What sits in the margin of a page is easy to skip; the verb applies that layout to an argument.","whyCN":"排在页边的内容最容易被跳过；这个动词把这种版面安排移用到论证上。"},{"no":"03","title":"Deny political voice","titleCN":"剥夺政治发言权","definition":"to keep a group out of political decisions by rules, distance or lack of representation","definitionCN":"通过规则、距离或缺乏代表权，把某个群体挡在政治决策之外","example":"Registration rules that exclude renters marginalize young voters in city elections.","exampleCN":"把租房者排除在外的登记规则，使年轻选民在市选举中被边缘化。","why":"A person at the edge of the room can see the table but cannot reach it; political voice follows the same geometry.","whyCN":"坐在屋子边缘的人看得见长桌却够不到；政治发言权遵循同样的空间关系。"},{"no":"04","title":"Push a business out of the market","titleCN":"把商家挤出主流市场","definition":"to make a firm or worker unable to compete in the main market, usually through cost or regulation","definitionCN":"通常因成本或监管，使企业或劳动者无法在主要市场中竞争","example":"Rents rising faster than sales marginalize small shops that cannot absorb the cost.","exampleCN":"租金涨得比销售额快，把无法消化成本的小店挤到市场边缘。","why":"The margin is also the narrow band where profit barely exists, so being pushed there means surviving at the edge of viability.","whyCN":"边缘也指利润勉强存在的窄带，因此被推到那里就意味着只能在存亡线上挣扎。"},{"no":"05","title":"Make a subject peripheral in education","titleCN":"使某学科在教育中处于附属地位","definition":"to reduce a school subject to an optional or minor place in the curriculum","definitionCN":"把某门学科在课程体系中降为选修或次要位置","example":"A timetable that marginalizes local languages leaves pupils without a written heritage.","exampleCN":"把本地语言排到课程边缘的课表，使学生失去书面传承。","why":"Curricula have a centre and a margin just as pages do, and the verb marks the move from one to the other.","whyCN":"课程表与书页一样有中心与边缘，这个动词标记的正是从中心被挪到边缘。"},{"no":"06","title":"Marginalize oneself","titleCN":"自我边缘化，主动退出中心","definition":"to place oneself outside a group or discussion by one's own choices","definitionCN":"因自己的选择而置身于群体或讨论之外","example":"By refusing every invitation, he marginalized himself within his own department.","exampleCN":"他拒绝所有邀请，结果在自己所在的部门里把自己边缘化了。","why":"The verb normally takes another person as its object; turning it on oneself shows that the edge can be chosen as well as imposed.","whyCN":"这个动词通常以别人为宾语；把它转向自己，说明边缘既可以被强加，也可以被主动选择。"},{"no":"07","title":"Integrate out a variable in statistics","titleCN":"统计学中把某个变量积分消去","definition":"to sum or integrate over a variable so that it no longer appears in the result","definitionCN":"对某个变量求和或积分，使它不再出现在结果中","example":"Bayesian analysts marginalize over the prior before they report the posterior.","exampleCN":"贝叶斯分析者在报告后验分布之前，先对先验做边缘化处理。","why":"In a table of totals, the margins hold the sums; to marginalize is to collapse a full table into its marginal totals.","whyCN":"在总计表里，边缘栏放的是求和结果；边缘化就是把整张表压缩成边缘合计。"},{"no":"08","title":"Frame an idea out of the debate","titleCN":"通过设框把某种考虑排除在讨论之外","definition":"to make a value or question disappear from a debate by defining the debate in narrower terms","definitionCN":"通过把讨论限定在更窄的范围内，使某种价值或问题从争论中消失","example":"Framing the debate around cost alone marginalizes questions of fairness.","exampleCN":"只围绕成本来设定讨论，就把公平问题挤到了边缘。","why":"The frame of a page decides what counts as main text; setting a narrow frame decides which ideas become margin notes.","whyCN":"页面的版框决定什么算正文；设定一个狭窄的版框，就决定了哪些想法只能成为页边注。"}],"etymology":{"intro":{"en":"Marginalize joins margin with the verb suffix -ize. Margin came through Old French from Latin margo, marginis 'edge, border'. The suffix reached English through French from Greek -izein 'to make or do'. Dates are approximate.","cn":"marginalize 由 margin 加动词后缀构成。margin 经古法语来自拉丁 margo（属格 marginis）「边缘、边界」。这个后缀经法语源自希腊语，意为「使……、做……」。年代均为约数。"},"items":[{"era":"LATIN MARGO","en":"Margo meant 'edge, border, brink'. Its deeper origin is not established; the boundary root often proposed for it is a reconstruction, not a demonstrated source.","cn":"margo 意为「边缘、边界、崖边」。其更深来源未得到证明；常为它提出的「边界」词根属于重构形式，并非已证实的来源。"},{"era":"OLD FRENCH MARGE","en":"Old French marge carried the word into English in the fourteenth century, first naming the blank edge of a page.","cn":"古法语 marge 在十四世纪把这个词带入英语，最初指书页的空白边缘。"},{"era":"ENGLISH MARGIN","en":"By the sixteenth century margin also named a difference, an amount left over, and the boundary of a field of activity.","cn":"到十六世纪，margin 也指差额、剩余量以及某种活动范围的边界。"},{"era":"ENGLISH MARGINALIZE","en":"The verb appeared in the mid-twentieth century in social science writing, where it named the process of pushing people to the edge of a group.","cn":"这个动词在二十世纪中叶出现于社会科学写作中，指把人推到群体边缘的过程。"},{"era":"SUFFIX -IZE","en":"The ending came through French from Greek -izein, which forms verbs meaning 'make, cause to be'.","cn":"这个后缀经法语源自希腊语，用来构成表示「使……、使成为」的动词。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): no exact first citation is recorded for the social sense, and the pre-Latin origin of margo is unsettled, so any earlier form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：社会义没有确切的最早书证；margo 在拉丁语之前的来源亦无定论，凡为其给出的更早形态均属重构形式。"}]},"similar":{"note":{"en":"Group one holds the same margin family in other parts of speech; group two holds verbs that remove influence by different means.","cn":"第一组是同一「边缘」词族中不同词性的词；第二组是以不同方式剥夺影响力的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"margin","ipa":"/ˈmɑːdʒɪn/","tag":"the noun","definition":"The page edge or the space around a main body of text; from it the whole family takes its image.","definitionCN":"书页边缘或正文四周的空白；整个词族都从它取得意象。"},{"word":"marginal","ipa":"/ˈmɑːdʒɪnəl/","tag":"the adjective","definition":"Means at the edge or barely important; it describes the position that the verb creates.","definitionCN":"意为「边缘的、微小的」；描述正是这个动词所造成的位置。"},{"word":"marginalization","ipa":"/ˌmɑːdʒɪnəlaɪˈzeɪʃən/","tag":"the noun","definition":"The process or result of being pushed to the edge; the verb names the act, this noun names the state.","definitionCN":"被推到边缘的过程或结果；动词指动作，这个名词指状态。"},{"word":"marginality","ipa":"/ˌmɑːdʒɪˈnæləti/","tag":"the abstract noun","definition":"The condition of living between two groups or outside the centre, often used in sociology.","definitionCN":"处在两个群体之间或中心之外的状态，常用于社会学。"}]},{"heading":"NEAR MEANING","entries":[{"word":"exclude","ipa":"/ɪkˈskluːd/","tag":"shut out","definition":"To keep someone out of a group or place on purpose; it names the act of barring, while marginalize names the resulting position.","definitionCN":"有意把某人挡在群体或场所之外；它指设障的动作，而 marginalize 指由此形成的位置。"},{"word":"sideline","ipa":"/ˈsaɪdlaɪn/","tag":"put aside","definition":"To move someone or something out of the main action, as a player is moved off the field.","definitionCN":"把某人或某事移出主要行动，如同把球员移到场边。"},{"word":"alienate","ipa":"/ˈeɪliəneɪt/","tag":"make estranged","definition":"To make a person feel distant or hostile; it stresses the emotional break, which marginalize does not always imply.","definitionCN":"使某人感到疏远或敌对；它强调情感上的断裂，而 marginalize 不一定带有这一层。"},{"word":"downgrade","ipa":"/ˈdaʊnɡreɪd/","tag":"lower in rank","definition":"To reduce the status or importance of something in an official scale.","definitionCN":"在正式等级中降低某物的地位或重要性。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real page-edge image, the real word family and the real academic phrases.","cn":"正常联想：真实的页边意象、真实的同族词与真实的学术搭配。"},"normal":[{"en":"The base noun is the blank edge of a page, and the verb ending means 'make', so the word means 'make someone a margin note'.","cn":"基础名词是书页的空白边缘，动词后缀意为「使……」，因此整个词意为「把某人变成页边的一条注」。"},{"en":"The family runs margin, marginal, marginalize, marginalization, marginalized and marginality.","cn":"同族词包括 margin、marginal、marginalize、marginalization、marginalized 与 marginality。"},{"en":"The academic phrases are marginalize a group, feel marginalized, politically marginalized and marginalize an issue.","cn":"学术搭配有「使某群体边缘化」「感到被排挤」「在政治上被边缘化」「把某议题贬到次要位置」。"},{"en":"The Latin source margo is also the root of the English word for a page border.","cn":"拉丁来源 margo 同时也是英语中「页边」一词的词根。"},{"en":"Sociology often pairs the word with its opposite: whatever is pushed from the centre is left at the margin.","cn":"社会学常把这个词与它的反面放在一起：凡被推出中心者，就留在边缘。"}],"abstract":[{"en":"Picture a meeting where every chair slowly moves forward, leaving one row against the wall in shadow.","cn":"想象一场会议，所有椅子都慢慢前移，只把靠墙的一排留在阴影里。"},{"en":"Picture a newspaper page whose main columns are full, so a whole neighbourhood's story is squeezed into the margin.","cn":"想象一张报纸，主要栏目都满了，于是一整个社区的故事被挤进页边。"},{"en":"Picture a sum table where only the edge totals survive, all the inner cells gone.","cn":"想象一张求和表，最后只剩边缘的合计，中间所有格子都消失了。"}]},"examples":[{"en":"The zoning plan marginalizes families who rent rather than own their homes.","cn":"分区规划把租房而非买房的家庭挤到了边缘。"},{"en":"When a newsroom treats science as a hobby, it marginalizes real expertise.","cn":"当新闻编辑室把科学当作业余爱好时，真正的专业能力就被贬到了边缘。"},{"en":"Analysts marginalize over the nuisance variable before they compare the models.","cn":"分析者在比较模型之前，先对干扰变量做边缘化处理。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「边缘」加「使……化」——把人从桌子中央挪到墙边 → 使边缘化、排挤","word":"marginalize"},"root":"marginalize 由 margin 加动词后缀构成；margin 经古法语来自拉丁 margo（属格 marginis）「边缘、边界」。margo 在拉丁语之前的更深来源未得到证明。这个后缀经法语源自希腊语，意为「使……」。","sensesIntro":{"en":"Eight senses follow one movement: something is moved from the centre to the edge. The movement is applied to a social group, an issue, a political voice, a market position, a school subject, the self, a statistical variable and finally the frame of a debate.","cn":"八个义项都沿同一个动作展开：把某物从中心移到边缘。这个动作依次用于社会群体、议题、政治发言权、市场位置、学校科目、自己、统计变量，最后用于一场讨论的设框。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long table whose centre is bright while the wall side stays in shadow.","cn":"核心意象：一张长桌，中央明亮，靠墙一侧始终在阴影里。"},"chain":["PAGE EDGE","PUSH OUTWARD","MINOR ROLE","NO VOICE","MARKET EDGE","SUMMED AWAY"],"branches":[{"senses":"01","en":"SOCIAL EDGE: the first sense places a whole group at the shadowed wall.","cn":"社会边缘：第一个义项把整个群体安置在靠墙的阴影里。"},{"senses":"02 · 08","en":"SMALL SPACE: an issue or a value survives only as a short note at the side of the argument.","cn":"微小篇幅：一个议题或一种价值只作为论证旁边的一条短注存在。"},{"senses":"03 · 05","en":"NO SEAT AT THE TABLE: voters and pupils are kept away from the decisions that shape them.","cn":"桌边无座：选民与学生被挡在塑造他们的决策之外。"},{"senses":"04","en":"BUSINESS MARGIN: a shop pushed to the thin band where survival is barely possible.","cn":"生意边缘：小店被推到只能勉强存活的窄带。"},{"senses":"06 · 07","en":"SELF AND NUMBER: the edge can be chosen by the person, and a whole table can be reduced to its margins.","cn":"自我与数字：边缘可以由本人选择，整张表也可以被压缩到只剩边缘合计。"}]},"affixes":{"intro":{"en":"The word can be read from an English noun for a page edge, a Latin source noun, a verb suffix from Greek and the derived words built on the same stem.","cn":"这个单词可以按表示页边的英语名词、拉丁来源名词、来自希腊语的动词后缀以及同一词干上的派生词逐段读出。"},"latinIntro":{"en":"Latin margo, marginis supplies margin and the whole family; the verb ending came through French from Greek and adds the sense of making.","cn":"拉丁 margo（属格 marginis）衍生 margin 与整个词族；动词后缀经法语来自希腊语，增添「使成为」的意思。"},"items":[{"word":"margin","structure":"margin (English noun)","meaning":"the blank edge of a page; a difference or reserve","meaningCN":"书页空白边缘；差额或余地","example":"The note sat in the margin of the page.","exampleCN":"那条注记留在书页的边缘。"},{"word":"margo","structure":"margo, marginis (Latin noun, third declension)","meaning":"edge, border, brink","meaningCN":"边缘；边界；崖边","example":"The Latin noun named the border of a field.","exampleCN":"这个拉丁名词本指田地的边界。"},{"word":"marginal","structure":"margin + -al (relating to)","meaning":"of the edge; barely important","meaningCN":"边缘的；微小的","example":"The change had only a marginal effect.","exampleCN":"这项变化只产生了微小的影响。"},{"word":"marginalize","structure":"marginal + -ize (make or cause)","meaning":"to make someone or something peripheral","meaningCN":"使某人或某事处于边缘","example":"The policy marginalized the poorest families.","exampleCN":"这项政策把最贫困的家庭排挤到边缘。"},{"word":"marginalized","structure":"marginalize + -ed (past participle)","meaning":"pushed to the edge","meaningCN":"被边缘化的","example":"The report gave voice to marginalized workers.","exampleCN":"这份报告为被边缘化的工人发声。"},{"word":"marginalization","structure":"marginalize + -ation (action or result)","meaning":"the act or state of being pushed to the edge","meaningCN":"边缘化；被排挤的状态","example":"The study traced the marginalization of rural schools.","exampleCN":"这项研究追溯了乡村学校被边缘化的过程。"},{"word":"marginally","structure":"marginal + -ly (adverb ending)","meaning":"slightly; at the edge","meaningCN":"稍微；在边缘地","example":"Prices rose marginally over the year.","exampleCN":"物价在这一年里略微上涨。"},{"word":"marginality","structure":"marginal + -ity (state)","meaning":"the condition of being at the edge","meaningCN":"边缘性；处于边缘的状态","example":"Her essays explore the marginality of migrant workers.","exampleCN":"她的文章探讨外来工人的边缘处境。"},{"word":"marginalia","structure":"marginal + -ia (plural noun ending)","meaning":"notes written in the margin","meaningCN":"写在页边的注记","example":"The scholar filled the marginalia with questions.","exampleCN":"这位学者在页边写满了疑问。"},{"word":"-ize","structure":"-ize (verb suffix from Greek through French)","meaning":"to make or cause to be","meaningCN":"使……；使成为","example":"The suffix turns a description into an action.","exampleCN":"这个后缀把一种描述变成一种动作。"}],"derivatives":[{"word":"marginal","structure":"margin + -al (relating to)","meaning":"of the edge; slight","meaningCN":"边缘的；微小的"},{"word":"marginalization","structure":"marginalize + -ation (action or result)","meaning":"the process of being pushed to the edge","meaningCN":"边缘化；被排挤的过程"},{"word":"marginality","structure":"marginal + -ity (state)","meaning":"the condition of being peripheral","meaningCN":"边缘性"},{"word":"marginally","structure":"marginal + -ly (adverb ending)","meaning":"slightly","meaningCN":"略微地"},{"word":"margin","structure":"margin (English noun from Latin)","meaning":"page edge; difference; reserve","meaningCN":"页边；差额；余地"}],"latinEntries":[{"word":"margo","structure":"margo, marginis (m., third declension)","meaning":"edge, border, brink","meaningCN":"边缘；边界；崖边"},{"word":"marginalis","structure":"marginalis, -e (adjective, Medieval Latin)","meaning":"of the edge, marginal","meaningCN":"边缘的；页边的"}]}},{"word":"inclusive","ipa_uk":"/ɪnˈkluːsɪv/","ipa_us":"/ɪnˈkluːsɪv/","definition_zh":"包含的；包括在内的；包容的（不排斥任何群体）；（范围）含端点的","definition_en":"including a particular person, group or limit rather than leaving it out","core_image":"一圈人围坐，桌子原本留着一个缺口，后来缺口处也摆上一把椅子，圈就此闭合","scene":"礼堂的座位原本只排到侧门，工作人员又搬来几把椅子，把最后一排补满。An inclusive admissions policy welcomes applicants from every region and every income level.","sceneCN":"这里指「不排斥任何群体、把所有人都纳入」（第 1 个义项：范围上包含所有人）；句意为不排斥的招生政策欢迎来自每个地区和每个收入水平的申请者。可辨识物件：礼堂座椅、侧门、登记桌、名单、台阶。","pos":[{"tag":"adj.","zh":"包容的；不排斥任何群体的"},{"tag":"adj.","zh":"包括在内的；含（某物）的"},{"tag":"adj.","zh":"（范围）含端点的；全部费用在内的"}],"collocations":[{"phrase":"inclusive of","zh":"包括……在内"},{"phrase":"inclusive education","zh":"融合教育；全纳教育"},{"phrase":"inclusive growth","zh":"包容性增长"},{"phrase":"inclusive language","zh":"包容性语言"},{"phrase":"all-inclusive","zh":"全部费用在内的"},{"phrase":"inclusive range","zh":"含端点的范围"}],"forms":[{"label":"比较级","form":"more inclusive"},{"label":"最高级","form":"most inclusive"},{"label":"副词（包容地）","form":"inclusively"},{"label":"名词（包容性）","form":"inclusiveness"},{"label":"名词（包含；纳入）","form":"inclusion"},{"label":"动词（包括）","form":"include"},{"label":"形容词（被包括的）","form":"included"}],"derivatives":[{"word":"include","pos":"v.","zh":"包括；把……纳入"},{"word":"included","pos":"adj.","zh":"被包括在内的"},{"word":"inclusion","pos":"n.","zh":"包含；纳入；包容"},{"word":"inclusively","pos":"adv.","zh":"包容地；包括地"},{"word":"inclusiveness","pos":"n.","zh":"包容性"},{"word":"inclusivity","pos":"n.","zh":"包容性（现代政策用语）"}],"senses":[{"no":"01","title":"Leaving no group out","titleCN":"不排斥任何群体","definition":"including everyone in a group, service or institution, especially people who are often excluded","definitionCN":"把一个群体、服务或机构向所有人开放，尤其是常被排除在外的人","example":"An inclusive admissions policy welcomes applicants from every region and every income level.","exampleCN":"不排斥的招生政策欢迎来自每个地区和每个收入水平的申请者。","why":"The Latin verb meant 'to shut in'; an inclusive rule shuts the gate only after everyone has been brought inside.","whyCN":"拉丁动词本义是「关在里面」；一条包容的规则是在所有人都被带进来之后才关门。"},{"no":"02","title":"Including the stated item","titleCN":"把所提到的事物包括在内","definition":"covering a named item as part of a total, often in the phrase inclusive of","definitionCN":"把提到的事物计入总数，常用于「包括……在内」这一说法","example":"The quoted price is inclusive of delivery and insurance.","exampleCN":"所报价格包含运费与保险。","why":"The word marks the boundary of a total: what lies inside the line is counted, what lies outside is not.","whyCN":"这个词标出总数的边界：线内之物计入，线外之物不计。"},{"no":"03","title":"One price covering everything","titleCN":"一价全包、费用全部计入","definition":"describing a price or package that covers all costs, so no extra charge follows","definitionCN":"描述涵盖全部费用的价格或套餐，事后不再另收费","example":"They booked an all-inclusive stay where meals and transfers were covered.","exampleCN":"他们订了一次一价全包的行程，餐食与接送都包含在内。","why":"The boundary sense turned commercial: the total is closed, and nothing is left outside it to be billed later.","whyCN":"边界义进入商业语境：总数被封闭起来，外面不再留下任何可另行收费的项目。"},{"no":"04","title":"Counting both endpoints","titleCN":"范围计算包含两端","definition":"counting the first and last values as part of a stated range","definitionCN":"把所给范围的首尾数值都计入其中","example":"Read pages ten to twenty inclusive before the seminar.","exampleCN":"研讨课之前读完第十页到第二十页，含首尾两页。","why":"A closed interval is drawn with solid ends; the word says the ends are inside the line, not outside it.","whyCN":"闭区间用实心端点画出；这个词表示端点在线内，而不在线外。"},{"no":"05","title":"Language that names everyone","titleCN":"照顾到所有人的语言表达","definition":"using words that do not assume one gender, culture or group and leave others invisible","definitionCN":"使用不预设某一种性别、文化或群体、也不让其他人隐形的措辞","example":"The style guide recommends inclusive language that names both parents.","exampleCN":"体例指南建议使用同时提到双亲的包容性措辞。","why":"A phrase can have a margin too: whichever group is not named is left outside the sentence.","whyCN":"措辞也有边缘：没有被提到的那群人就留在句子之外。"},{"no":"06","title":"Classrooms built for all pupils","titleCN":"让所有学生都能参与的课堂","definition":"describing schooling in which pupils with different needs learn together with shared support","definitionCN":"描述不同需求的学生在共同支持下一起学习的教育安排","example":"The district moved toward inclusive classrooms with shared support staff.","exampleCN":"该学区转向融合课堂，并配备共享的支持人员。","why":"The social sense settled into education, where the test of inclusion is whether a pupil sits inside the ordinary room.","whyCN":"社会义进入教育领域，衡量的标准就是学生是否被安置在普通教室里。"},{"no":"07","title":"Growth that reaches the edge","titleCN":"惠及边缘群体的增长","definition":"describing economic growth that raises incomes and opportunities for low-income groups as well as the average","definitionCN":"描述不仅提高平均值、也提高低收入群体收入与机会的经济增长","example":"Economists now ask whether growth is inclusive, not merely fast.","exampleCN":"经济学家现在追问增长是否包容，而不只看它是否快速。","why":"If growth stays in the centre, the margin receives nothing; an inclusive economy carries the gain to the edge.","whyCN":"增长若只留在中心，边缘什么也得不到；包容的经济把收益带到边缘。"},{"no":"08","title":"A pronoun that includes the listener","titleCN":"语言学中把听者包括在内的代词","definition":"describing a first person plural form that includes the person addressed as well as the speaker","definitionCN":"描述既包括说话者、也包括受话者的第一人称复数形式","example":"In some languages an inclusive first person plural includes the listener.","exampleCN":"有些语言的第一人称复数包含式把听者也包括在内。","why":"Grammar drew the same line: an inclusive form keeps the listener inside the circle, an exclusive form leaves the listener outside.","whyCN":"语法沿用了同一条界线：包含式把听者留在圈内，排除式把听者留在圈外。"}],"etymology":{"intro":{"en":"Inclusive comes from Medieval Latin inclusivus, from Latin includere 'to shut in', built on in- 'in' and claudere 'to shut, close'. Dates are approximate.","cn":"inclusive 来自中世纪拉丁 inclusivus，再往上出自拉丁 includere「关在里面」，由 in-「在内」与 claudere「关闭」构成。年代均为约数。"},"items":[{"era":"LATIN CLAUDERE","en":"Claudere meant 'to shut, close, enclose'. Its deeper origin is not established; the link sometimes suggested to clavis 'key' is a hypothesis, not a demonstrated derivation.","cn":"claudere 意为「关闭、围住」。其更深来源未得到证明；有人把它与 clavis「钥匙」联系起来，那只是假说，并非已证实的派生。"},{"era":"LATIN INCLUDERE","en":"In- 'in' plus claudere produced includere 'to shut in, enclose, include'.","cn":"in-「在内」加 claudere 构成 includere「关在里面、围住、包括」。"},{"era":"MEDIEVAL LATIN INCLUSIVUS","en":"Medieval Latin formed inclusivus to describe something that encloses or counts another item within it.","cn":"中世纪拉丁构成 inclusivus，用来描述把另一项围在或计入自身之内的事物。"},{"era":"ENGLISH INCLUSIVE","en":"English adopted the adjective in the fifteenth century, first in the sense of enclosing or comprising.","cn":"英语在十五世纪引入这个形容词，最初表示「围住」或「包含」。"},{"era":"SOCIAL SENSE","en":"In the twentieth century the word was applied to schools, workplaces and growth, where the question is who is left outside the gate.","cn":"到二十世纪，这个词被用于学校、职场与经济增长，问题变成谁被留在门之外。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of claudere is unsettled, and no exact first citation is recorded for the social sense, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：claudere 在拉丁语之前的来源无定论，社会义也没有确切的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds words from the same shutting-in root in other parts of speech; group two holds adjectives of wide or welcoming scope.","cn":"第一组是同出「关在里面」词根、词性不同的词；第二组是表示范围宽广或态度欢迎的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"include","ipa":"/ɪnˈkluːd/","tag":"the verb","definition":"To bring something inside a group or total; inclusive is the adjective describing such a total.","definitionCN":"把某物带入一个群体或总数；inclusive 是描述这种总数的形容词。"},{"word":"included","ipa":"/ɪnˈkluːdɪd/","tag":"the participle","definition":"Means 'having been counted in'; it marks an item already inside, while inclusive marks the boundary that lets it in.","definitionCN":"意为「已被计入的」；它标记已在内部的项目，而 inclusive 标记放它进来的那条边界。"},{"word":"inclusion","ipa":"/ɪnˈkluːʒən/","tag":"the noun","definition":"The act or state of being brought inside; the adjective describes the quality, the noun names the thing itself.","definitionCN":"被带入内部的动作或状态；形容词描述性质，名词指事物本身。"},{"word":"inclusively","ipa":"/ɪnˈkluːsɪvli/","tag":"the adverb","definition":"Means in a way that leaves nothing out; it modifies how a list or rule is applied.","definitionCN":"意为「以不遗漏任何一项的方式」；修饰清单或规则被适用的方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"comprehensive","ipa":"/ˌkɒmprɪˈhensɪv/","tag":"covering everything","definition":"Covering all or nearly all parts of a subject; it stresses completeness of content, not openness to people.","definitionCN":"涵盖一个主题的全部或几乎全部；强调内容的完整，而非对人的开放。"},{"word":"welcoming","ipa":"/ˈwelkəmɪŋ/","tag":"friendly to newcomers","definition":"Describing a place or person that makes outsiders feel wanted; it names the emotional effect of inclusion.","definitionCN":"描述让外来者感到被接纳的场所或人；它指包容带来的情感效果。"},{"word":"broad","ipa":"/brɔːd/","tag":"wide in scope","definition":"Covering a wide range; it can describe a category without saying who is treated fairly inside it.","definitionCN":"涵盖范围广；可描述一个类别，却不说明其中谁被公平对待。"},{"word":"universal","ipa":"/ˌjuːnɪˈvɜːsl/","tag":"applying to all","definition":"Applying to every member without exception; stronger than inclusive because it allows no local variation.","definitionCN":"无例外地适用于每一成员；比 inclusive 更强，因为它不留地方性差异。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real shutting-in root, the real derivatives and the real policy phrases.","cn":"正常联想：真实的「关在里面」词根、真实的派生词与真实的政策搭配。"},"normal":[{"en":"The Latin verb meant 'to shut in', so an inclusive rule closes the door only after everyone is inside.","cn":"拉丁动词意为「关在里面」，因此包容的规则是在所有人都进来之后才关门。"},{"en":"The family runs include, included, inclusion, inclusive, inclusively, inclusiveness and inclusivity.","cn":"同族词包括 include、included、inclusion、inclusive、inclusively、inclusiveness 与 inclusivity。"},{"en":"Policy phrases mark the modern sense: inclusive education, inclusive growth, inclusive language, all-inclusive.","cn":"政策搭配标出现代义：融合教育、包容性增长、包容性语言、一价全包。"},{"en":"The boundary sense survives in the arithmetic phrase 'ten to twenty inclusive'.","cn":"边界义保留在算术说法「第十到第二十，含首尾」中。"},{"en":"The prefix in- also appears in include and inclusion, all from the same Latin verb.","cn":"前缀 in- 同样出现在 include 与 inclusion 中，都出自同一个拉丁动词。"}],"abstract":[{"en":"Picture a circle of chairs with one gap, and a late guest filling that gap so the circle closes.","cn":"想象一圈椅子留着一个缺口，一位迟到的客人坐进缺口，圆圈就此闭合。"},{"en":"Picture a gate that stays open until the last person has walked through, then shuts behind everyone.","cn":"想象一扇门一直开着，直到最后一个人走过，才在所有人身后关上。"},{"en":"Picture a receipt with no line left for extras, because every cost was written inside the total.","cn":"想象一张账单，没有任何一行留给额外费用，因为每项成本都已写进总数。"}]},"examples":[{"en":"The library runs an inclusive reading hour for children of every ability.","cn":"图书馆为各种能力的孩子开设包容性阅读时段。"},{"en":"The fare is inclusive of taxes, so the final bill will not change.","cn":"票价已含税，因此最终账单不会再变。"},{"en":"Count the seats from the first row to the fifth inclusive.","cn":"座位从第一排数到第五排，含首尾两排。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「里面」加「关」——先把所有人都关进圈内，再合上门 → 包容的、包括在内的","word":"inclusive"},"root":"inclusive 来自中世纪拉丁 inclusivus，再往上出自拉丁 includere「关在里面」= in-「在内」+ claudere「关闭」。claudere 在拉丁语之前的更深来源不确定；与 clavis「钥匙」的联系仅为假说。","sensesIntro":{"en":"Eight senses follow one line: a boundary is drawn so that nothing and nobody is left outside. The line is applied to a group, a price, a range, a wording, a classroom, an economy and finally to the grammar of who counts as 'we'.","cn":"八个义项沿同一条线展开：画一条边界，使任何人与任何事物都不被留在外面。这条线依次用于群体、价格、范围、措辞、课堂、经济，最后用于「我们」是否包括听者的语法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a circle of chairs with its last gap filled.","cn":"核心意象：一圈椅子，最后一个缺口也被补上。"},"chain":["SHUT IN","NO ONE OUTSIDE","BOUNDS COUNTED","ALL COSTS IN","SHARED ROOM","GROWTH THAT REACHES"],"branches":[{"senses":"01","en":"THE CLOSED CIRCLE: the first sense fills the last empty chair so that no group stays outside.","cn":"闭合的圆圈：第一个义项补上最后一把空椅，使任何群体都不留在外面。"},{"senses":"02 · 04","en":"THE LINE ITSELF: a total or a range counts what lies inside, including both ends.","cn":"线本身：总数或范围只计入线内之物，两端也包括在内。"},{"senses":"03","en":"THE SEALED PRICE: every cost is written inside the total, leaving nothing to bill later.","cn":"封住的价格：每项成本都写进总数，事后不再收费。"},{"senses":"05 · 06","en":"ROOM IN THE SENTENCE AND THE CLASS: wording and schooling must also leave a chair for everyone.","cn":"句子与教室里的位置：措辞与教育同样必须给每个人留一把椅子。"},{"senses":"07 · 08","en":"GAIN AND GRAMMAR: prosperity reaches the margin, and the pronoun keeps the listener inside the circle.","cn":"收益与语法：繁荣抵达边缘，代词把听者留在圈内。"}]},"affixes":{"intro":{"en":"The word can be read from a Latin prefix meaning 'in', a Latin verb for shutting, a medieval adjective ending and the derived words built on the same stem.","cn":"这个单词可以按表示「在内」的拉丁前缀、表示关闭的拉丁动词、中世纪形容词后缀以及同一词干上的派生词逐段读出。"},"latinIntro":{"en":"Latin in- and claudere together give include and the whole family; the adjective ending -ive marks a quality, and -ity turns it into a noun.","cn":"拉丁 in- 与 claudere 合成 include 与整个词族；形容词后缀标记性质，名词后缀再把它变成名词。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, into')","meaning":"in; into","meaningCN":"在内；进入","example":"The prefix places the action inside a boundary.","exampleCN":"这个前缀把动作放进一条边界之内。"},{"word":"claudere","structure":"claudere, clausi, clausum (Latin verb, third conjugation)","meaning":"to shut, close, enclose","meaningCN":"关闭；围住","example":"The Latin verb supplies the closing image.","exampleCN":"这个拉丁动词提供「关闭」的意象。"},{"word":"include","structure":"in- + claudere","meaning":"to shut in; to count as part of a group","meaningCN":"关在里面；包括","example":"The fee includes all materials.","exampleCN":"费用包括全部材料。"},{"word":"inclusion","structure":"include + -sion (action or result)","meaning":"the act or state of being included","meaningCN":"包含；纳入","example":"The inclusion of new voices changed the report.","exampleCN":"新声音的加入改变了这份报告。"},{"word":"inclusive","structure":"include + -ive (tending to)","meaning":"tending to include; leaving nothing out","meaningCN":"倾向于包含的；不遗漏的","example":"The policy is inclusive of part-time workers.","exampleCN":"这项政策把兼职工作者也包括在内。"},{"word":"inclusively","structure":"inclusive + -ly (adverb ending)","meaning":"in an including way","meaningCN":"以包含的方式","example":"The list was read inclusively, from the first name to the last.","exampleCN":"名单从第一个名字读到最后，首尾都算在内。"},{"word":"inclusiveness","structure":"inclusive + -ness (quality)","meaning":"the quality of including others","meaningCN":"包容性","example":"Reviewers praised the inclusiveness of the design.","exampleCN":"评审者称赞这项设计的包容性。"},{"word":"inclusivity","structure":"inclusive + -ity (state or quality)","meaning":"deliberate openness to all groups","meaningCN":"有意识地接纳所有群体的做法","example":"The agency published targets for inclusivity.","exampleCN":"该机构公布了包容性目标。"},{"word":"included","structure":"include + -ed (past participle)","meaning":"counted in","meaningCN":"被包括在内的","example":"Breakfast is included in the room rate.","exampleCN":"早餐包含在房费内。"},{"word":"-ive","structure":"-ive (adjective suffix from Latin -ivus)","meaning":"tending to or serving to","meaningCN":"倾向于……的；起……作用的","example":"The ending turns a verb into a describing word.","exampleCN":"这个后缀把动词变成描述性词语。"}],"derivatives":[{"word":"include","structure":"in- + claudere (Latin)","meaning":"to take in as part of a whole","meaningCN":"包括；纳入"},{"word":"inclusion","structure":"include + -sion (action or result)","meaning":"the act or state of being included","meaningCN":"包含；包容"},{"word":"inclusively","structure":"inclusive + -ly (adverb ending)","meaning":"in a way that leaves nothing out","meaningCN":"以不遗漏的方式"},{"word":"inclusiveness","structure":"inclusive + -ness (quality)","meaning":"the quality of being open to all","meaningCN":"包容性"},{"word":"inclusivity","structure":"inclusive + -ity (state)","meaning":"deliberate inclusion of all groups","meaningCN":"包容性做法"}],"latinEntries":[{"word":"claudere","structure":"claudere, clausi, clausum (verb, third conjugation)","meaning":"to shut, close","meaningCN":"关闭"},{"word":"includere","structure":"includere, inclusi, inclusum (verb, third conjugation)","meaning":"to shut in, enclose","meaningCN":"关在里面；围住"},{"word":"inclusivus","structure":"inclusivus, -a, -um (adjective, Medieval Latin)","meaning":"enclosing, inclusive","meaningCN":"围住的；包含的"}]}},{"word":"inclusion","ipa_uk":"/ɪnˈkluːʒən/","ipa_us":"/ɪnˈkluːʒən/","definition_zh":"包含；纳入；包容（社会政策）；包含关系（数学）；包裹体（矿物或细胞内）","definition_en":"the act or state of being included within a group, whole or boundary","core_image":"木盒里分成一个个格位，每件小物都被放进属于自己的格子，盒盖合上时没有一件留在外面","scene":"教室里原本多出一把椅子，老师把它搬进圆圈，让转学来的孩子也坐进来。The inclusion of a new member changed how the committee made its decisions.","sceneCN":"这里指「把某人纳入一个群体或集体」（第 1 个义项：接纳新成员进入集体）；句意为一位新成员的加入改变了委员会做决定的方式。可辨识物件：圆圈座椅、空椅子、名册、桌牌、门口。","pos":[{"tag":"n.","zh":"包含；纳入（动作或状态，常作不可数）"},{"tag":"n.","zh":"包容；社会接纳（政策用语）"},{"tag":"n.","zh":"包裹体（矿物或细胞内的封闭小体）"},{"tag":"n.","zh":"包含关系（数学，指一个集合被另一个集合包含）"}],"collocations":[{"phrase":"social inclusion","zh":"社会包容"},{"phrase":"financial inclusion","zh":"金融普惠"},{"phrase":"inclusion in education","zh":"教育中的融合"},{"phrase":"the inclusion of new members","zh":"新成员的加入"},{"phrase":"set inclusion","zh":"集合包含关系"},{"phrase":"fluid inclusion","zh":"流体包裹体"}],"forms":[{"label":"不可数用法（整体包容）","form":"inclusion"},{"label":"可数复数（具体纳入实例）","form":"inclusions"},{"label":"动词（包括）","form":"include"},{"label":"形容词（包容的）","form":"inclusive"},{"label":"形容词（被纳入的）","form":"included"},{"label":"副词（包容地）","form":"inclusively"}],"derivatives":[{"word":"include","pos":"v.","zh":"包括；把……纳入"},{"word":"inclusive","pos":"adj.","zh":"包容的；包括在内的"},{"word":"included","pos":"adj.","zh":"被包括在内的"},{"word":"inclusively","pos":"adv.","zh":"以包含的方式"},{"word":"inclusiveness","pos":"n.","zh":"包容性"},{"word":"inclusivity","pos":"n.","zh":"包容性（政策用语）"}],"senses":[{"no":"01","title":"Bringing a person into a group","titleCN":"把某人纳入一个集体","definition":"the act of admitting a person or group into a body that had previously been without them","definitionCN":"把某人或某个群体接纳进此前没有他们的集体","example":"The inclusion of a new member changed how the committee made its decisions.","exampleCN":"一位新成员的加入改变了委员会做决定的方式。","why":"The Latin verb means 'to shut in'; inclusion is the moment the gate closes with one more person inside.","whyCN":"拉丁动词意为「关在里面」；这个名词指的就是门关上时里面多了一个人的那一刻。"},{"no":"02","title":"The feeling of belonging","titleCN":"被接纳的归属感","definition":"the experience of being treated as a full member rather than as an outsider","definitionCN":"被当作完整成员而非外来者的体验","example":"Her sense of inclusion grew after the team began sharing credit for its results.","exampleCN":"团队开始共同分享成果之后，她的归属感增强了。","why":"Being counted inside a group is not only a fact about membership but also a feeling about one's place.","whyCN":"被算在群体之内，不只是成员资格的事实，也是一种关于自己位置的感觉。"},{"no":"03","title":"A social policy of admitting all","titleCN":"接纳所有人的社会政策","definition":"a policy or programme that removes barriers keeping particular groups from services or public life","definitionCN":"消除某些群体获得服务或参与公共生活的障碍的政策或计划","example":"The city budget funds inclusion for residents with disabilities.","exampleCN":"城市预算为残障居民的包容性安排提供资金。","why":"The noun moved from a single act of admission to a standing public commitment to keep the gate open.","whyCN":"这个名词从一次接纳的动作，扩展为长期保持大门敞开的公共承诺。"},{"no":"04","title":"Learning together in one classroom","titleCN":"在同一间教室里共同学习","definition":"the practice of teaching pupils with different needs in the same ordinary classroom","definitionCN":"把需求不同的学生放在同一间普通教室里教学的做法","example":"Inclusion in mainstream classes requires trained support staff and flexible lesson plans.","exampleCN":"在普通班级中实施融合教育，需要受过训练的支持人员与灵活的教案。","why":"The policy sense acquired a school form, where the test is whether every pupil has an ordinary seat.","whyCN":"政策义获得学校形态，检验标准就是每个学生是否都有普通教室里的一把椅子。"},{"no":"05","title":"One set contained in another","titleCN":"数学中一个集合被另一个集合包含","definition":"the relation in which every element of one set also belongs to another set","definitionCN":"一个集合的每个元素同时属于另一个集合的关系","example":"The proof rests on the inclusion of one set in another.","exampleCN":"这个证明依赖于一个集合对另一个集合的包含关系。","why":"Mathematics kept the literal image: one collection is placed wholly inside the boundary of another.","whyCN":"数学保留了这个字面意象：一个集合被整体放进另一个集合的边界之内。"},{"no":"06","title":"A pocket sealed inside a mineral","titleCN":"矿物中封住的小包裹体","definition":"a small body of gas, liquid or another mineral trapped inside a crystal as it grew","definitionCN":"晶体生长过程中被封在内部的小团气体、液体或另一种矿物","example":"A tiny gas inclusion in the crystal records the air of an ancient atmosphere.","exampleCN":"晶体中微小的气体包裹体记录了远古大气的成分。","why":"The geological sense is literal enclosure: a drop of old water shut inside stone.","whyCN":"地质义就是字面意义的围住：一滴古老的水被关在石头里。"},{"no":"07","title":"A body inside a cell","titleCN":"细胞内的包含体","definition":"a structure or particle visible inside a cell, often a sign of infection or storage","definitionCN":"细胞内可见的结构或颗粒，常是感染或储存的迹象","example":"The pathologist noted an inclusion in the liver cells.","exampleCN":"病理学家注意到肝细胞内有一个包含体。","why":"Microscopy borrowed the same word because the object is enclosed by the cell as a box encloses an item.","whyCN":"显微镜观察借用了同一个词，因为该物被细胞围住，正如盒子围住一件物品。"},{"no":"08","title":"A contract clause requiring openness","titleCN":"要求开放选角的合同条款","definition":"a contractual requirement that a production include people from under-represented groups","definitionCN":"要求制作方纳入代表性不足群体的合同条款","example":"The actor added an inclusion rider to her contract before signing.","exampleCN":"这位演员在签约前把包容性条款加入合同。","why":"The modern labour sense turns inclusion into a written condition, so the gate can be held open by law rather than goodwill.","whyCN":"现代劳工义把包容写成书面条件，使大门靠条款而非善意保持敞开。"}],"etymology":{"intro":{"en":"Inclusion comes from Latin inclusio, 'a shutting in', from includere 'to shut in', built on in- 'in' and claudere 'to shut, close'. It entered English through learned Latin rather than through French. Dates are approximate.","cn":"inclusion 来自拉丁 inclusio「关在里面」，再往上出自 includere「关在里面」，由 in-「在内」与 claudere「关闭」构成。它经学术拉丁语而非法语进入英语。年代均为约数。"},"items":[{"era":"LATIN CLAUDERE","en":"Claudere meant 'to shut, close, enclose'. Its deeper origin is not established; the connection sometimes drawn to clavis 'key' is a hypothesis, not a demonstrated derivation.","cn":"claudere 意为「关闭、围住」。其更深来源未得到证明；有人把它与 clavis「钥匙」联系起来，那只是假说，并非已证实的派生。"},{"era":"LATIN INCLUDERE","en":"In- 'in' plus claudere gave includere 'to shut in, enclose, include'.","cn":"in-「在内」加 claudere 构成 includere「关在里面、围住、包括」。"},{"era":"LATIN INCLUSIO","en":"The noun inclusio, inclusonis named the act of shutting something in, and later an enclosed thing.","cn":"名词 inclusio（属格 inclusionis）指把某物关进去的动作，后来也指被围住之物。"},{"era":"ENGLISH INCLUSION","en":"English took the noun in the seventeenth century, first in the general sense of comprising something within a whole.","cn":"英语在十七世纪引入这个名词，最初泛指把某物包含在整体之内。"},{"era":"TECHNICAL SENSES","en":"Mineralogy and cell biology adopted the word for bodies enclosed in stone or cells, and mathematics used it for the relation of one set lying inside another.","cn":"矿物学与细胞学用这个词指被石头或细胞围住的小体；数学则用它指一个集合位于另一个集合之内的关系。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of claudere is unsettled, and the first citation of the social-policy sense is not fixed, so all dates here are approximate.","cn":"来源不确定（更深词源与首见年代）：claudere 在拉丁语之前的来源无定论，社会政策义的最早书证也不确定，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the same shutting-in family in other grammatical roles; group two holds nouns for bringing something into a larger whole.","cn":"第一组是同出「关在里面」词族、语法角色不同的词；第二组是把某物带入更大整体的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"include","ipa":"/ɪnˈkluːd/","tag":"the verb","definition":"To count something as part of a whole; inclusion is the act or result of doing so.","definitionCN":"把某物算作整体的一部分；inclusion 是这一动作或结果。"},{"word":"inclusive","ipa":"/ɪnˈkluːsɪv/","tag":"the adjective","definition":"Describing a group or total that leaves nobody out; it names the quality, not the event.","definitionCN":"描述不遗漏任何人的群体或总数；它指性质，而非事件。"},{"word":"included","ipa":"/ɪnˈkluːdɪd/","tag":"the participle","definition":"Means 'counted in'; it describes an item already inside, while inclusion can name the doorway itself.","definitionCN":"意为「被计入的」；描述已在内部的项目，而 inclusion 可指那道入口本身。"},{"word":"inclusively","ipa":"/ɪnˈkluːsɪvli/","tag":"the adverb","definition":"Means in a manner that omits nothing, usually of reading a range or applying a rule.","definitionCN":"意为「以不遗漏任何一项的方式」，通常用于读范围或适用规则。"}]},{"heading":"NEAR MEANING","entries":[{"word":"integration","ipa":"/ˌɪntɪˈɡreɪʃən/","tag":"making one whole","definition":"The process of combining parts into a single functioning whole; it stresses unity, while inclusion stresses entry.","definitionCN":"把各部分合为一个运作整体的过程；强调统一，而 inclusion 强调进入。"},{"word":"incorporation","ipa":"/ˌɪnkɔːpəˈreɪʃən/","tag":"absorbing into a body","definition":"The act of taking something into a larger organized body, often a company or a legal entity.","definitionCN":"把某物纳入一个更大的组织体，常指公司或法律实体。"},{"word":"membership","ipa":"/ˈmembəʃɪp/","tag":"the status of belonging","definition":"The state of belonging to a group; inclusion can also name the act of granting that state.","definitionCN":"属于某个群体的状态；inclusion 也可指赋予这一状态的动作。"},{"word":"admission","ipa":"/əˈmɪʃən/","tag":"the act of letting in","definition":"Permission to enter a place or institution; it is the gate event, broader than social inclusion.","definitionCN":"获准进入某地或某机构的许可；它是进入门槛的事件，比社会包容更宽泛。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin root, the real derivatives and the real policy phrases.","cn":"正常联想：真实的拉丁词根、真实的派生词与真实的政策搭配。"},"normal":[{"en":"The Latin verb means 'to shut in', so the noun names the moment the gate closes with one more person inside.","cn":"拉丁动词意为「关在里面」，因此这个名词指门关上时里面多了一个人的那一刻。"},{"en":"The family runs include, included, inclusion, inclusive, inclusively, inclusiveness and inclusivity.","cn":"同族词包括 include、included、inclusion、inclusive、inclusively、inclusiveness 与 inclusivity。"},{"en":"Policy phrases mark the public sense: social inclusion, financial inclusion, inclusion in education.","cn":"政策搭配标出公共义：社会包容、金融普惠、教育融合。"},{"en":"Technical phrases mark the physical sense: fluid inclusion, set inclusion, cell inclusion.","cn":"技术搭配标出物理义：流体包裹体、集合包含关系、细胞包含体。"},{"en":"The same root is visible in include and inclusive, and the noun is simply the act those words describe.","cn":"同一词根可见于 include 与 inclusive，而这个名词不过是那些词所描述的动作。"}],"abstract":[{"en":"Picture a box whose compartments are all filled and whose lid closes without pressing anything down.","cn":"想象一只盒子，每个格位都放好了东西，盒盖合上时没有压到任何一件。"},{"en":"Picture a circle of chairs where a latecomer is given a seat instead of a glance.","cn":"想象一圈椅子，迟到的人得到的是一个座位，而不是一瞥。"},{"en":"Picture a crystal holding a drop of ancient water sealed inside its clear wall.","cn":"想象一块水晶，把一滴远古的水封在透明的石壁之内。"}]},"examples":[{"en":"The inclusion of part-time staff in the pension plan took two years to negotiate.","cn":"把兼职员工纳入养老金计划，谈判花了两年。"},{"en":"Fluid inclusions in the quartz preserve samples of the original groundwater.","cn":"石英中的流体包裹体保存了原始地下水的样本。"},{"en":"In set theory, inclusion is written with a symbol that resembles a sideways horseshoe.","cn":"在集合论中，包含关系用一个像横放马蹄铁的符号来表示。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「里面」加「关」再加名词尾——把人和物都关进格子里，一个也不留在外面 → 包含、纳入、包容","word":"inclusion"},"root":"inclusion 来自拉丁 inclusio「关在里面」，源头是 includere「关在里面」= in-「在内」+ claudere「关闭」。claudere 的更深来源不确定，与 clavis「钥匙」的联系仅为假说。","sensesIntro":{"en":"Eight senses all describe something being placed inside a boundary: a person inside a group, a member inside a community, a pupil inside a classroom, a set inside another set, a drop inside a crystal and a body inside a cell.","cn":"八个义项都在描述某物被放进一条边界之内：人被放进群体，成员被放进共同体，学生被放进教室，集合被放进另一集合，水滴被放进晶体，小体被放进细胞。"},"semanticMap":{"core":{"en":"CORE IMAGE: a compartmented box with every item in its slot.","cn":"核心意象：一只分格的盒子，每件物品都在自己的格位里。"},"chain":["SHUT IN","BELONGING","OPEN POLICY","SHARED CLASSROOM","SUBSET","SEALED TRACE"],"branches":[{"senses":"01","en":"THE GATE EVENT: one more person is admitted and the group changes shape.","cn":"入口事件：又多一个人被接纳，群体因此改变形状。"},{"senses":"02 · 08","en":"INSIDE BY RIGHT: belonging can be felt, and it can also be written into a contract.","cn":"有权利在内：归属可以被感受到，也可以被写进合同。"},{"senses":"03 · 04","en":"PUBLIC AND SCHOOL: the gate is held open by policy and by classroom practice.","cn":"公共与学校：大门靠政策与课堂实践保持敞开。"},{"senses":"05","en":"MATHEMATICAL BOUNDARY: a whole set sits inside another with no element left out.","cn":"数学边界：一个集合整体位于另一个集合之内，没有元素留在外面。"},{"senses":"06 · 07","en":"SEALED BODIES: stone and cells enclose a trace of what was there when they formed.","cn":"封住的小体：石头与细胞围住形成之时的痕迹。"}]},"affixes":{"intro":{"en":"The noun can be read from a Latin prefix, a Latin verb of closing, a Latin noun ending and the derived family built on the same stem.","cn":"这个名词可以按拉丁前缀、表示关闭的拉丁动词、拉丁名词后缀以及同一词干上的派生词族逐段读出。"},"latinIntro":{"en":"Latin in- and claudere give include and inclusion; the noun ending -io names an act or its result.","cn":"拉丁 in- 与 claudere 衍生 include 与 inclusion；名词后缀指动作或其结果。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, into')","meaning":"in; into","meaningCN":"在内；进入","example":"The prefix puts the action inside a boundary.","exampleCN":"这个前缀把动作放进一条边界之内。"},{"word":"claudere","structure":"claudere, clausi, clausum (Latin verb, third conjugation)","meaning":"to shut, close","meaningCN":"关闭；围住","example":"The Latin verb carries the closing image.","exampleCN":"这个拉丁动词带着「关闭」的意象。"},{"word":"include","structure":"in- + claudere","meaning":"to shut in; to count as part of a whole","meaningCN":"关在里面；包括","example":"The course includes six laboratory sessions.","exampleCN":"这门课包括六次实验课。"},{"word":"inclusion","structure":"include + -sion (action or result)","meaning":"the act or state of being included","meaningCN":"包含；纳入","example":"The inclusion of new evidence delayed the verdict.","exampleCN":"新证据的纳入使裁决推迟。"},{"word":"inclusive","structure":"include + -ive (tending to)","meaning":"leaving no one out","meaningCN":"不遗漏任何人的","example":"The programme is inclusive of all ages.","exampleCN":"该计划涵盖所有年龄。"},{"word":"inclusively","structure":"inclusive + -ly (adverb ending)","meaning":"in an including manner","meaningCN":"以包含的方式","example":"The years were counted inclusively, from first to last.","exampleCN":"年份从第一年到最末一年都计入。"},{"word":"inclusiveness","structure":"inclusive + -ness (quality)","meaning":"the quality of including others","meaningCN":"包容性","example":"The review measured the inclusiveness of the hiring process.","exampleCN":"这项评估衡量了招聘流程的包容性。"},{"word":"inclusivity","structure":"inclusive + -ity (state or quality)","meaning":"deliberate openness to all groups","meaningCN":"有意识地接纳所有群体","example":"The board set an inclusivity target for each department.","exampleCN":"董事会为每个部门设定了包容性目标。"},{"word":"included","structure":"include + -ed (past participle)","meaning":"counted in","meaningCN":"被包括在内的","example":"The map is included with the guidebook.","exampleCN":"地图随指南书附送。"},{"word":"-sion","structure":"-sion (noun suffix from Latin -io)","meaning":"an action or its result","meaningCN":"动作或其结果","example":"The ending turns a verb of action into a noun.","exampleCN":"这个后缀把动作动词变成名词。"}],"derivatives":[{"word":"include","structure":"in- + claudere (Latin)","meaning":"to take in as part of a whole","meaningCN":"包括；纳入"},{"word":"inclusive","structure":"include + -ive (tending to)","meaning":"leaving nobody out","meaningCN":"包容的"},{"word":"inclusively","structure":"inclusive + -ly (adverb ending)","meaning":"in an including manner","meaningCN":"以包含的方式"},{"word":"inclusiveness","structure":"inclusive + -ness (quality)","meaning":"the quality of being open to all","meaningCN":"包容性"},{"word":"inclusivity","structure":"inclusive + -ity (state)","meaning":"deliberate inclusion of all groups","meaningCN":"包容性做法"}],"latinEntries":[{"word":"claudere","structure":"claudere, clausi, clausum (verb, third conjugation)","meaning":"to shut, close","meaningCN":"关闭"},{"word":"includere","structure":"includere, inclusi, inclusum (verb, third conjugation)","meaning":"to shut in, enclose","meaningCN":"关在里面；围住"},{"word":"inclusio","structure":"inclusio, inclusionis (f., third declension)","meaning":"a shutting in; an enclosed thing","meaningCN":"关入；被围住之物"}]}},{"word":"segregation","ipa_uk":"/ˌsiːɡrɪˈɡeɪʃən/","ipa_us":"/ˌsiːɡrəˈɡeɪʃən/","definition_zh":"隔离；分离；（种族、性别等的）隔离制度；（基因）分离；（废物）分类","definition_en":"the separation of people or things into distinct groups, whether by policy or by a natural process","core_image":"牧人把一群羊赶进两道栏门，门一关，两边的羊再也碰不到彼此","scene":"牧场上的羊被分成两栏，栏门关上后，两边的羊只能隔着木栅相望。Racial segregation kept the two neighbourhoods apart for decades.","sceneCN":"这里指「按种族把人分开的隔离制度」（第 1 个义项：种族隔离）；句意为种族隔离使两个街区数十年互不相通。可辨识物件：羊栏、木栅、栏门、牧场、土路。","pos":[{"tag":"n.","zh":"隔离；分离（常作不可数）"},{"tag":"n.","zh":"种族隔离制度（历史与社会学用语）"},{"tag":"n.","zh":"（基因）分离；分离现象（遗传学）"},{"tag":"n.","zh":"分类；分开处理（如垃圾分类）"}],"collocations":[{"phrase":"racial segregation","zh":"种族隔离"},{"phrase":"residential segregation","zh":"居住隔离"},{"phrase":"occupational segregation","zh":"职业隔离"},{"phrase":"waste segregation","zh":"垃圾分类"},{"phrase":"segregation of duties","zh":"职责分离"},{"phrase":"allele segregation","zh":"等位基因分离"}],"forms":[{"label":"不可数用法（整体制度或过程）","form":"segregation"},{"label":"可数复数（具体隔离安排，技术文献）","form":"segregations"},{"label":"动词（隔离）","form":"segregate"},{"label":"形容词（被隔离的）","form":"segregated"},{"label":"名词（隔离主义者）","form":"segregationist"},{"label":"形容词（隔离性的）","form":"segregative"}],"derivatives":[{"word":"segregate","pos":"v.","zh":"隔离；分开；分类"},{"word":"segregated","pos":"adj.","zh":"被隔离的；分开的"},{"word":"segregationist","pos":"n./adj.","zh":"隔离主义者（的）"},{"word":"segregative","pos":"adj.","zh":"造成分离的；隔离性的"},{"word":"segregational","pos":"adj.","zh":"与隔离相关的"},{"word":"gregarious","pos":"adj.","zh":"群居的；爱社交的（同出「群」词根）"}],"senses":[{"no":"01","title":"Separation of races by law","titleCN":"以法律强制实行的种族隔离","definition":"a system that keeps racial groups apart in schools, housing, transport and public life","definitionCN":"在学校、住房、交通与公共生活中把不同种族群体分开的制度","example":"Racial segregation kept the two neighbourhoods apart for decades.","exampleCN":"种族隔离使两个街区数十年互不相通。","why":"The Latin verb means 'to separate from the flock'; the racial sense applies that herding image to a whole society.","whyCN":"拉丁动词意为「把……赶出羊群」；种族义把这个分群意象用于整个社会。"},{"no":"02","title":"Separation written into policy","titleCN":"被写进政策的分离安排","definition":"any official arrangement that assigns groups to separate institutions or separate parts of a city","definitionCN":"把不同群体分配到分开的机构或城市不同区域的任何官方安排","example":"The report documented segregation by income across the school system.","exampleCN":"这份报告记录了整个学校系统中按收入形成的分离。","why":"Once a line is drawn by rule, the separation no longer depends on personal choice and becomes an institution.","whyCN":"一旦界线由规则画出，分离就不再取决于个人选择，而成为一项制度。"},{"no":"03","title":"Alleles separating in meiosis","titleCN":"减数分裂中等位基因的分离","definition":"the separation of paired alleles so that each gamete receives only one copy","definitionCN":"成对等位基因分开，使每个配子只得到一份拷贝","example":"The segregation of alleles during meiosis follows Mendel's first law.","exampleCN":"减数分裂中的等位基因分离遵循孟德尔第一定律。","why":"Genetics borrowed the word because chromosomes part into two sets as cleanly as a herd is split into two pens.","whyCN":"遗传学借用这个词，因为染色体分成两组，就像羊群被干净地分进两栏。"},{"no":"04","title":"Sorting waste at the source","titleCN":"在源头对垃圾进行分类","definition":"the practice of separating waste into streams such as paper, glass and food scraps before collection","definitionCN":"在收集之前把垃圾分成纸类、玻璃、厨余等类别的做法","example":"Waste segregation at the source raises recycling rates and lowers contamination.","exampleCN":"在源头进行垃圾分类能提高回收率并降低混杂污染。","why":"The core act of setting things apart is applied to materials, where mixing is the problem and separation is the fix.","whyCN":"把事物分开的核心动作被用于物料：混杂是问题，分开就是解决办法。"},{"no":"05","title":"Men and women in different jobs","titleCN":"男女被分到不同的职业","definition":"the pattern in which one sex is concentrated in certain occupations and pay levels","definitionCN":"某一性别集中在某些职业与薪酬层级的格局","example":"Occupational segregation channels women into lower-paid roles.","exampleCN":"职业隔离把女性导向薪酬较低的岗位。","why":"When a labour market sorts workers into separate tracks, the old image of separate pens reappears in wages.","whyCN":"当劳动力市场把劳动者分进不同轨道，旧有的分栏意象就以工资差异的形式重现。"},{"no":"06","title":"Neighbourhoods divided by group","titleCN":"不同群体住在分开的街区","definition":"the uneven distribution of social groups across neighbourhoods, often produced by housing markets and past policy","definitionCN":"社会群体在不同街区的分布不均，常由住房市场与过去政策造成","example":"Residential segregation shapes who can reach the best schools.","exampleCN":"居住隔离决定了谁能够进入最好的学校。","why":"A city map can be split like a herd: the line is invisible but the addresses on each side are distinct.","whyCN":"城市地图可以像羊群一样被分开：界线看不见，但两侧的地址泾渭分明。"},{"no":"07","title":"Keeping financial duties apart","titleCN":"把财务职责分开以防舞弊","definition":"an internal control that prevents one person from authorizing, recording and paying the same transaction","definitionCN":"一种内部控制，防止同一个人对同一笔交易同时拥有批准、记录与付款的权力","example":"Segregation of duties prevents one clerk from approving and paying the same invoice.","exampleCN":"职责分离防止同一名职员既批准又支付同一张发票。","why":"The word's separating act became a safeguard: tasks are penned apart so that no single hand controls the whole path.","whyCN":"这个词的分离动作变成一种保障：把任务分栏关好，使没有哪一只手能控制整条路径。"},{"no":"08","title":"Elements separating in an alloy","titleCN":"合金中元素的偏聚分离","definition":"the uneven redistribution of elements within a metal, producing regions of different composition","definitionCN":"金属内部元素重新分布不均，形成成分不同的区域","example":"Phase segregation in the alloy produced brittle regions along the grain boundaries.","exampleCN":"合金中的相分离沿晶界形成了脆性区域。","why":"Materials science uses the word for a natural sorting, where atoms of one kind gather as a flock gathers.","whyCN":"材料学用这个词指一种自然分选：同类原子像羊群一样聚在一起。"}],"etymology":{"intro":{"en":"Segregation comes from Latin segregatio, from segregare 'to separate from the flock', built on se- 'apart' and grex, gregis 'flock, herd'. Dates are approximate.","cn":"segregation 来自拉丁 segregatio，再往上出自 segregare「把……从羊群中分开」，由 se-「分开」与 grex（属格 gregis）「羊群、畜群」构成。年代均为约数。"},"items":[{"era":"LATIN GREX","en":"Grex meant 'flock, herd, crowd'. Its deeper origin is not established; the herd root sometimes proposed for it is a reconstruction.","cn":"grex 意为「羊群、畜群、人群」。其更深来源未得到证明；常为它提出的「畜群」词根属于重构形式。"},{"era":"LATIN SEGREGARE","en":"Se- 'apart' plus the verb built on grex produced segregare, 'to separate from the herd, set apart'.","cn":"se-「分开」加由 grex 构成的动词，产生 segregare「把……从畜群中分开、使隔开」。"},{"era":"LATIN SEGREGATIO","en":"The noun segregatio named the act of setting apart or the state of being apart.","cn":"名词 segregatio 指使分开的动作，或彼此分开的状态。"},{"era":"ENGLISH SEGREGATION","en":"English adopted the noun in the eighteenth century for a general act of separation before it acquired its racial sense.","cn":"英语在十八世纪引入这个名词，先指一般意义上的分离，后来才获得种族义。"},{"era":"RACIAL AND TECHNICAL SENSES","en":"The racial sense dominated in the twentieth century, while genetics, accounting and waste management developed their own specialized uses.","cn":"种族义在二十世纪占据主导，同时遗传学、会计与废物管理各自发展出专门用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of grex is unsettled, and the first citation of the racial sense is not fixed, so the dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：grex 在拉丁语之前的来源无定论，种族义的最早书证也不确定，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the same flock-root family in other grammatical roles; group two holds nouns that also name a dividing line.","cn":"第一组是同出「畜群」词根、语法角色不同的词；第二组是同样表示分界的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"segregate","ipa":"/ˈsiːɡrɪɡeɪt/","tag":"the verb","definition":"To set groups or things apart; segregation is the system or result that the verb produces.","definitionCN":"把群体或事物分开；segregation 是这一动作造成的制度或结果。"},{"word":"segregated","ipa":"/ˈsiːɡrɪɡeɪtɪd/","tag":"the participle","definition":"Describing something already kept apart, as a segregated school or bus.","definitionCN":"描述已被分开的事物，如隔离的学校或公交车。"},{"word":"segregationist","ipa":"/ˌsiːɡrɪˈɡeɪʃənɪst/","tag":"the person or policy","definition":"A person who supports keeping groups apart, or an adjective describing such a policy.","definitionCN":"支持把群体分开的人，或描述此类政策的形容词。"},{"word":"gregarious","ipa":"/ɡrɪˈɡeəriəs/","tag":"same flock root","definition":"Means fond of company and living in groups; it shares the herd root but has no sense of separation.","definitionCN":"意为「群居的、爱社交的」；它同出「畜群」词根，却完全没有分开的意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"separation","ipa":"/ˌsepəˈreɪʃən/","tag":"the general word","definition":"The broad act of dividing or keeping apart; segregation usually adds a group, a rule or a system.","definitionCN":"泛指分开或保持分离；segregation 通常还带有群体、规则或制度的含义。"},{"word":"isolation","ipa":"/ˌaɪsəˈleɪʃən/","tag":"cut off alone","definition":"The state of being alone or cut off from contact; it stresses loneliness, not a two-sided split.","definitionCN":"独处或与接触隔绝的状态；强调孤独，而非两边的分割。"},{"word":"division","ipa":"/dɪˈvɪʒən/","tag":"split into parts","definition":"The act of splitting a whole into parts; it can be neutral, while segregation often implies injustice.","definitionCN":"把整体分成部分；它可以中立，而 segregation 常带不公正的含义。"},{"word":"apartheid","ipa":"/əˈpɑːtaɪd/","tag":"a specific system","definition":"The former official system of racial separation in South Africa; a proper historical name, not a general synonym.","definitionCN":"南非昔日的官方种族隔离制度；这是专有的历史名称，并非一般同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real flock root, the real derivatives and the real technical phrases.","cn":"正常联想：真实的「畜群」词根、真实的派生词与真实的技术搭配。"},"normal":[{"en":"The Latin noun for a flock supplies the image: to segregate is to drive part of the herd into another pen.","cn":"拉丁语中表示羊群的名词提供意象：隔离就是把一部分羊赶进另一栏。"},{"en":"The family runs segregate, segregated, segregation, segregationist, segregative and segregational.","cn":"同族词包括 segregate、segregated、segregation、segregationist、segregative 与 segregational。"},{"en":"The social phrases are racial segregation, residential segregation and occupational segregation.","cn":"社会搭配有种族隔离、居住隔离与职业隔离。"},{"en":"The technical phrases are waste segregation, segregation of duties and allele segregation.","cn":"技术搭配有垃圾分类、职责分离与等位基因分离。"},{"en":"The same flock root appears in gregarious, which describes animals that stay together rather than split apart.","cn":"同一「畜群」词根出现在 gregarious 中，那个词描述喜欢结群而非分群的动物。"}],"abstract":[{"en":"Picture two pens divided by a gate that is never opened again.","cn":"想象两道羊栏，中间那扇门从此不再打开。"},{"en":"Picture a city map cut by an invisible line, with different addresses on each side.","cn":"想象一张城市地图被一条看不见的线切开，两侧的地址截然不同。"},{"en":"Picture four bins standing in a row, each receiving only one kind of waste.","cn":"想象四只桶排成一列，每只只接收一种废物。"}]},"examples":[{"en":"The court struck down the segregation of public schools.","cn":"法院推翻了公立学校的隔离制度。"},{"en":"Waste segregation begins in the kitchen, not at the sorting plant.","cn":"垃圾分类从厨房开始，而不是从分拣厂开始。"},{"en":"Segregation of duties is a basic safeguard in every accounting office.","cn":"职责分离是每个会计部门的基本保障。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「分开」加「羊群」——把一群羊分成两栏，栏门一关，两边再也碰不到 → 隔离、分离","word":"segregation"},"root":"segregation 来自拉丁 segregatio，源头是 segregare「把……从羊群中分开」= se-「分开」+ grex（属格 gregis）「羊群、畜群」。grex 在拉丁语之前的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one act: a group is split off from the rest and kept apart. The act is applied to races, institutions, alleles, waste, jobs, housing, financial duties and finally to elements inside a metal.","cn":"八个义项都沿同一个动作展开：把一部分从其余部分分出并保持隔离。这个动作依次用于种族、机构、等位基因、垃圾、职业、住房、财务职责，最后用于金属中的元素。"},"semanticMap":{"core":{"en":"CORE IMAGE: a herd driven into two pens with a shut gate between them.","cn":"核心意象：一群羊被赶进两栏，中间的门已经关上。"},"chain":["APART FROM THE HERD","DRAWN LINE","ALLELES SPLIT","SORTED STREAMS","JOBS AND HOUSES","GUARDED DUTIES"],"branches":[{"senses":"01","en":"THE RACIAL PEN: the oldest modern sense turns a whole society into two separate herds.","cn":"种族分栏：最古老的现代义把整个社会分成两群。"},{"senses":"02 · 06","en":"THE WRITTEN LINE: policy draws it, and the housing map makes it durable.","cn":"写下的界线：政策画出这条线，住房地图使它长久存在。"},{"senses":"03","en":"THE GENETIC SPLIT: chromosomes part with the same cleanness as the pens.","cn":"基因分裂：染色体分开得和羊栏一样干净。"},{"senses":"04","en":"THE MATERIAL STREAM: separation at the bin prevents mixing downstream.","cn":"物料分流：在桶边分开，防止下游混杂。"},{"senses":"05 · 07 · 08","en":"THE GUARDED SYSTEM: jobs, duties and alloys are all kept apart so that one part cannot control or contaminate the rest.","cn":"受守护的体系：职业、职责与合金都被分开，使某一部分无法控制或污染其余部分。"}]},"affixes":{"intro":{"en":"The noun can be read from a Latin prefix meaning 'apart', the Latin noun for a flock, the verb built on it and the derived family.","cn":"这个名词可以按表示「分开」的拉丁前缀、表示羊群的拉丁名词、由它构成的动词以及派生词族逐段读出。"},"latinIntro":{"en":"Latin se- and grex together give segregare and the whole family; gregarious shares the same herd noun without the prefix.","cn":"拉丁 se- 与 grex 合成 segregare 与整个词族；gregarious 共享同一个「畜群」名词，只是不带这个前缀。"},"items":[{"word":"se-","structure":"se- (Latin prefix, 'apart, aside')","meaning":"apart; aside","meaningCN":"分开；在一旁","example":"The prefix marks the movement away from the group.","exampleCN":"这个前缀标记离开群体的动作。"},{"word":"grex","structure":"grex, gregis (Latin noun, third declension)","meaning":"flock, herd, crowd","meaningCN":"羊群；畜群；人群","example":"The noun supplies the image of animals kept together.","exampleCN":"这个名词提供动物结群的意象。"},{"word":"segregare","structure":"se- + grex (Latin verb, first conjugation)","meaning":"to separate from the herd","meaningCN":"把……从畜群中分开","example":"The Latin verb named the act of setting one part aside.","exampleCN":"这个拉丁动词指把一部分放到一旁的动作。"},{"word":"segregate","structure":"segregare (English verb)","meaning":"to set apart by group","meaningCN":"按群体隔开","example":"The old rule segregated passengers by race.","exampleCN":"旧规定按种族把乘客隔开。"},{"word":"segregated","structure":"segregate + -ed (past participle)","meaning":"kept apart","meaningCN":"被隔开的","example":"The city maintained segregated schools for decades.","exampleCN":"这座城市维持隔离学校数十年。"},{"word":"segregation","structure":"segregate + -ation (action or result)","meaning":"separation into separate groups","meaningCN":"隔离；分离","example":"Residential segregation survived the change in law.","exampleCN":"居住隔离在法律改变之后依然存在。"},{"word":"segregationist","structure":"segregation + -ist (person or advocate)","meaning":"a supporter of keeping groups apart","meaningCN":"支持隔离的人","example":"The segregationist candidate lost the county vote.","exampleCN":"主张隔离的候选人输掉了该县的选票。"},{"word":"segregative","structure":"segregate + -ive (tending to)","meaning":"tending to separate","meaningCN":"倾向于分离的","example":"The policy had a segregative effect on poor districts.","exampleCN":"这项政策对贫困城区产生了分离效果。"},{"word":"segregational","structure":"segregation + -al (relating to)","meaning":"relating to segregation","meaningCN":"与隔离相关的","example":"Historians studied the segregational geography of the city.","exampleCN":"历史学者研究了这座城市的隔离地理。"},{"word":"gregarious","structure":"grex + -arius (adjective, 'of a herd')","meaning":"fond of company; living in groups","meaningCN":"群居的；爱社交的","example":"The birds are gregarious outside the breeding season.","exampleCN":"这些鸟在繁殖季之外喜欢结群。"}],"derivatives":[{"word":"segregate","structure":"se- + grex (Latin)","meaning":"to set apart","meaningCN":"隔离；分开"},{"word":"segregated","structure":"segregate + -ed (past participle)","meaning":"kept apart","meaningCN":"被隔离的"},{"word":"segregationist","structure":"segregation + -ist (person)","meaning":"a supporter of separation","meaningCN":"隔离主义者"},{"word":"segregative","structure":"segregate + -ive (tending to)","meaning":"tending to separate","meaningCN":"造成分离的"},{"word":"gregarious","structure":"grex + -arius (adjective)","meaning":"herd-loving","meaningCN":"群居的"}],"latinEntries":[{"word":"grex","structure":"grex, gregis (m., third declension)","meaning":"flock, herd","meaningCN":"羊群；畜群"},{"word":"segregare","structure":"segregare, segregavi, segregatum (verb, first conjugation)","meaning":"to separate from the herd","meaningCN":"把……从畜群中分开"},{"word":"segregatio","structure":"segregatio, segregationis (f., third declension)","meaning":"a setting apart","meaningCN":"分开；隔离"},{"word":"gregarius","structure":"gregarius, -a, -um (adjective)","meaning":"of a herd, gregarious","meaningCN":"畜群的；群居的"}]}},{"word":"segregate","ipa_uk":"/ˈsiːɡrɪɡeɪt/","ipa_us":"/ˈseɡrəɡeɪt/","definition_zh":"隔离；分开；按类别分开（垃圾、材料等）；（基因）分离；把（病人）单独隔开","definition_en":"to set people or things apart into separate groups, either by policy, by sorting or by a natural process","core_image":"牧人举着木杖，把混在一起的羊群赶向左右两道栏门","scene":"牧人把混在一起的羊群分成两路，一路进左栏，一路进右栏。An old rule used to segregate passengers by race on the same bus.","sceneCN":"这里指「按种族把人群强制分开」（第 1 个义项：按群体实行隔离）；句意为旧时的规定在同一辆公交车上按种族把乘客隔开。可辨识物件：木杖、羊栏、栏门、公交车、座位。","pos":[{"tag":"vt.","zh":"隔离；把（群体）分开"},{"tag":"vi.","zh":"分开；分离（如基因、元素）"},{"tag":"adj.","zh":"被隔离的（少用，多见于技术文献）"}],"collocations":[{"phrase":"segregate by race","zh":"按种族隔离"},{"phrase":"segregate waste","zh":"把垃圾分类"},{"phrase":"segregate duties","zh":"把职责分开"},{"phrase":"segregate a patient","zh":"把病人单独隔离"},{"phrase":"segregate alleles","zh":"使等位基因分离"},{"phrase":"segregate the sexes","zh":"把两性分开"}],"forms":[{"label":"三单（第三人称单数）","form":"segregates"},{"label":"过去式","form":"segregated"},{"label":"过去分词","form":"segregated"},{"label":"现在分词","form":"segregating"},{"label":"名词（隔离）","form":"segregation"},{"label":"名词（隔离主义者）","form":"segregationist"},{"label":"形容词（造成分离的）","form":"segregative"}],"derivatives":[{"word":"segregation","pos":"n.","zh":"隔离；分离；分类"},{"word":"segregated","pos":"adj.","zh":"被隔离的；分开的"},{"word":"segregationist","pos":"n./adj.","zh":"隔离主义者（的）"},{"word":"segregative","pos":"adj.","zh":"造成分离的"},{"word":"segregational","pos":"adj.","zh":"与隔离相关的"},{"word":"gregarious","pos":"adj.","zh":"群居的；爱社交的"}],"senses":[{"no":"01","title":"Separate people by group","titleCN":"按群体把人分开","definition":"to require different racial, ethnic or social groups to use separate places, services or institutions","definitionCN":"要求不同种族、族裔或社会群体使用分开的场所、服务或机构","example":"Old rules segregated passengers by race on the same bus.","exampleCN":"旧规定在同一辆公交车上按种族把乘客隔开。","why":"The Latin verb means 'to separate from the herd', and the modern racial use applies that herding action to people.","whyCN":"拉丁动词意为「把……从畜群中分开」，现代种族用法把这个分群动作用于人。"},{"no":"02","title":"Sort materials into streams","titleCN":"把物料分进不同类别","definition":"to separate waste, recycling or components into categories before further handling","definitionCN":"在进一步处理之前，把垃圾、回收物或零件按类别分开","example":"Households that segregate waste at the source raise the quality of recycling.","exampleCN":"在源头把垃圾分类的家庭提高了回收质量。","why":"The act of driving one part away from the rest works just as well for glass, paper and food scraps.","whyCN":"把一部分从其余部分赶开的动作，用在玻璃、纸张与厨余上同样合适。"},{"no":"03","title":"Alleles parting in meiosis","titleCN":"等位基因在减数分裂中分离","definition":"to separate paired alleles so that each gamete receives a single copy","definitionCN":"使成对的等位基因分开，让每个配子只得到一份","example":"During meiosis, homologous chromosomes segregate into different gametes.","exampleCN":"在减数分裂中，同源染色体分离进入不同的配子。","why":"Chromosomes part into two sets as cleanly as a herd is split between two pens.","whyCN":"染色体分成两组，干净利落得就像羊群被分进两栏。"},{"no":"04","title":"Keep an infected patient apart","titleCN":"把传染病人单独隔开","definition":"to place a patient or case in isolation to prevent contact with others","definitionCN":"把病人或病例单独安置，以防止与他人接触","example":"The hospital segregated the patient until the test results returned.","exampleCN":"医院把病人单独隔离，直到检测结果出来。","why":"Medical separation borrows the fencing image: one body is kept in its own pen for the safety of the herd.","whyCN":"医学隔离借用了围栏意象：为了群体的安全，把一个身体关进自己的栏里。"},{"no":"05","title":"Put a group in a separate space","titleCN":"把一群人安置在另一处空间","definition":"to assign a group to a distinct room, building or area rather than a shared one","definitionCN":"把某个群体分配到单独的教室、建筑或区域，而非共享空间","example":"The school used to segregate younger pupils into a separate wing.","exampleCN":"这所学校过去把低年级学生分到单独的一翼。","why":"A building, like a pasture, can be divided by walls; the verb marks which side each group is sent to.","whyCN":"建筑和牧场一样可以用墙分开；这个动词标记每个群体被送往哪一边。"},{"no":"06","title":"Split duties between people","titleCN":"把职责分给不同的人","definition":"to divide authority over a transaction so that no single person controls the whole process","definitionCN":"把同一笔交易的权限分开，使没有一个人控制全过程","example":"The finance office segregates duties so that the same clerk cannot approve and pay.","exampleCN":"财务部门把职责分开，使同一名职员不能既批准又付款。","why":"Internal control uses the verb because separating tasks prevents one hand from owning the whole path.","whyCN":"内部控制使用这个动词，因为把任务分开可以防止一只手掌握整条路径。"},{"no":"07","title":"Separate oneself from a group","titleCN":"把自己从群体中分出来","definition":"to withdraw deliberately from a group or from shared activity","definitionCN":"有意从一个群体或共同活动中退出","example":"He segregated himself from the planning group after the dispute.","exampleCN":"争执之后，他把自己从筹备组中分离出来。","why":"Turning the verb on oneself shows that the pen can be entered by choice as well as by force.","whyCN":"把动词转向自己，说明栏门既可以被人强行关上，也可以由自己走进去。"},{"no":"08","title":"Atoms gathering in an alloy","titleCN":"合金中的原子偏聚","definition":"to redistribute unevenly within a solid, so that regions differ in composition","definitionCN":"在固体内部不均匀地重新分布，使各区域成分不同","example":"Carbon atoms segregate along the grain boundaries as the steel cools.","exampleCN":"钢冷却时，碳原子沿晶界偏聚。","why":"In materials science the herd image becomes literal again: like atoms gather into their own flock.","whyCN":"在材料科学中，畜群意象又变回字面：同类原子聚成自己的群。"}],"etymology":{"intro":{"en":"Segregate comes from Latin segregare 'to separate from the flock', built on se- 'apart' and grex, gregis 'flock, herd'. The English verb appeared in the sixteenth century. Dates are approximate.","cn":"segregate 来自拉丁 segregare「把……从羊群中分开」，由 se-「分开」与 grex（属格 gregis）「羊群、畜群」构成。英语动词在十六世纪出现。年代均为约数。"},"items":[{"era":"LATIN GREX","en":"Grex meant 'flock, herd, crowd'. Its deeper origin is not established; the herd root proposed for it is a reconstruction.","cn":"grex 意为「羊群、畜群、人群」。其更深来源未得到证明；为它提出的「畜群」词根属于重构形式。"},{"era":"LATIN SEGREGARE","en":"Se- 'apart' plus the verb from grex produced segregare, 'to set apart from the herd'.","cn":"se-「分开」加由 grex 构成的动词，产生 segregare「把……从畜群中分出」。"},{"era":"ENGLISH SEGREGATE","en":"The verb entered English in the sixteenth century with the general sense of setting things or people apart.","cn":"这个动词在十六世纪进入英语，泛指把事物或人分开。"},{"era":"RACIAL SENSE","en":"By the nineteenth and twentieth centuries the verb was used for official separation of racial groups, especially in the United States.","cn":"到十九与二十世纪，这个动词用于官方按种族分开群体，尤其在美国。"},{"era":"SCIENTIFIC SENSES","en":"Genetics adopted the verb for the parting of alleles, and metallurgy for the uneven gathering of atoms.","cn":"遗传学借用这个动词指等位基因的分离，冶金学则用它指原子的不均匀聚集。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of grex is unsettled, and no exact first citation is fixed for the racial use, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：grex 在拉丁语之前的来源无定论，种族用法的最早书证也不确定，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the same flock-root family; group two holds verbs that divide by other means.","cn":"第一组是同出「畜群」词根的词族；第二组是用其他方式划分的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"segregation","ipa":"/ˌsiːɡrɪˈɡeɪʃən/","tag":"the noun","definition":"The system or result of keeping groups apart; the verb names the act that produces it.","definitionCN":"把群体隔开的制度或结果；动词指产生它的动作。"},{"word":"segregated","ipa":"/ˈsiːɡrɪɡeɪtɪd/","tag":"the participle","definition":"Describing something already kept apart, as a segregated carriage or school.","definitionCN":"描述已被隔开的事物，如隔离车厢或隔离学校。"},{"word":"segregationist","ipa":"/ˌsiːɡrɪˈɡeɪʃənɪst/","tag":"the person","definition":"A person who advocates separation of groups; it names a supporter, not the act.","definitionCN":"主张分开群体的人；指支持者，而非动作。"},{"word":"gregarious","ipa":"/ɡrɪˈɡeəriəs/","tag":"same flock root","definition":"Means sociable and living in groups; it shares the herd noun but carries no idea of separation.","definitionCN":"意为「群居的、爱社交的」；共享「畜群」名词，却不含分离之意。"}]},{"heading":"NEAR MEANING","entries":[{"word":"separate","ipa":"/ˈsepəreɪt/","tag":"the general verb","definition":"To divide or keep apart; segregate usually adds a group, a rule or a systematic policy.","definitionCN":"泛指分开或保持分离；segregate 通常还带有群体、规则或系统政策的含义。"},{"word":"isolate","ipa":"/ˈaɪsəleɪt/","tag":"cut off","definition":"To place something entirely alone or apart from contact; it stresses total separation rather than group sorting.","definitionCN":"把某物完全单独放置或切断接触；强调彻底分离，而非群体分类。"},{"word":"sort","ipa":"/sɔːt/","tag":"arrange by type","definition":"To arrange things by category, often for practical handling; it is neutral and lacks the social weight of segregate.","definitionCN":"按类别整理物品，通常为了实际处理；它中立，没有 segregate 的社会重量。"},{"word":"split","ipa":"/splɪt/","tag":"divide into parts","definition":"To break a whole into parts; it does not imply that the parts are kept from meeting again.","definitionCN":"把整体分成部分；不暗示各部分此后被阻止再度接触。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real herding verb, the real derivatives and the real technical phrases.","cn":"正常联想：真实的分群动词、真实的派生词与真实的技术搭配。"},"normal":[{"en":"The Latin verb means 'to drive part of the herd away', so the English verb keeps the image of a gate closing between two pens.","cn":"拉丁动词意为「把一部分羊赶出群」，因此英语动词保留了两栏之间关门上锁的意象。"},{"en":"The family runs segregate, segregated, segregation, segregationist, segregative and segregational.","cn":"同族词包括 segregate、segregated、segregation、segregationist、segregative 与 segregational。"},{"en":"The social phrases are segregate by race and segregate the sexes.","cn":"社会搭配有按种族隔离与把两性分开。"},{"en":"The technical phrases are segregate waste, segregate duties and segregate alleles.","cn":"技术搭配有垃圾分类、职责分离与等位基因分离。"},{"en":"The same herd noun appears in gregarious, which describes animals that stay together instead of being parted.","cn":"同一个「畜群」名词出现在 gregarious 中，那个词描述结群而不被分开的动物。"}],"abstract":[{"en":"Picture a wooden gate shutting between two pens while the animals on each side stop calling to each other.","cn":"想象两栏之间的木门关上，两边的动物不再互相呼唤。"},{"en":"Picture three bins with lids of different colours, each taking only one stream.","cn":"想象三只桶盖着不同颜色的盖子，每只只收一种物料。"},{"en":"Picture two clerks sitting at separate desks so that neither can finish the payment alone.","cn":"想象两名职员坐在分开的桌前，谁也无法独自完成付款。"}]},"examples":[{"en":"The city council finally stopped segregating students by neighbourhood income.","cn":"市议会终于停止按街区收入把学生分开。"},{"en":"Nurses segregate infectious cases in a separate ward.","cn":"护士把传染病例隔离在单独的病房。"},{"en":"As the alloy cooled, tin began to segregate at the surface.","cn":"合金冷却时，锡开始在表面偏聚。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「分开」加「羊群」——把混在一起的羊赶进两道栏门 → 隔离、分开","word":"segregate"},"root":"segregate 来自拉丁 segregare「把……从羊群中分开」= se-「分开」+ grex（属格 gregis）「羊群、畜群」。grex 在拉丁语之前的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one action: a part is driven away from the rest. The action is applied to races, waste, alleles, a patient, a group in a building, office duties, the self and atoms in a metal.","cn":"八个义项沿同一个动作展开：把一部分从其余部分赶开。这个动作依次用于种族、垃圾、等位基因、病人、建筑中的群体、办公职责、自己以及金属中的原子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a herder dividing the flock with a raised staff.","cn":"核心意象：牧人举起木杖，把羊群分成两路。"},"chain":["DRIVE APART","RACIAL LINE","SORTED STREAMS","ALLELES SPLIT","ISOLATED WARD","GUARDED TASKS"],"branches":[{"senses":"01","en":"THE FORCED PEN: the racial sense closes the gate on people who did not choose it.","cn":"强制分栏：种族义对那些并未选择的人关上栏门。"},{"senses":"02","en":"THE SORTING BIN: materials are separated so that mixing does not undo their value.","cn":"分类桶：把物料分开，使混杂不至于毁掉它们的价值。"},{"senses":"03","en":"THE GENETIC PEN: chromosomes part into two sets as cleanly as animals into two pens.","cn":"基因分栏：染色体分成两组，和动物分进两栏一样干净。"},{"senses":"04 · 05","en":"THE SEPARATE ROOM: a patient or a group is moved behind a wall for safety or order.","cn":"分隔的房间：病人或群体被移到墙后，以求安全或秩序。"},{"senses":"06 · 07 · 08","en":"THE GUARDED PATH: duties, the self and atoms are all kept apart so that no single part controls the whole.","cn":"受守护的路径：职责、自己与原子都被分开，使任何单独部分都无法掌控整体。"}]},"affixes":{"intro":{"en":"The verb can be read from a Latin prefix of separation, a Latin noun for a herd, the derived verb and its family.","cn":"这个动词可以按表示分离的拉丁前缀、表示畜群的拉丁名词、由它们构成的动词以及词族逐段读出。"},"latinIntro":{"en":"Latin se- and grex give segregare, segregate and segregation; the same herd noun also yields gregarious.","cn":"拉丁 se- 与 grex 衍生 segregare、segregate 与 segregation；同一个「畜群」名词还衍生 gregarious。"},"items":[{"word":"se-","structure":"se- (Latin prefix, 'apart')","meaning":"apart; aside","meaningCN":"分开；在一旁","example":"The prefix marks departure from the group.","exampleCN":"这个前缀标记离开群体。"},{"word":"grex","structure":"grex, gregis (Latin noun, third declension)","meaning":"flock, herd","meaningCN":"羊群；畜群","example":"The noun gives the image of animals kept together.","exampleCN":"这个名词提供动物结群的意象。"},{"word":"segregare","structure":"se- + grex (Latin verb, first conjugation)","meaning":"to separate from the herd","meaningCN":"把……从畜群中分开","example":"The Latin verb named the act of setting one part aside.","exampleCN":"这个拉丁动词指把一部分放到一旁的动作。"},{"word":"segregate","structure":"segregare (English verb)","meaning":"to set apart","meaningCN":"隔离；分开","example":"The rule segregated passengers by race.","exampleCN":"这项规定按种族把乘客隔开。"},{"word":"segregated","structure":"segregate + -ed (past participle)","meaning":"kept apart","meaningCN":"被隔开的","example":"The ward was segregated from the rest of the hospital.","exampleCN":"这间病房与医院其余部分隔开。"},{"word":"segregation","structure":"segregate + -ation (action or result)","meaning":"separation into groups","meaningCN":"隔离；分离","example":"Waste segregation starts at home.","exampleCN":"垃圾分类从家庭开始。"},{"word":"segregationist","structure":"segregation + -ist (person)","meaning":"a supporter of separation","meaningCN":"支持隔离的人","example":"The segregationist blocked the new admissions rule.","exampleCN":"主张隔离的人阻挠了新的招生规定。"},{"word":"segregative","structure":"segregate + -ive (tending to)","meaning":"tending to separate","meaningCN":"倾向于分开的","example":"The tax had a segregative effect on the housing market.","exampleCN":"这项税对住房市场产生了分离效果。"},{"word":"gregarious","structure":"grex + -arius (adjective, 'of a herd')","meaning":"living in groups","meaningCN":"群居的","example":"The seals are gregarious on the rocks.","exampleCN":"这些海豹在礁石上成群结队。"}],"derivatives":[{"word":"segregation","structure":"segregate + -ation (action or result)","meaning":"the act or system of separation","meaningCN":"隔离；分离制度"},{"word":"segregated","structure":"segregate + -ed (past participle)","meaning":"kept apart","meaningCN":"被隔离的"},{"word":"segregationist","structure":"segregation + -ist (person)","meaning":"one who supports separation","meaningCN":"隔离主义者"},{"word":"segregative","structure":"segregate + -ive (tending to)","meaning":"causing separation","meaningCN":"造成分离的"},{"word":"gregarious","structure":"grex + -arius (adjective)","meaning":"herd-loving","meaningCN":"群居的"}],"latinEntries":[{"word":"grex","structure":"grex, gregis (m., third declension)","meaning":"flock, herd","meaningCN":"羊群；畜群"},{"word":"segregare","structure":"segregare, segregavi, segregatum (verb, first conjugation)","meaning":"to separate from the herd","meaningCN":"把……从畜群中分开"},{"word":"segregatio","structure":"segregatio, segregationis (f., third declension)","meaning":"a setting apart","meaningCN":"分开；隔离"}]}},{"word":"prestige","ipa_uk":"/prɪˈstiːʒ/","ipa_us":"/ˈprestɪdʒ/","definition_zh":"威望；声誉；声望；由地位或成功带来的影响力","definition_en":"the respect and admiration that a person, group or institution receives because of status, success or perceived quality","core_image":"剧院门口的海报上，一个名字被印得比剧名还大，路人抬头时先看见那个名字","scene":"剧院门口的节目单上，一位演员的名字排在最上方，字号比剧名还大。The university's prestige attracts students from across the country.","sceneCN":"这里指「因地位与成就而获得的崇高声望」（第 1 个义项：高声望带来的普遍敬重）；句意为这所大学的声望吸引了全国各地的学生。可辨识物件：节目单、演员名字、剧院门廊、海报、路灯。","pos":[{"tag":"n.","zh":"威望；声誉（常作不可数）"},{"tag":"n.","zh":"由声望带来的影响力或优势"},{"tag":"n.","zh":"（旧用法）迷惑人的幻象；魅力"}],"collocations":[{"phrase":"gain prestige","zh":"获得声望"},{"phrase":"lose prestige","zh":"失去威望"},{"phrase":"national prestige","zh":"国家威望"},{"phrase":"occupational prestige","zh":"职业声望"},{"phrase":"prestige goods","zh":"声望商品；彰显身份的商品"},{"phrase":"prestige dialect","zh":"威望方言"}],"forms":[{"label":"不可数用法（整体声望）","form":"prestige"},{"label":"形容词（有声望的）","form":"prestigious"},{"label":"副词（令人敬重地）","form":"prestigiously"},{"label":"名词（声望性）","form":"prestigiousness"},{"label":"复合词（声望商品）","form":"prestige goods"},{"label":"复合词（威望方言）","form":"prestige dialect"}],"derivatives":[{"word":"prestigious","pos":"adj.","zh":"有声望的；令人敬重的"},{"word":"prestigiously","pos":"adv.","zh":"以有声望的方式"},{"word":"prestigiousness","pos":"n.","zh":"声望性；令人敬重的特质"},{"word":"prestidigitation","pos":"n.","zh":"手法魔术；戏法（同出拉丁「幻象」词根）"},{"word":"prestidigitator","pos":"n.","zh":"手法魔术师"},{"word":"prestige pricing","pos":"n.","zh":"声望定价（以高价标示品质）"}],"senses":[{"no":"01","title":"High standing in others' eyes","titleCN":"在他人眼中的崇高地位","definition":"the respect and admiration a person or institution enjoys because of status, achievement or perceived excellence","definitionCN":"个人或机构因地位、成就或被认可的优秀而享有的敬重与仰慕","example":"The university's prestige attracts students from across the country.","exampleCN":"这所大学的声望吸引了全国各地的学生。","why":"The word first named a glamour cast over the eyes; that dazzle later settled into lasting respect.","whyCN":"这个词最初指投在眼前的魅惑；那种眩目后来沉淀为持久的敬重。"},{"no":"02","title":"Reputation earned by success","titleCN":"由成功赢得的声誉","definition":"a reputation built by visible achievement, prizes or a record of good work","definitionCN":"由可见成就、奖项或良好记录建立的声誉","example":"The prize added prestige to an already famous laboratory.","exampleCN":"这项奖为一家本已闻名的实验室增添了声望。","why":"Honour attaches to the thing that has repeatedly proved itself, so success becomes the evidence behind prestige.","whyCN":"荣誉附着在反复证明自身的事物上，因此成功成为声望背后的证据。"},{"no":"03","title":"A rank in the social scale","titleCN":"社会等级中的位次","definition":"the relative social value assigned to an occupation, group or role","definitionCN":"社会赋予某种职业、群体或角色的相对价值","example":"Occupational prestige rankings place doctors near the top and cleaners near the bottom.","exampleCN":"职业声望排名把医生放在接近顶端，把清洁工放在接近底端。","why":"Sociology turned the word into a measurable rank: how much respect a position commands in a survey.","whyCN":"社会学把这个词变成可测量的等级：某个职位在调查中能获得多少敬重。"},{"no":"04","title":"Goods that signal standing","titleCN":"用来标示身份的商品","definition":"products bought mainly because their ownership displays wealth, taste or status","definitionCN":"主要因拥有者能借此展示财富、品味或地位而购买的产品","example":"The brand sells prestige goods rather than ordinary appliances.","exampleCN":"这个品牌卖的是彰显身份的商品，而非普通家电。","why":"If respect can be attached to a name, then a name on a product can transfer that respect to its buyer.","whyCN":"如果敬重可以附着在一个名字上，那么印在商品上的名字就能把这份敬重转给买家。"},{"no":"05","title":"A high price as a quality signal","titleCN":"以高价作为品质信号","definition":"a pricing strategy that keeps a price high so that cost itself suggests exclusivity","definitionCN":"故意维持高价、让价格本身暗示稀缺与优越的定价策略","example":"Prestige pricing keeps the watch expensive because the price is part of the message.","exampleCN":"声望定价让这款表保持高价，因为价格本身就是信息的一部分。","why":"Marketing made the dazzle calculable: the number on the tag does what the poster once did.","whyCN":"营销把这种眩目变得可计算：价签上的数字做了海报曾经做的事。"},{"no":"06","title":"The accent that carries authority","titleCN":"带权威感的方言或口音","definition":"a language variety that listeners treat as educated, powerful or socially superior","definitionCN":"被听者视为有教养、有权力或社会地位更高的一种语言变体","example":"The prestige dialect of the capital shapes school textbooks.","exampleCN":"首都的威望方言塑造了学校教科书。","why":"Speech carries status too, so the variety spoken by those with standing becomes the one others imitate.","whyCN":"言语同样携带地位，因此有地位者所说的变体成为他人模仿的对象。"},{"no":"07","title":"A nation's standing abroad","titleCN":"国家在海外的威望","definition":"the international respect a country holds, often used to justify diplomatic or military action","definitionCN":"一国在国际上所受的敬重，常被用来为外交或军事行动辩护","example":"The summit was staged to restore national prestige after the border dispute.","exampleCN":"这场峰会被安排出来，是为了在边境争端之后恢复国家威望。","why":"States borrow the personal word: a country can be seen to lose face as an individual can.","whyCN":"国家借用了个人层面的词：一个国家也像个人一样会被看作丢了脸面。"},{"no":"08","title":"An old word for a dazzling illusion","titleCN":"旧义：令人目眩的幻象","definition":"in older usage, a spell, trick or illusion that deceives the eyes","definitionCN":"旧时用法中指欺骗眼睛的魅惑、戏法或幻象","example":"In the old usage, prestige named a spell cast over the eyes.","exampleCN":"在旧用法中，这个词指投在眼前的魅惑。","why":"The Latin source meant a blinding trick; the modern sense of respect is a later softening of that dazzle.","whyCN":"拉丁来源意为使人目盲的戏法；现代的敬重义是那种眩目后来软化的结果。"}],"etymology":{"intro":{"en":"Prestige came through French from Latin praestigium 'illusion, delusion', from praestringere 'to bind or blind', built on prae- 'before' and stringere 'to bind, tighten'. The modern sense of standing developed in the nineteenth century. Dates are approximate.","cn":"prestige 经法语来自拉丁 praestigium「幻象、迷惑」，再往上出自 praestringere「绑住、使目盲」，由 prae-「在前」与 stringere「绑紧」构成。现代的声望义在十九世纪发展出来。年代均为约数。"},"items":[{"era":"LATIN STRINGERE","en":"Stringere meant 'to bind, tighten, graze'. Its pre-Latin origin is reconstructed rather than directly attested.","cn":"stringere 意为「绑紧、收紧、擦过」。它在拉丁语之前的来源属于重构，而非直接有据。"},{"era":"LATIN PRAESTRINGERE","en":"Prae- 'before' plus stringere produced praestringere, 'to bind in front, to blind or dazzle'.","cn":"prae-「在前」加 stringere 构成 praestringere「在前绑住、使目盲、使目眩」。"},{"era":"LATIN PRAESTIGIUM","en":"The noun praestigium named an illusion or juggler's trick, something that deceives the sight.","cn":"名词 praestigium 指幻象或戏法，即欺骗视觉之物。"},{"era":"OLD FRENCH PRESTIGE","en":"Old French prestige kept the sense of a deceptive glamour, and English adopted the word in the seventeenth century as a term for illusion.","cn":"古法语 prestige 保留了「骗人的魅力」之义，英语在十七世纪引入该词，用作「幻象」的名称。"},{"era":"MODERN STANDING","en":"By the nineteenth century the dazzle had become admiration: prestige now meant the impression of power and distinction a person or institution makes.","cn":"到十九世纪，眩目变成了敬慕：prestige 开始指一个人或机构给人留下的权力与卓越印象。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Latin source of stringere is a reconstruction, and no single first citation marks the shift from illusion to standing, so the dates here are approximate.","cn":"来源不确定（更深词源）：stringere 在拉丁语之前的来源属于重构形式；从幻象义到声望义的转变也没有唯一的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds words from the same blinding root; group two holds nouns for the respect a person or institution commands.","cn":"第一组是同出「使目盲」词根的词；第二组是表示人或机构所受敬重的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"prestigious","ipa":"/prɪˈstɪdʒəs/","tag":"the adjective","definition":"Describing something that commands respect; it is the adjective formed from the noun.","definitionCN":"描述享有敬重的事物；是由这个名词构成的形容词。"},{"word":"prestidigitation","ipa":"/ˌprestɪdɪdʒɪˈteɪʃən/","tag":"same illusion root","definition":"Sleight of hand, from the same Latin noun for a trick; it keeps the old sense of deceiving the eyes.","definitionCN":"手法戏法，同出表示戏法的拉丁名词；保留了「欺骗眼睛」的旧义。"},{"word":"prestidigitator","ipa":"/ˌprestɪˈdɪdʒɪteɪtə/","tag":"the performer","definition":"A conjurer who performs sleight of hand; the person who makes the illusion.","definitionCN":"表演手法戏法的魔术师；制造幻象的人。"},{"word":"prestigiously","ipa":"/prɪˈstɪdʒəsli/","tag":"the adverb","definition":"Means in a manner that earns respect, usually describing an institution's style or reputation.","definitionCN":"意为「以令人敬重的方式」，通常描述机构的风格或声誉。"}]},{"heading":"NEAR MEANING","entries":[{"word":"status","ipa":"/ˈsteɪtəs/","tag":"position in a scale","definition":"A person's rank or position within a group; prestige is the respect that may accompany that rank.","definitionCN":"个人在群体中的等级或位置；prestige 是可能伴随该等级而来的敬重。"},{"word":"reputation","ipa":"/ˌrepjuˈteɪʃən/","tag":"what people believe","definition":"The general opinion held about someone's character or work; it can be good or bad, while prestige is always favourable.","definitionCN":"他人对某人品格或工作的总体看法；可好可坏，而 prestige 总是正面的。"},{"word":"standing","ipa":"/ˈstændɪŋ/","tag":"rank among peers","definition":"One's position relative to others in a profession or community.","definitionCN":"在某职业或共同体中相对于他人的位置。"},{"word":"influence","ipa":"/ˈɪnfluəns/","tag":"power to affect","definition":"The ability to change decisions or opinions; prestige can produce influence, but the two are not the same.","definitionCN":"改变决定或意见的能力；声望可以带来影响力，但两者并不等同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real blinding root, the real derivatives and the real social phrases.","cn":"正常联想：真实的「使目盲」词根、真实的派生词与真实的社会搭配。"},"normal":[{"en":"The Latin source is a trick that blinds the eyes; from that dazzle the modern word for respect grew.","cn":"拉丁来源是使眼睛目盲的戏法；现代的敬重义正是从那种眩目生长出来。"},{"en":"The family runs prestige, prestigious, prestigiously, prestigiousness and the older pair prestidigitation and prestidigitator.","cn":"同族词包括 prestige、prestigious、prestigiously、prestigiousness，以及保留旧义的 prestidigitation 与 prestidigitator。"},{"en":"The social phrases are national prestige, occupational prestige and prestige dialect.","cn":"社会搭配有国家威望、职业声望与威望方言。"},{"en":"The marketing phrases are prestige goods and prestige pricing.","cn":"营销搭配有声望商品与声望定价。"},{"en":"The same root is visible in the older word for sleight of hand, which still means deceiving the eye.","cn":"同一词根可见于表示手法戏法的旧词，那个词至今仍指欺骗眼睛。"}],"abstract":[{"en":"Picture a poster where one name is printed larger than the play itself.","cn":"想象一张海报，一个名字印得比剧名还大。"},{"en":"Picture a price tag so high that the number itself starts to speak about quality.","cn":"想象一张价签高得让数字本身开始替品质说话。"},{"en":"Picture a stage magician whose hand is faster than the eye, leaving only admiration behind.","cn":"想象一位舞台魔术师，手比眼睛更快，最后只留下赞叹。"}]},"examples":[{"en":"The award brought prestige to a department long ignored by funders.","cn":"这个奖项为一个长期被资助方忽视的院系带来了声望。"},{"en":"Prestige pricing works only when buyers already trust the name.","cn":"声望定价只有在买家已经信任该品牌时才奏效。"},{"en":"Children quickly learn which accent carries prestige in their town.","cn":"孩子们很快学会镇上的哪种口音带有威望。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「预先」加「绑紧」——先把你眼睛绑住，让你只看见光环 → 威望、声望","word":"prestige"},"root":"prestige 经法语来自拉丁 praestigium「幻象、戏法」，源头是 praestringere「在前绑住、使目盲」= prae-「在前」+ stringere「绑紧」。stringere 的更深来源属于重构形式。","sensesIntro":{"en":"Eight senses follow one shift: a blinding illusion becomes a lasting glow around a name. The glow is then read as personal standing, earned reputation, social rank, expensive goods, a price signal, a respected accent, a nation's image and finally the old illusion itself.","cn":"八个义项沿同一次转变展开：使人目盲的幻象变成名字周围持久的光晕。这层光晕依次被读作个人地位、赢得的声誉、社会等级、昂贵商品、价格信号、受敬重的口音、国家形象，最后回到那个旧有的幻象本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a name printed larger than everything around it.","cn":"核心意象：一个名字被印得比周围一切都大。"},"chain":["BIND THE EYES","ILLUSION","GLAMOUR","RESPECT","SOCIAL RANK","QUALITY SIGNAL"],"branches":[{"senses":"01 · 08","en":"FROM SPELL TO RESPECT: the old blinding trick survives as the glow that makes a name admired.","cn":"从魅惑到敬重：古老的障眼戏法留存为让名字受仰慕的光晕。"},{"senses":"02","en":"EARNED GLOW: prizes and records turn admiration into evidence.","cn":"赢来的光：奖项与记录把仰慕变成证据。"},{"senses":"03 · 06","en":"RANK AND ACCENT: a survey can rank a job, and a city accent can carry the same rank in speech.","cn":"等级与口音：调查可以给职业排名，城市口音也能在言语中携带同样的等级。"},{"senses":"04 · 05","en":"THE PRICE TAG: a product or a number borrows the glow and sells it onward.","cn":"价签：商品或数字借来这层光，再把它卖出去。"},{"senses":"07","en":"NATIONAL FACE: a country can lose or restore the same standing an individual holds.","cn":"国家脸面：一个国家也会失去或恢复个人所拥有的同一种地位。"}]},"affixes":{"intro":{"en":"The word can be read from a Latin prefix meaning 'before', a Latin verb for binding, the noun of illusion built from them and the modern derived family.","cn":"这个单词可以按表示「在前」的拉丁前缀、表示绑紧的拉丁动词、由它们构成的名词以及现代派生词族逐段读出。"},"latinIntro":{"en":"Latin prae- and stringere give praestringere and praestigium; the noun for a trick then produced both prestige and the older word for sleight of hand.","cn":"拉丁 prae- 与 stringere 构成 praestringere 与 praestigium；表示戏法的名词随后同时衍生出 prestige 与表示手法魔术的旧词。"},"items":[{"word":"prae-","structure":"prae- (Latin prefix, 'before, in front')","meaning":"before; in front","meaningCN":"在前；在前面","example":"The prefix places the action in front of the eyes.","exampleCN":"这个前缀把动作放在眼睛前面。"},{"word":"stringere","structure":"stringere, strinxi, strictum (Latin verb, third conjugation)","meaning":"to bind, tighten, graze","meaningCN":"绑紧；收紧；擦过","example":"The verb supplies the image of something pulled tight.","exampleCN":"这个动词提供把某物拉紧的意象。"},{"word":"praestringere","structure":"prae- + stringere","meaning":"to bind in front; to blind, dazzle","meaningCN":"在前绑住；使目盲、使目眩","example":"The Latin verb described a glare that stopped the sight.","exampleCN":"这个拉丁动词描述一种挡住视线的强光。"},{"word":"praestigium","structure":"praestringere + -ium (noun ending)","meaning":"illusion, juggler's trick","meaningCN":"幻象；戏法","example":"The noun named a trick that deceived the eyes.","exampleCN":"这个名词指欺骗眼睛的戏法。"},{"word":"prestige","structure":"praestigium through Old French prestige","meaning":"standing; formerly, illusion","meaningCN":"声望；旧义为幻象","example":"The institute's prestige drew visiting scholars.","exampleCN":"该研究所的声望吸引了访问学者。"},{"word":"prestigious","structure":"prestige + -ious (full of, having)","meaning":"full of standing; highly respected","meaningCN":"享有声望的；极受敬重的","example":"She won a prestigious fellowship.","exampleCN":"她赢得了一项极具声望的研究奖金。"},{"word":"prestigiously","structure":"prestigious + -ly (adverb ending)","meaning":"in a respected manner","meaningCN":"以令人敬重的方式","example":"The journal is prestigiously edited.","exampleCN":"这份期刊的编辑水准享有盛誉。"},{"word":"prestigiousness","structure":"prestigious + -ness (quality)","meaning":"the quality of commanding respect","meaningCN":"声望性；令人敬重的特质","example":"Rankings measure the prestigiousness of a school.","exampleCN":"排行榜衡量一所学校的声望。"},{"word":"prestidigitation","structure":"praestigium + digitus (finger) + -ation","meaning":"sleight of hand","meaningCN":"手法魔术；戏法","example":"The hall applauded his prestidigitation.","exampleCN":"大厅为他的手法戏法鼓掌。"},{"word":"prestidigitator","structure":"prestidigitation + -or (one who acts)","meaning":"a sleight-of-hand performer","meaningCN":"手法魔术师","example":"The prestidigitator never showed his hands.","exampleCN":"这位魔术师从不让人看清他的手。"}],"derivatives":[{"word":"prestigious","structure":"prestige + -ious (full of)","meaning":"highly respected","meaningCN":"有声望的"},{"word":"prestigiously","structure":"prestigious + -ly (adverb ending)","meaning":"in a respected manner","meaningCN":"以有声望的方式"},{"word":"prestigiousness","structure":"prestigious + -ness (quality)","meaning":"the quality of commanding respect","meaningCN":"声望性"},{"word":"prestidigitation","structure":"praestigium + digitus + -ation","meaning":"sleight of hand","meaningCN":"手法魔术"},{"word":"prestidigitator","structure":"prestidigitation + -or (person)","meaning":"a conjurer","meaningCN":"手法魔术师"}],"latinEntries":[{"word":"stringere","structure":"stringere, strinxi, strictum (verb, third conjugation)","meaning":"to bind, tighten","meaningCN":"绑紧；收紧"},{"word":"praestringere","structure":"praestringere, praestrinxi, praestrictum (verb, third conjugation)","meaning":"to bind in front; to blind","meaningCN":"在前绑住；使目盲"},{"word":"praestigium","structure":"praestigium, praestigii (n., second declension)","meaning":"illusion, trick","meaningCN":"幻象；戏法"}]}},{"word":"authority","ipa_uk":"/ɔːˈθɒrəti/","ipa_us":"/ɔːˈθɔːrəti/","definition_zh":"权力；职权；权威机构；专家；权威性依据；当局（复数）","definition_en":"the legitimate power to give orders, make decisions or be believed, or the person or body that holds it","core_image":"墙上挂着一块木牌，写明谁有权开哪扇门，来办事的人都要先抬头看那块牌","scene":"办事处门口挂着一块牌子，写明只有值班主管能打开档案室的门。The port authority approved the new terminal after a long public review.","sceneCN":"这里指「依法设立并行使管理权的官方机构」（第 2 个义项：官方主管机构）；句意为港务管理机构在长期公众审查之后批准了新码头。可辨识物件：木牌、档案室门、值班台、印章、申请表。","pos":[{"tag":"n.","zh":"权力；职权（常作不可数）"},{"tag":"n.","zh":"官方机构；管理局"},{"tag":"n.","zh":"专家；权威（可数）"},{"tag":"n.","zh":"当局；官方（复数）"}],"collocations":[{"phrase":"have authority to do something","zh":"有权做某事"},{"phrase":"local authority","zh":"地方当局"},{"phrase":"an authority on","zh":"……方面的权威"},{"phrase":"in authority","zh":"掌权的；负责的"},{"phrase":"the authorities","zh":"当局；官方"},{"phrase":"delegate authority","zh":"授权；下放权力"}],"forms":[{"label":"不可数用法（权力）","form":"authority"},{"label":"可数复数（机构或权威人士）","form":"authorities"},{"label":"动词（授权）","form":"authorize"},{"label":"形容词（有权威的）","form":"authoritative"},{"label":"副词（以权威方式）","form":"authoritatively"},{"label":"名词（授权；批准）","form":"authorization"},{"label":"名词（作者；创始人）","form":"author"}],"derivatives":[{"word":"authorize","pos":"v.","zh":"授权；批准"},{"word":"authorization","pos":"n.","zh":"授权；批准"},{"word":"authoritative","pos":"adj.","zh":"有权威的；可信的"},{"word":"authoritatively","pos":"adv.","zh":"以权威方式"},{"word":"authoritarian","pos":"adj./n.","zh":"专制的；专制者"},{"word":"author","pos":"n.","zh":"作者；创始人（同出「使增长」词根）"}],"senses":[{"no":"01","title":"Legitimate power to command","titleCN":"依法拥有的命令权","definition":"the recognized right to give orders, make decisions and enforce obedience within a defined scope","definitionCN":"在特定范围内被承认的发布命令、作出决定并使人服从的权利","example":"The council has authority to close the road during the flood.","exampleCN":"议会有权在洪水期间封闭这条道路。","why":"The Latin noun named the influence that comes from being an originator; authority is power that traces back to a recognized source.","whyCN":"拉丁名词指作为开创者而产生的影响力；权威是能够追溯到被承认来源的权力。"},{"no":"02","title":"An official body","titleCN":"官方的管理机构","definition":"a public organization created by law to manage a service, region or industry","definitionCN":"依法设立、负责管理某项服务、区域或行业的公共机构","example":"The port authority approved the new terminal after a long public review.","exampleCN":"港务管理机构在长期公众审查之后批准了新码头。","why":"The abstract right was given a body: the power to decide became an office with a name and a budget.","whyCN":"抽象的权利被赋予一个实体：作出决定的权力变成一个有名称、有预算的机关。"},{"no":"03","title":"A recognized expert","titleCN":"被公认的专家","definition":"a person whose knowledge of a subject is widely trusted and consulted","definitionCN":"在某领域知识广受信任、常被请教的人","example":"She is a leading authority on ancient glass.","exampleCN":"她是古代玻璃研究方面的一位权威。","why":"Someone who knows a field from its origin can speak with weight, so expertise itself becomes a kind of authority.","whyCN":"从源头了解一个领域的人说话有分量，因此专业知识本身也成为一种权威。"},{"no":"04","title":"A standard that settles disputes","titleCN":"能定纷争的权威依据","definition":"a text, record or rule treated as decisive when people disagree","definitionCN":"在人们意见不一被当作决定性的文本、记录或规则","example":"The dictionary is treated as an authority on spelling in this office.","exampleCN":"在这个办公室里，词典被视为拼写方面的权威依据。","why":"A reference work stands in for a person who cannot be consulted, carrying the same weight as an expert.","whyCN":"参考书替代了无法当面请教的人，因而携带与专家相同的分量。"},{"no":"05","title":"Written permission","titleCN":"书面许可","definition":"official permission to act, often recorded in a document","definitionCN":"获准采取行动的官方许可，通常记录在文件中","example":"No one may enter the vault without written authority from the owner.","exampleCN":"没有所有者的书面许可，任何人不得进入金库。","why":"A right to act can be handed over on paper; the document is the authority in portable form.","whyCN":"行动的权利可以写在纸上转交；那份文件就是可携带的权限。"},{"no":"06","title":"The police or public officials","titleCN":"警方或政府当局","definition":"the bodies responsible for public order, used in the plural","definitionCN":"负责公共秩序的机关，常用复数形式","example":"The authorities evacuated the valley before the storm arrived.","exampleCN":"当局在风暴到来之前疏散了山谷里的人。","why":"When a whole set of offices acts together, English uses the plural to mean the officials as one force.","whyCN":"当一整套机关共同行动时，英语用复数来指作为一个整体力量的官方。"},{"no":"07","title":"A commanding personal quality","titleCN":"令人信服的个人气度","definition":"a calm assurance in someone's manner that makes others listen and obey","definitionCN":"某人举止中使人愿意倾听并服从的沉稳自信","example":"He spoke with the quiet authority of someone who had done the work himself.","exampleCN":"他说话时带着亲自做过这项工作的人才有的沉稳权威。","why":"Authority can reside in a voice rather than an office; experience lends the same weight as a title.","whyCN":"权威可以存在于声音里，而不只在职位上；经验赋予的分量与头衔相同。"},{"no":"08","title":"Power resting on accepted custom","titleCN":"依托传统习俗的权威","definition":"in sociology, power accepted because it seems to follow from long-established custom","definitionCN":"社会学中指因看似源自长期习俗而被接受的权力","example":"Traditional authority rests on the belief that old customs are binding.","exampleCN":"传统型权威建立在「旧习俗具有约束力」这一信念之上。","why":"One of the classic social types of authority: people obey because it has always been done this way.","whyCN":"这是权威的经典社会类型之一：人们服从，是因为事情一向如此。"}],"etymology":{"intro":{"en":"Authority came through Old French autorité from Latin auctoritas, 'influence, command', from auctor 'originator, promoter', itself from augere 'to increase, grow'. Dates are approximate.","cn":"authority 经古法语 autorité 来自拉丁 auctoritas「影响力、命令权」，再往上出自 auctor「开创者、推动者」，而 auctor 又来自 augere「使增长、使生长」。年代均为约数。"},"items":[{"era":"LATIN AUGERE","en":"Augere meant 'to increase, grow, enrich'. Its pre-Latin origin is reconstructed rather than directly attested.","cn":"augere 意为「使增长、使生长、使丰富」。它在拉丁语之前的来源属于重构，而非直接有据。"},{"era":"LATIN AUCTOR","en":"Auctor named the person who causes something to grow or begin: an originator, founder or seller.","cn":"auctor 指使某物生长或开始的人：开创者、创立者或出售者。"},{"era":"LATIN AUCTORITAS","en":"Auctoritas named the influence and weight that such a person carries, including the power to command and to be believed.","cn":"auctoritas 指这样一个人所携带的影响力与分量，包括命令他人与被人相信的权力。"},{"era":"OLD FRENCH AUTORITE","en":"Old French autorité carried the word into English in the fourteenth century, first naming a legal right to rule.","cn":"古法语 autorité 在十四世纪把这个词带入英语，最初指统治的法律权利。"},{"era":"EXPERT AND DOCUMENT SENSES","en":"By the eighteenth century authority also named a trusted expert and a text accepted as decisive.","cn":"到十八世纪，authority 也指受信任的专家以及被接受为决定性的文本。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of augere is a reconstruction, and no exact first citation is recorded for the expert sense, so dates here are approximate.","cn":"来源不确定（更深词源与首见年代）：augere 在拉丁语之前的来源属于重构形式；专家义也没有确切的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds words from the same root meaning growth and origination; group two holds nouns for the ability to make others act.","cn":"第一组是同出「增长与开创」词根的词；第二组是表示使他人行动的能力的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"author","ipa":"/ˈɔːθə/","tag":"the originator","definition":"A person who originates a work; it shares the Latin root but has nothing to do with command.","definitionCN":"创作作品的原创者；共享拉丁词根，却与命令权无关。"},{"word":"authorize","ipa":"/ˈɔːθəraɪz/","tag":"the verb","definition":"To give official permission; it turns the noun of power into an act of granting.","definitionCN":"给予官方许可；把表示权力的名词变成授予的动作。"},{"word":"authoritative","ipa":"/ɔːˈθɒrətətɪv/","tag":"the adjective","definition":"Describing a source that can be trusted or a tone that expects obedience.","definitionCN":"描述可信的来源或期待服从的语气。"},{"word":"authoritarian","ipa":"/ɔːˌθɒrɪˈteəriən/","tag":"the harsher relative","definition":"Describing rule that demands obedience and allows little dissent; it is a modern political formation.","definitionCN":"描述要求服从、几乎不容异议的统治；这是现代政治构词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"power","ipa":"/ˈpaʊə/","tag":"the capacity","definition":"The general ability to act or make others act; authority adds legitimacy and recognized right.","definitionCN":"行动或使他人行动的一般能力；authority 增添了正当性与被承认的权利。"},{"word":"control","ipa":"/kənˈtrəʊl/","tag":"the grip","definition":"The fact of directing or restraining something; it stresses effective command rather than rightful command.","definitionCN":"指挥或约束某物的事实；强调有效的控制，而非正当的权利。"},{"word":"jurisdiction","ipa":"/ˌdʒʊrɪsˈdɪkʃən/","tag":"the legal reach","definition":"The area or subject over which a body has legal authority.","definitionCN":"某个机构拥有法律权限的区域或事项范围。"},{"word":"expertise","ipa":"/ˈekspətaɪz/","tag":"the knowledge","definition":"Deep skill in a field; it earns the expert sense of authority but carries no right to command.","definitionCN":"某一领域的深厚技能；它赢得权威中的专家义，却不带命令权。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real root of growth and origination, the real derivatives and the real institutional phrases.","cn":"正常联想：真实的「增长与开创」词根、真实的派生词与真实的机构搭配。"},"normal":[{"en":"The Latin root means 'to increase': an author makes a work grow, and authority is the weight that growth earns.","cn":"拉丁词根意为「使增长」：作者使作品生长，而权威是这种生长赢得的重量。"},{"en":"The family runs author, authority, authorize, authorization, authoritative and authoritarian.","cn":"同族词包括 author、authority、authorize、authorization、authoritative 与 authoritarian。"},{"en":"The institutional phrases are local authority, port authority and the authorities.","cn":"机构搭配有地方当局、港务管理机构与当局。"},{"en":"The expert phrase is 'an authority on', followed by the subject.","cn":"专家搭配是「某方面的权威」，后面接具体领域。"},{"en":"The permission phrase is 'authority to do something', often in writing.","cn":"许可搭配是「做某事的权限」，常以书面形式出现。"}],"abstract":[{"en":"Picture a wooden board naming who may open which door.","cn":"想象一块木牌，写明谁可以打开哪扇门。"},{"en":"Picture a signature at the bottom of a page, turning a request into a right.","cn":"想象页底的一个签名，把请求变成权利。"},{"en":"Picture a room that falls silent when one person begins to speak.","cn":"想象一个人开口时，整间屋子安静下来。"}]},"examples":[{"en":"The agency lacks authority to inspect private homes without a warrant.","cn":"该机构无权在没有搜查令的情况下检查私人住宅。"},{"en":"As an authority on soil chemistry, she was asked to review the report.","cn":"作为土壤化学方面的权威，她被邀请审阅这份报告。"},{"en":"The authorities closed the bridge after the inspection found cracks.","cn":"检查发现裂缝后，当局关闭了这座桥。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「作者」也是「开创者」——谁开创，谁说话就有分量 → 权威、职权、当局","word":"authority"},"root":"authority 经古法语来自拉丁 auctoritas「影响力、命令权」，源头是 auctor「开创者」与 augere「使增长」。augere 在拉丁语之前的来源属于重构形式。","sensesIntro":{"en":"Eight senses follow one idea: weight that comes from a recognized source. The weight belongs to a right to command, an official body, an expert, a standard text, a written permission, the police, a personal manner and finally to custom itself.","cn":"八个义项沿一个观念展开：来自被承认来源的分量。这份分量依次属于命令权、官方机构、专家、标准文本、书面许可、警方、个人气度，最后属于习俗本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a board on the wall that says who holds the key.","cn":"核心意象：墙上的一块牌子，写明钥匙在谁手里。"},"chain":["MAKE GROW","ORIGINATOR","RIGHT TO COMMAND","OFFICIAL BODY","TRUSTED EXPERT","ACCEPTED WEIGHT"],"branches":[{"senses":"01","en":"THE RECOGNIZED RIGHT: power is legitimate only when its source can be named.","cn":"被承认的权利：只有当权力的来源可以被指名时，它才是正当的。"},{"senses":"02 · 06","en":"THE OFFICE: a right becomes a body with a name, a budget and officers who act together.","cn":"机关：权利变成一个实体，有名称、有预算，也有共同行动的官员。"},{"senses":"03 · 04","en":"THE TRUSTED VOICE: an expert and a standard text both settle questions by being believed.","cn":"可信的声音：专家与标准文本都靠被人相信来平息疑问。"},{"senses":"05","en":"THE PAPER KEY: permission travels as a document that can be shown at a door.","cn":"纸上的钥匙：许可作为一份文件流转，可以在门口出示。"},{"senses":"07 · 08","en":"THE QUIET WEIGHT: experience in a voice and custom in a society produce obedience without force.","cn":"安静的分量：声音里的经验与社会中的习俗，都能不靠武力使人服从。"}]},"affixes":{"intro":{"en":"The noun can be read from a Latin verb of growth, the person noun built on it, the abstract noun of influence and the derived family.","cn":"这个名词可以按表示增长的拉丁动词、由它构成的人称名词、表示影响力的抽象名词以及派生词族逐段读出。"},"latinIntro":{"en":"Latin augere gives auctor and auctoritas; English also built authorize, authoritative and authoritarian on the same stem.","cn":"拉丁 augere 衍生 auctor 与 auctoritas；英语又在同一词干上构成 authorize、authoritative 与 authoritarian。"},"items":[{"word":"augere","structure":"augere, auxi, auctum (Latin verb, third conjugation)","meaning":"to increase, grow","meaningCN":"使增长；使生长","example":"The Latin verb supplies the idea of making something grow.","exampleCN":"这个拉丁动词提供使某物生长的观念。"},{"word":"auctor","structure":"augere + -tor (one who causes)","meaning":"originator, founder, seller","meaningCN":"开创者；创立者；出售者","example":"The noun named the person who makes something begin.","exampleCN":"这个名词指使某物开始的人。"},{"word":"auctoritas","structure":"auctor + -itas (abstract state)","meaning":"influence, command, authority","meaningCN":"影响力；命令权；权威","example":"The abstract noun named the weight a founder carries.","exampleCN":"这个抽象名词指开创者所携带的分量。"},{"word":"authority","structure":"auctoritas through Old French autorité","meaning":"recognized power or expertise","meaningCN":"被承认的权力或专业权威","example":"The council has authority over the harbour.","exampleCN":"议会对港口拥有管辖权。"},{"word":"author","structure":"auctor through Old French autor","meaning":"originator of a work","meaningCN":"作品的创作者","example":"The author revised the manuscript twice.","exampleCN":"作者两次修改手稿。"},{"word":"authorize","structure":"authority + -ize (make or grant)","meaning":"to give official permission","meaningCN":"给予官方许可","example":"Only the director can authorize the payment.","exampleCN":"只有主管可以批准这笔付款。"},{"word":"authorization","structure":"authorize + -ation (action or result)","meaning":"official permission","meaningCN":"授权；批准","example":"The purchase needs written authorization.","exampleCN":"这笔采购需要书面授权。"},{"word":"authoritative","structure":"authority + -ative (tending to)","meaning":"carrying trusted weight","meaningCN":"具有权威分量的","example":"The guide is the most authoritative source on the subject.","exampleCN":"这本指南是该主题最具权威性的来源。"},{"word":"authoritatively","structure":"authoritative + -ly (adverb ending)","meaning":"in a commanding or trusted manner","meaningCN":"以权威的方式","example":"She spoke authoritatively about the risks.","exampleCN":"她以权威的口吻谈论这些风险。"},{"word":"authoritarian","structure":"authority + -arian (person or system)","meaning":"demanding obedience with little dissent","meaningCN":"要求服从、几乎不容异议的","example":"The regime grew increasingly authoritarian.","exampleCN":"这个政权变得越来越专制。"}],"derivatives":[{"word":"authorize","structure":"authority + -ize (make or grant)","meaning":"to grant permission","meaningCN":"授权；批准"},{"word":"authorization","structure":"authorize + -ation (action or result)","meaning":"official permission","meaningCN":"授权"},{"word":"authoritative","structure":"authority + -ative (tending to)","meaning":"trusted and commanding","meaningCN":"有权威的"},{"word":"authoritarian","structure":"authority + -arian (person or system)","meaning":"strictly controlling","meaningCN":"专制的"},{"word":"author","structure":"Latin auctor through French","meaning":"originator of a work","meaningCN":"作者；创始人"}],"latinEntries":[{"word":"augere","structure":"augere, auxi, auctum (verb, third conjugation)","meaning":"to increase, grow","meaningCN":"使增长"},{"word":"auctor","structure":"auctor, auctoris (m., third declension)","meaning":"originator, founder","meaningCN":"开创者；创立者"},{"word":"auctoritas","structure":"auctoritas, auctoritatis (f., third declension)","meaning":"influence, authority","meaningCN":"影响力；权威"}]}},{"word":"power","ipa_uk":"/ˈpaʊə/","ipa_us":"/ˈpaʊər/","definition_zh":"力量；权力；能力；电力；幂（数学）；（镜头的）放大倍率","definition_en":"the ability to act, control or influence, or the energy and mathematical capacity that make action possible","core_image":"一只手握住总闸的把手往下一压，整条街的灯同时亮起","scene":"变电站里，值班员把总闸推上去，整片街区的灯同时亮了。A fallen line cut the power to three streets before dawn.","sceneCN":"这里指「供给电器的电力」（第 4 个义项：电力供应）；句意为天亮前一条掉落的电线切断了三条街的供电。可辨识物件：总闸、变电站、电线、街灯、工具箱。","pos":[{"tag":"n.","zh":"力量；权力（常作不可数）"},{"tag":"n.","zh":"能力；作用力"},{"tag":"n.","zh":"电力；动力"},{"tag":"n.","zh":"幂；乘方（数学）"},{"tag":"vt.","zh":"给……提供动力；推动"}],"collocations":[{"phrase":"political power","zh":"政治权力"},{"phrase":"the power to do something","zh":"做某事的能力或权力"},{"phrase":"power supply","zh":"电源；供电"},{"phrase":"nuclear power","zh":"核能；核电"},{"phrase":"to the power of","zh":"……次方"},{"phrase":"power of attorney","zh":"授权委托书"}],"forms":[{"label":"不可数用法（力量或电力）","form":"power"},{"label":"可数复数（多种权力或强国）","form":"powers"},{"label":"形容词（强大的）","form":"powerful"},{"label":"形容词（无力的）","form":"powerless"},{"label":"副词（强大地）","form":"powerfully"},{"label":"动词（提供动力）","form":"power"},{"label":"名词（潜力；潜能）","form":"potential"}],"derivatives":[{"word":"powerful","pos":"adj.","zh":"强大的；有影响力的"},{"word":"powerless","pos":"adj.","zh":"无力的；无权势的"},{"word":"powerfully","pos":"adv.","zh":"强有力地"},{"word":"powered","pos":"adj.","zh":"由……驱动的"},{"word":"potent","pos":"adj.","zh":"有效的；强有力的（同出「能」词根）"},{"word":"potential","pos":"n./adj.","zh":"潜力；潜在的"}],"senses":[{"no":"01","title":"Physical force","titleCN":"物理上的力量","definition":"the strength or energy that something uses to move, break or hold another thing","definitionCN":"某物用于移动、破坏或固定另一物的力量或能量","example":"The storm's power tore the roof from the shed.","exampleCN":"风暴的力量把棚屋的屋顶掀掉了。","why":"The Latin source means 'to be able'; the first kind of ability is the brute ability to move matter.","whyCN":"拉丁来源意为「能够」；最基础的能力就是移动物体的蛮力。"},{"no":"02","title":"Control over people and decisions","titleCN":"对人及决策的控制权","definition":"the capacity to make others act or to determine collective decisions, whether through office, money or numbers","definitionCN":"使他人行动或决定集体事务的能力，可来自职位、金钱或人数","example":"The union used its power to stop the layoffs.","exampleCN":"工会动用它的力量阻止了裁员。","why":"Ability directed at people becomes influence; whoever can change what others do holds power.","whyCN":"指向他人的能力变成影响力；能改变他人行为的人就握有权力。"},{"no":"03","title":"Capacity to produce an effect","titleCN":"产生效果的能力","definition":"the ability of a thing, substance or person to produce a particular effect","definitionCN":"某物、某物质或某人产生特定效果的能力","example":"The drug has the power to relieve pain within minutes.","exampleCN":"这种药能在几分钟内缓解疼痛。","why":"The same 'can' is at work here: the question is not who commands but what a thing is able to do.","whyCN":"这里仍是同一个「能」：问题不是谁在下命令，而是某物能够做成什么。"},{"no":"04","title":"Electricity supplied to a place","titleCN":"供给某处的电力","definition":"electric energy supplied to homes, machines or a network","definitionCN":"供给住宅、机器或电网的电能","example":"A fallen line cut the power to three streets before dawn.","exampleCN":"天亮前一条掉落的电线切断了三条街的供电。","why":"The industrial age narrowed the general word to the energy that makes machines able to work.","whyCN":"工业时代把这一通用词收窄为让机器得以运转的能量。"},{"no":"05","title":"An exponent in mathematics","titleCN":"数学中的幂指数","definition":"the number that shows how many times a base is multiplied by itself","definitionCN":"表示一个底数被自身相乘多少次的数","example":"Two raised to the fifth power equals thirty-two.","exampleCN":"二的五次方等于三十二。","why":"Repeated multiplication multiplies capacity, so mathematics named the count of multiplications by the same word.","whyCN":"重复相乘使能力成倍增长，因此数学用同一个词来命名相乘的次数。"},{"no":"06","title":"Magnification of a lens","titleCN":"镜头的放大倍率","definition":"the factor by which an optical instrument enlarges a distant object","definitionCN":"光学仪器把远处物体放大的倍数","example":"A ten-power lens brings the distant ridge into view.","exampleCN":"十倍的镜头把远处的山脊拉到眼前。","why":"A lens multiplies the reach of the eye, so its factor is also called its power.","whyCN":"镜头把眼睛的触及范围成倍扩大，因此它的倍数也被称为它的力量。"},{"no":"07","title":"A strong state on the world stage","titleCN":"国际舞台上的强国","definition":"a country able to influence other states through military, economic or diplomatic capacity","definitionCN":"能通过军事、经济或外交能力影响他国的国家","example":"The two powers agreed to limit naval forces in the region.","exampleCN":"两个强国同意限制该地区的海军力量。","why":"States are treated as single actors, so the ability to act becomes a nation's power.","whyCN":"国家被当作单一行动者，因此行动的能力就成为一个国家的力量。"},{"no":"08","title":"Legal authority to act for another","titleCN":"代他人行动的法定权限","definition":"a legal document or status allowing one person to act on another's behalf","definitionCN":"允许一个人代另一人行动的法定文件或身份","example":"The daughter held power of attorney for her father.","exampleCN":"女儿持有父亲的授权委托书。","why":"Law borrowed the word for a delegated ability: the agent can act because the principal's capacity has been transferred.","whyCN":"法律借用这个词表示被授予的能力：代理人能行动，是因为本人的能力被转交了过来。"}],"etymology":{"intro":{"en":"Power came through Old French poeir from Vulgar Latin potere, from Latin posse 'to be able', built on potis 'able' and esse 'to be'. Dates are approximate.","cn":"power 经古法语 poeir 来自通俗拉丁 potere，再往上出自拉丁 posse「能够」，由 potis「有能力的」与 esse「是」构成。年代均为约数。"},"items":[{"era":"LATIN POTIS","en":"Potis meant 'able, capable, powerful'. Its pre-Latin origin is reconstructed rather than directly attested.","cn":"potis 意为「有能力的、能干的、有力量的」。它在拉丁语之前的来源属于重构，而非直接有据。"},{"era":"LATIN POSSE","en":"Potis plus esse produced posse, the verb 'to be able, can'.","cn":"potis 加 esse 构成 posse，即动词「能够、可以」。"},{"era":"VULGAR LATIN POTERE","en":"Everyday Latin reshaped the verb as potere, which became the ordinary verb for ability in the Romance languages.","cn":"通俗拉丁把这个动词改形为 potere，它后来成为罗曼语族中表示能力的常用动词。"},{"era":"OLD FRENCH POEIR","en":"Old French poeir carried both the verb and a noun for ability into English in the thirteenth century.","cn":"古法语 poeir 在十三世纪把动词以及表示能力的名词一并带入英语。"},{"era":"TECHNICAL SENSES","en":"Mathematics adopted the word for an exponent in the sixteenth century, and the electrical sense followed with the power grid in the nineteenth.","cn":"数学在十六世纪用这个词指幂指数；随着电网出现，电力义在十九世纪跟进。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of potis is a reconstruction, and no single first citation is fixed for the electrical sense, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：potis 在拉丁语之前的来源属于重构形式；电力义也没有唯一的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds words from the same 'able' root; group two holds nouns for strength or influence seen from other angles.","cn":"第一组是同出「能够」词根的词；第二组是从其他角度表示力量或影响力的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"powerful","ipa":"/ˈpaʊəfəl/","tag":"the adjective","definition":"Having great strength or influence; the adjective describes what the noun possesses.","definitionCN":"拥有强大力量或影响力的；形容词描述名词所拥有的东西。"},{"word":"powerless","ipa":"/ˈpaʊələs/","tag":"the opposite","definition":"Having no ability to act or change a situation; it is the direct negation of the noun.","definitionCN":"没有能力行动或改变处境的；是这个名词的直接否定。"},{"word":"potent","ipa":"/ˈpəʊtənt/","tag":"same able root","definition":"Means strong in effect, especially of a drug or argument; it shares the Latin root of ability.","definitionCN":"意为「效力强的」，尤指药物或论证；共享表示能力的拉丁词根。"},{"word":"potential","ipa":"/pəˈtenʃəl/","tag":"capacity not yet used","definition":"An ability that exists but has not yet been exercised; it is power still folded up.","definitionCN":"已存在但尚未施展的能力；是仍折叠未用的力量。"}]},{"heading":"NEAR MEANING","entries":[{"word":"strength","ipa":"/streŋθ/","tag":"bodily or structural force","definition":"The physical quality of being strong; it covers muscles and materials rather than decisions.","definitionCN":"身体或结构上的强壮；覆盖肌肉与材料，而非决策。"},{"word":"force","ipa":"/fɔːs/","tag":"energy that moves","definition":"Physical energy acting on an object, or organized pressure used to compel.","definitionCN":"作用于物体的物理能量，或用来强迫的有组织压力。"},{"word":"authority","ipa":"/ɔːˈθɒrəti/","tag":"legitimate right","definition":"Power that is recognized as rightful; power alone can be held without legitimacy.","definitionCN":"被承认正当的权力；单纯的力量可以在缺乏正当性的情况下被持有。"},{"word":"influence","ipa":"/ˈɪnfluəns/","tag":"quiet effect","definition":"The ability to change opinions or decisions without direct command.","definitionCN":"不靠直接命令而改变意见或决定的能力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real 'able' root, the real derivatives and the real technical phrases.","cn":"正常联想：真实的「能够」词根、真实的派生词与真实的技术搭配。"},"normal":[{"en":"The Latin verb means 'to be able'; every sense is a kind of ability, from moving a roof to lighting a street.","cn":"拉丁动词意为「能够」；每个义项都是一种能力，从掀翻屋顶到点亮街道。"},{"en":"The family runs power, powerful, powerless, powerfully, powered, potent and potential.","cn":"同族词包括 power、powerful、powerless、powerfully、powered、potent 与 potential。"},{"en":"The political phrases are political power, balance of power and the powers.","cn":"政治搭配有政治权力、力量均势与列强。"},{"en":"The technical phrases are power supply, nuclear power and to the power of.","cn":"技术搭配有电源、核能与……次方。"},{"en":"The legal phrase is power of attorney, where one person acts for another.","cn":"法律搭配是授权委托书，即一个人代另一个人行动。"}],"abstract":[{"en":"Picture a hand on a master switch that lights a whole street at once.","cn":"想象一只手按在总闸上，一下点亮整条街。"},{"en":"Picture a number multiplied by itself again and again until it fills the page.","cn":"想象一个数反复自乘，直到写满整页。"},{"en":"Picture a signature that lets one person stand in another's shoes at a counter.","cn":"想象一个签名，让一个人在柜台前站进另一个人的位置。"}]},"examples":[{"en":"The engine's power is measured in kilowatts rather than horses.","cn":"这台发动机的功率用千瓦而非马力来衡量。"},{"en":"The committee has no power to change the budget on its own.","cn":"委员会无权自行改变预算。"},{"en":"Three to the fourth power is eighty-one.","cn":"三的四次方是八十一。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「能够」加「力」——能推动物体、能让人服从、能让灯亮 → 力量、权力、电力","word":"power"},"root":"power 经古法语来自通俗拉丁 potere，源头是拉丁 posse「能够」= potis「有能力的」+ esse「是」。potis 在拉丁语之前的来源属于重构形式。","sensesIntro":{"en":"Eight senses follow one root idea, 'being able': able to move matter, able to command people, able to produce an effect, able to supply electricity, able to multiply a number, able to enlarge an image, able to act as a state, able to act for another person.","cn":"八个义项沿同一个词根观念「能够」展开：能移动物体、能命令他人、能产生效果、能供电、能使数字成倍、能放大图像、能作为国家行动、能代他人行动。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand on a master switch.","cn":"核心意象：一只手按在总闸上。"},"chain":["BE ABLE","MOVE MATTER","COMMAND PEOPLE","MAKE EFFECT","SUPPLY ENERGY","MEASURED CAPACITY"],"branches":[{"senses":"01","en":"THE BODY'S ABILITY: force that moves or breaks matter is the first meaning of being able.","cn":"身体的能力：移动或破坏物体的力量，是「能够」的第一层含义。"},{"senses":"02 · 07","en":"THE SOCIAL ABILITY: a union or a state acts because people and institutions can be made to move.","cn":"社会的能力：工会或国家能行动，是因为可以使人及机构动起来。"},{"senses":"03","en":"THE EFFECT: a drug or a word is powerful when it can change a body or a mind.","cn":"效果：药物或言辞之所以有力，是因为它能改变身体或心智。"},{"senses":"04","en":"THE CURRENT: the industrial age gave the general word to the energy that runs machines.","cn":"电流：工业时代把这一通用词交给了驱动机器的能量。"},{"senses":"05 · 06 · 08","en":"THE MEASURED AND DELEGATED: an exponent multiplies a number, a lens multiplies sight, and a legal document transfers capacity.","cn":"可计量与可转交：指数使数字成倍，镜头使视力成倍，法律文件则转交能力。"}]},"affixes":{"intro":{"en":"The word can be read from a Latin adjective of ability, the verb 'to be', the compound verb they form and the modern derived family.","cn":"这个单词可以按表示能力的拉丁形容词、表示「是」的动词、由它们合成的动词以及现代派生词族逐段读出。"},"latinIntro":{"en":"Latin potis and esse give posse, the source of power; the same stem yields potent, potential and the noun potentia.","cn":"拉丁 potis 与 esse 构成 posse，也就是 power 的来源；同一词干还衍生 potent、potential 与名词 potentia。"},"items":[{"word":"potis","structure":"potis, -e (Latin adjective, 'able')","meaning":"able, capable","meaningCN":"有能力的；能干的","example":"The adjective supplied the idea of capability.","exampleCN":"这个形容词提供「有能力」的观念。"},{"word":"esse","structure":"esse (Latin verb, 'to be')","meaning":"to be","meaningCN":"是；存在","example":"The verb completes the compound meaning 'to be able'.","exampleCN":"这个动词补足「能够」的合成含义。"},{"word":"posse","structure":"potis + esse (Latin verb)","meaning":"to be able, can","meaningCN":"能够；可以","example":"The Latin verb stated plain ability.","exampleCN":"这个拉丁动词表示单纯的能力。"},{"word":"potentia","structure":"potens + -ia (abstract noun)","meaning":"power, capacity","meaningCN":"力量；能力","example":"The noun named capacity as a quality.","exampleCN":"这个名词指作为一种性质的能力。"},{"word":"power","structure":"potere through Old French poeir","meaning":"ability, control, energy","meaningCN":"能力；权力；能量","example":"The motor lost power on the climb.","exampleCN":"马达在爬坡时失去了动力。"},{"word":"powerful","structure":"power + -ful (full of)","meaning":"full of strength or influence","meaningCN":"充满力量或影响力的","example":"A powerful storm crossed the coast.","exampleCN":"一场强风暴越过海岸。"},{"word":"powerless","structure":"power + -less (without)","meaning":"without ability to act","meaningCN":"无力行动的","example":"The villagers felt powerless against the landslide.","exampleCN":"村民面对山体滑坡感到无能为力。"},{"word":"powerfully","structure":"powerful + -ly (adverb ending)","meaning":"with great force","meaningCN":"强有力地","example":"The speech argued powerfully for the bridge.","exampleCN":"这场演讲为这座桥做了有力的论证。"},{"word":"powered","structure":"power + -ed (having)","meaning":"driven by a specified source","meaningCN":"由某种能源驱动的","example":"The shed runs on solar-powered lights.","exampleCN":"棚屋使用太阳能驱动的灯。"},{"word":"potent","structure":"potens, potentis (Latin adjective)","meaning":"strong in effect","meaningCN":"效力强的","example":"The drug is potent at a very low dose.","exampleCN":"这种药在很低的剂量下就有效。"}],"derivatives":[{"word":"powerful","structure":"power + -ful (full of)","meaning":"full of strength","meaningCN":"强大的"},{"word":"powerless","structure":"power + -less (without)","meaning":"without ability","meaningCN":"无力的"},{"word":"powerfully","structure":"powerful + -ly (adverb ending)","meaning":"with great force","meaningCN":"强有力地"},{"word":"powered","structure":"power + -ed (having)","meaning":"driven by a source","meaningCN":"由某种能源驱动的"},{"word":"potential","structure":"potentia + -al (relating to)","meaning":"existing as a capacity","meaningCN":"潜在的；潜力"}],"latinEntries":[{"word":"potis","structure":"potis, -e (adjective)","meaning":"able, capable","meaningCN":"有能力的"},{"word":"posse","structure":"posse, potui (verb, irregular)","meaning":"to be able","meaningCN":"能够"},{"word":"potentia","structure":"potentia, potentiae (f., first declension)","meaning":"power, capacity","meaningCN":"力量；能力"}]}},{"word":"power structure","ipa_uk":"/ˈpaʊə ˌstrʌktʃə/","ipa_us":"/ˈpaʊər ˌstrʌktʃər/","definition_zh":"权力结构；一个社会、组织或群体中权力与影响力的分布方式","definition_en":"the arrangement through which power and influence are distributed among people, groups and institutions","core_image":"一张楼房剖面图：顶层只有几间大办公室，越往下隔间越多，箭头一层层指向上方","scene":"会议室墙上挂着一张组织图，顶层只有三个房间，越往下隔间越多，箭头逐层指向上方。The power structure of the university kept most decisions in the hands of a small council.","sceneCN":"这里指「一个组织中权力如何分布的总体格局」（第 1 个义项：权力分布的总格局）；句意为这所大学的权力结构把大多数决定交到一个小型理事会手中。可辨识物件：组织图、顶层办公室、隔间、箭头、会议桌。","pos":[{"tag":"n.","zh":"权力结构（社会或组织的权力分布，常作可数）"},{"tag":"n.","zh":"具体的权力层级或权力网络（可数）"}],"collocations":[{"phrase":"the existing power structure","zh":"现有的权力结构"},{"phrase":"shift the power structure","zh":"改变权力结构"},{"phrase":"challenge the power structure","zh":"挑战权力结构"},{"phrase":"formal power structure","zh":"正式权力结构"},{"phrase":"the power structure of a society","zh":"一个社会的权力结构"},{"phrase":"reform the power structure","zh":"改革权力结构"}],"forms":[{"label":"不可数用法（整体格局）","form":"power structure"},{"label":"可数复数（多种权力结构）","form":"power structures"},{"label":"名词（权力）","form":"power"},{"label":"名词（结构）","form":"structure"},{"label":"形容词（结构性的）","form":"structural"},{"label":"动词（重组结构）","form":"restructure"}],"derivatives":[{"word":"power","pos":"n./v.","zh":"权力；力量；提供动力"},{"word":"structure","pos":"n./v.","zh":"结构；构造；组织"},{"word":"structural","pos":"adj.","zh":"结构的；结构性的"},{"word":"structurally","pos":"adv.","zh":"在结构上"},{"word":"restructure","pos":"v.","zh":"重组；调整结构"},{"word":"infrastructure","pos":"n.","zh":"基础设施（同出「建造」词根）"}],"senses":[{"no":"01","title":"Who holds power in a society","titleCN":"一个社会中谁掌握权力","definition":"the overall distribution of authority and influence among the groups that make up a society","definitionCN":"构成一个社会的各群体之间权力与影响力的总体分布","example":"The power structure of the university kept most decisions in the hands of a small council.","exampleCN":"这所大学的权力结构把大多数决定交到一个小型理事会手中。","why":"Power is held in patterns, not only in single hands; structure names the shape those patterns make.","whyCN":"权力以格局而非单只手的方式被持有；结构一词命名的正是这些格局形成的形状。"},{"no":"02","title":"The formal chain of command","titleCN":"正式的指挥链条","definition":"the official hierarchy that shows who reports to whom and who may decide what","definitionCN":"显示谁向谁汇报、谁可以决定什么的官方层级","example":"The company's power structure places the board above every division.","exampleCN":"这家公司的权力结构把董事会置于所有部门之上。","why":"An organization draws its power as a building draws its floors: each level rests on the one below and answers to the one above.","whyCN":"组织安排权力就像建筑安排楼层：每一层压在下一层之上，又向上一层负责。"},{"no":"03","title":"The informal web behind the chart","titleCN":"组织图背后的非正式网络","definition":"the real pattern of influence created by relationships, access and reputation rather than by titles","definitionCN":"由关系、接近机会与声誉而非头衔形成的真实影响力格局","example":"Informal power structures often matter more than the printed chart.","exampleCN":"非正式的权力结构常常比印出来的组织图更重要。","why":"A building has hidden corridors as well as official stairs; influence travels through both.","whyCN":"建筑除了正式楼梯还有隐蔽通道；影响力也沿两条路流动。"},{"no":"04","title":"The division of constitutional powers","titleCN":"宪制权力的分立","definition":"the arrangement that assigns authority to separate branches or levels of government","definitionCN":"把权限分配给不同政府分支或层级的安排","example":"The constitutional power structure divides authority among three branches.","exampleCN":"宪制权力结构把权限分给三个分支。","why":"Political theory uses the word for the architecture of a state, where each branch is a load-bearing wall.","whyCN":"政治理论用这个词指国家的建筑结构，每个分支都是一面承重墙。"},{"no":"05","title":"Who decides inside a household","titleCN":"家庭内部谁作决定","definition":"the pattern of decision-making and influence among members of a family or household","definitionCN":"家庭成员之间作决定与施加影响的格局","example":"In many households the power structure shifts when an elder moves in.","exampleCN":"在许多家庭里，长辈搬进来之后，权力结构就会改变。","why":"The same architecture appears at a smaller scale: every group that shares a roof also shares a way of deciding.","whyCN":"同样的建筑结构以更小的尺度出现：每个共住一个屋檐下的群体，也共享一套作决定的方式。"},{"no":"06","title":"Control written into ownership","titleCN":"写进股权安排的控股权","definition":"the way share classes, voting rules and board seats fix who controls a company","definitionCN":"通过股份类别、投票规则与董事席位固定谁控制公司的方式","example":"A dual-class share system entrenches the power structure of the founding family.","exampleCN":"双重股权制度巩固了创始家族的权力结构。","why":"Corporate law turns influence into a floor plan: certain shares carry keys to certain rooms.","whyCN":"公司法把影响力变成一张楼层图：某些股份带着某些房间的钥匙。"},{"no":"07","title":"The order between states","titleCN":"国家之间的权力格局","definition":"the distribution of military, economic and diplomatic power among states in a region or the world","definitionCN":"军事、经济与外交力量在一个地区或全世界各国之间的分布","example":"The postwar power structure rested on two blocs and a set of alliances.","exampleCN":"战后的权力结构建立在两个阵营与一系列联盟之上。","why":"International relations borrows the architectural word for a balance that is built, maintained and sometimes demolished.","whyCN":"国际关系借用这个建筑词汇，指一种被建造、维护、有时又被拆除的均势。"},{"no":"08","title":"The structure that decides whose knowledge counts","titleCN":"决定谁的知识算数的结构","definition":"the unspoken arrangement that gives some voices the right to define problems and others no hearing","definitionCN":"让某些声音有权界定问题、另一些声音却无人倾听的隐性安排","example":"The report questioned the power structure that decides whose expertise counts.","exampleCN":"这份报告质疑了决定谁的专业意见算数的权力结构。","why":"Even a discussion has a floor plan: some seats face the table, others face the wall.","whyCN":"连一场讨论也有自己的平面图：有些座位朝向长桌，另一些只能朝向墙壁。"}],"etymology":{"intro":{"en":"Power structure joins power, from Latin posse 'to be able', with structure, from Latin structura 'a building, an arrangement', from struere 'to pile up, build'. The compound is a modern social-science term. Dates are approximate.","cn":"power structure 由 power 与 structure 组合而成。power 源自拉丁 posse「能够」；structure 源自拉丁 structura「建筑物、安排」，再往上出自 struere「堆起、建造」。这个复合词是现代社会科学术语。年代均为约数。"},"items":[{"era":"LATIN POSSE","en":"Posse meant 'to be able', built on potis 'able' and esse 'to be'. Its pre-Latin elements are reconstructed.","cn":"posse 意为「能够」，由 potis「有能力的」与 esse「是」构成。它在拉丁语之前的成分属于重构。"},{"era":"LATIN STRUERE","en":"Struere meant 'to pile up, build, arrange'. Its deeper origin is not established; the building root proposed for it is a reconstruction.","cn":"struere 意为「堆起、建造、安排」。其更深来源未得到证明；为它提出的「建造」词根属于重构形式。"},{"era":"LATIN STRUCTURA","en":"Structura named the act of building and the resulting arrangement, from which English took the idea of a built framework.","cn":"structura 指建造的动作以及由此形成的安排，英语从它取得「构建起来的框架」这一观念。"},{"era":"ENGLISH POWER AND STRUCTURE","en":"Power entered English through Old French in the thirteenth century; structure came from Latin in the fifteenth and named both buildings and organized wholes.","cn":"power 在十三世纪经古法语进入英语；structure 在十五世纪来自拉丁语，既指建筑，也指有组织的整体。"},{"era":"SOCIAL SCIENCE COMPOUND","en":"In the twentieth century the two words were joined to name the durable pattern of influence in a society or institution.","cn":"到二十世纪，这两个词被组合起来，指一个社会或机构中持久的影响力格局。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin sources of potis and struere are reconstructions, and no exact first citation is fixed for the compound, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：potis 与 struere 在拉丁语之前的来源属于重构形式；这个复合词也没有确切的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the two building blocks and their relatives; group two holds terms for an order of influence or command.","cn":"第一组是两个构词成分及其亲属词；第二组是表示影响力或命令秩序的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"power","ipa":"/ˈpaʊə/","tag":"the first element","definition":"The ability to act or compel; the compound names how that ability is arranged.","definitionCN":"行动或强迫的能力；这个复合词指这种能力如何被安排。"},{"word":"structure","ipa":"/ˈstrʌktʃə/","tag":"the second element","definition":"A built arrangement of parts; alone it can describe a bridge as easily as an institution.","definitionCN":"各部分构建起来的安排；单独使用时既可描述桥梁，也可描述机构。"},{"word":"structural","ipa":"/ˈstrʌktʃərəl/","tag":"the adjective","definition":"Relating to the arrangement of parts; structural power is power built into a system rather than held by a person.","definitionCN":"与部分之间的安排有关；结构性权力是嵌入制度的权力，而非个人持有的权力。"},{"word":"restructure","ipa":"/ˌriːˈstrʌktʃə/","tag":"the verb","definition":"To rebuild the arrangement of an organization, often changing who reports to whom.","definitionCN":"重建一个组织的安排，常改变谁向谁汇报。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hierarchy","ipa":"/ˈhaɪərɑːki/","tag":"ranked levels","definition":"A system of levels in which each rank answers to the one above; it is one common form of power structure.","definitionCN":"每一等级向上一级负责的层级体系；它是权力结构的一种常见形态。"},{"word":"pecking order","ipa":"/ˈpekɪŋ ɔːdə/","tag":"informal ranking","definition":"The unofficial order of status and precedence in a group, often visible in small behaviours.","definitionCN":"群体中非正式的地位与优先次序，常从小举动中看出来。"},{"word":"governance","ipa":"/ˈɡʌvənəns/","tag":"the process of ruling","definition":"The rules and practices by which an organization or state is directed; it names the process, not the distribution.","definitionCN":"指导一个组织或国家的规则与实践；指过程，而非分布。"},{"word":"regime","ipa":"/reɪˈʒiːm/","tag":"a ruling system","definition":"A particular government or set of ruling arrangements; it is more political and less analytical than power structure.","definitionCN":"特定的政府或一套统治安排；比 power structure 更政治化，分析性较弱。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real roots, the real derivatives and the real institutional phrases.","cn":"正常联想：两个真实词根、真实的派生词与真实的机构搭配。"},"normal":[{"en":"The first word means 'to be able' and the second means 'built arrangement', so the compound is ability arranged into a lasting shape.","cn":"第一个词意为「能够」，第二个词意为「建造起来的安排」，因此整个复合词就是被安排成持久形状的能力。"},{"en":"The family runs power, structure, structural, structurally, restructure and infrastructure.","cn":"同族词包括 power、structure、structural、structurally、restructure 与 infrastructure。"},{"en":"The critical phrases are challenge the power structure, shift the power structure and reform the power structure.","cn":"批判性搭配有挑战权力结构、改变权力结构与改革权力结构。"},{"en":"The descriptive phrases are formal power structure and the power structure of a society.","cn":"描述性搭配有正式权力结构与一个社会的权力结构。"},{"en":"The same building root appears in infrastructure, which names the built supports beneath a system.","cn":"同一「建造」词根出现在 infrastructure 中，那个词指体系下方建造起来的支撑设施。"}],"abstract":[{"en":"Picture a cutaway building where the top floor has three rooms and the ground floor has a hundred.","cn":"想象一座剖面楼，顶层只有三个房间，底层却有一百个。"},{"en":"Picture arrows on a chart all pointing upward to the same small office.","cn":"想象组织图上的箭头全都指向上方的同一间小办公室。"},{"en":"Picture a meeting where the seats facing the table decide what the others are allowed to say.","cn":"想象一场会议，朝向长桌的座位决定其余人能说什么。"}]},"examples":[{"en":"Reformers argued that the old power structure blocked every proposal for change.","cn":"改革者认为旧的权力结构阻挠了每一项变革提案。"},{"en":"The family's power structure changed after the youngest daughter took over the accounts.","cn":"最小的女儿接管账目之后，这个家庭的权力结构改变了。"},{"en":"Any study of a bureaucracy must map its formal and informal power structures.","cn":"任何对官僚机构的研究都必须描绘其正式与非正式的权力结构。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「权力」加「结构」——谁在上面、谁在下面、箭头指向谁 → 权力结构、权力格局","word":"power structure"},"root":"power structure 由 power 与 structure 组合而成。power 源自拉丁 posse「能够」；structure 源自拉丁 structura「建筑物、安排」，再往上出自 struere「建造」。potis 与 struere 的更深来源均属重构形式。","sensesIntro":{"en":"Eight senses follow one architectural image: an arrangement of levels tells who stands above whom. The arrangement is applied to a society, a company, an informal network, a constitution, a household, a shareholding scheme, the world of states and finally to the seating of a discussion.","cn":"八个义项沿同一个建筑意象展开：一层层的安排说明谁站在谁之上。这个安排依次用于社会、公司、非正式网络、宪制、家庭、股权方案、国家格局，最后用于一场讨论的座次。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cutaway building with arrows running upward.","cn":"核心意象：一座剖面楼，箭头一路向上。"},"chain":["TOP OFFICES","REPORTING LINES","HIDDEN CORRIDORS","SEPARATE BRANCHES","SHARED ROOF","WORLD ORDER"],"branches":[{"senses":"01","en":"THE WHOLE SHAPE: the first sense asks who holds power across a society, not in one office.","cn":"整体形状：第一个义项追问整个社会中谁掌握权力，而非某一间办公室。"},{"senses":"02 · 06","en":"THE DRAWN FLOOR PLAN: official reporting lines and share classes fix the same structure on paper.","cn":"画出的楼层图：正式汇报线与股份类别在纸面上固定了同一种结构。"},{"senses":"03 · 08","en":"THE HIDDEN PASSAGE: relationships and the right to define a problem move influence off the printed chart.","cn":"隐蔽通道：关系与界定问题的权利，把影响力带离印好的组织图。"},{"senses":"04","en":"THE LOAD-BEARING WALLS: a constitution assigns authority to separate branches so that none carries the whole roof.","cn":"承重墙：宪法把权限分给不同分支，使没有任何一方独自撑起整个屋顶。"},{"senses":"05 · 07","en":"THE SMALL AND LARGE ROOF: a household and a world of states both settle who decides under one shared frame.","cn":"大小屋檐：家庭与国家格局都在同一个共享框架下确定谁作决定。"}]},"affixes":{"intro":{"en":"The compound can be read from two Latin sources: a verb of ability and a verb of building, each with its own derived family.","cn":"这个复合词可以按两个拉丁来源读出：一个表示能力的动词，一个表示建造的动词，各自带有派生词族。"},"latinIntro":{"en":"Latin posse supplies power and potent; Latin struere supplies structure, structural and restructure.","cn":"拉丁 posse 衍生 power 与 potent；拉丁 struere 衍生 structure、structural 与 restructure。"},"items":[{"word":"posse","structure":"posse (Latin verb, 'to be able')","meaning":"to be able","meaningCN":"能够","example":"The verb is the source of the first element.","exampleCN":"这个动词是第一个构词成分的来源。"},{"word":"power","structure":"potere through Old French poeir","meaning":"ability, influence","meaningCN":"能力；影响力","example":"Power is the first element of the compound.","exampleCN":"power 是这个复合词的第一个成分。"},{"word":"struere","structure":"struere, struxi, structum (Latin verb, third conjugation)","meaning":"to pile up, build","meaningCN":"堆起；建造","example":"The verb supplies the image of building.","exampleCN":"这个动词提供建造的意象。"},{"word":"structura","structure":"struere + -ura (result noun)","meaning":"a building, an arrangement","meaningCN":"建筑物；安排","example":"The noun named both a building and its plan.","exampleCN":"这个名词既指建筑，也指它的布局。"},{"word":"structure","structure":"structura through French","meaning":"an arrangement of parts","meaningCN":"各部分的安排","example":"The second element names the arrangement.","exampleCN":"第二个成分指这种安排。"},{"word":"structural","structure":"structure + -al (relating to)","meaning":"relating to the arrangement","meaningCN":"与结构有关的","example":"Structural change altered the reporting lines.","exampleCN":"结构性变化改变了汇报线。"},{"word":"structurally","structure":"structural + -ly (adverb ending)","meaning":"in terms of structure","meaningCN":"在结构上","example":"The agency is structurally dependent on the ministry.","exampleCN":"该机构在结构上依赖部里。"},{"word":"restructure","structure":"re- + structure (rebuild)","meaning":"to rebuild an arrangement","meaningCN":"重组；重建安排","example":"The firm restructured its regional offices.","exampleCN":"这家公司重组了地区办事处。"},{"word":"infrastructure","structure":"infra- + structura (below the building)","meaning":"the built supports beneath a system","meaningCN":"体系下方的支撑设施","example":"Roads and pipes form the infrastructure of the town.","exampleCN":"道路与管道构成这座镇的基础设施。"}],"derivatives":[{"word":"power","structure":"Latin posse through French","meaning":"ability, influence","meaningCN":"能力；权力"},{"word":"structure","structure":"Latin structura through French","meaning":"arrangement of parts","meaningCN":"结构"},{"word":"structural","structure":"structure + -al (relating to)","meaning":"relating to structure","meaningCN":"结构的"},{"word":"restructure","structure":"re- + structure (rebuild)","meaning":"to reorganize","meaningCN":"重组"},{"word":"infrastructure","structure":"infra- + structura (below the building)","meaning":"basic built supports","meaningCN":"基础设施"}],"latinEntries":[{"word":"posse","structure":"posse, potui (verb, irregular)","meaning":"to be able","meaningCN":"能够"},{"word":"struere","structure":"struere, struxi, structum (verb, third conjugation)","meaning":"to build, pile up","meaningCN":"建造；堆起"},{"word":"structura","structure":"structura, structurae (f., first declension)","meaning":"a building, arrangement","meaningCN":"建筑物；安排"}]}},{"word":"leadership","ipa_uk":"/ˈliːdəʃɪp/","ipa_us":"/ˈliːdərʃɪp/","definition_zh":"领导；领导能力；领导层；领导地位","definition_en":"the ability or activity of guiding a group, or the people who hold that role","core_image":"队伍最前面的人举着火把，后面的人跟着那点光走，暗处的路看不清","scene":"夜路上，走在最前面的人举着火把，后面的人跟着那点光前进。Her leadership turned a divided committee into a working team.","sceneCN":"这里指「带领群体行动的领导能力」（第 1 个义项：引导群体的能力）；句意为她的领导力把一个分裂的委员会变成了能运转的团队。可辨识物件：火把、夜路、队伍、前方拐角、脚印。","pos":[{"tag":"n.","zh":"领导；领导能力（常作不可数）"},{"tag":"n.","zh":"领导层；领导班子（集合名词）"},{"tag":"n.","zh":"领导地位；领导职务"}],"collocations":[{"phrase":"under the leadership of","zh":"在……的领导下"},{"phrase":"strong leadership","zh":"强有力的领导"},{"phrase":"leadership style","zh":"领导风格"},{"phrase":"take over the leadership","zh":"接任领导职务"},{"phrase":"party leadership","zh":"党的领导层"},{"phrase":"thought leadership","zh":"思想领导力；行业思想权威"}],"forms":[{"label":"不可数用法（领导能力）","form":"leadership"},{"label":"可数用法（领导层，少见复数）","form":"leaderships"},{"label":"名词（领导者）","form":"leader"},{"label":"动词（带领）","form":"lead"},{"label":"形容词（领先的；主要的）","form":"leading"},{"label":"过去式（带领）","form":"led"},{"label":"现在分词（带领）","form":"leading"}],"derivatives":[{"word":"leader","pos":"n.","zh":"领导者；领先者"},{"word":"lead","pos":"v./n.","zh":"带领；领先；线索"},{"word":"leading","pos":"adj.","zh":"领先的；主要的"},{"word":"led","pos":"v.","zh":"带领（过去式与过去分词）"},{"word":"mislead","pos":"v.","zh":"误导（同出「行走」词根）"},{"word":"leaderless","pos":"adj.","zh":"没有领导的"}],"senses":[{"no":"01","title":"The ability to guide a group","titleCN":"引导群体的能力","definition":"the capacity to set a direction and keep a group working toward it","definitionCN":"确定方向并使一个群体朝该方向持续行动的能力","example":"Her leadership turned a divided committee into a working team.","exampleCN":"她的领导力把一个分裂的委员会变成了能运转的团队。","why":"The verb behind the word means 'to cause to go'; leadership is the ability to make a group go in one direction.","whyCN":"这个词背后的动词意为「使行走」；领导力就是使一个群体朝同一方向前进的能力。"},{"no":"02","title":"The position of leader","titleCN":"领导者的职位","definition":"the office or role of being the person who directs a group","definitionCN":"指导一个群体的那个人所占据的职位或角色","example":"He assumed leadership of the party after the election.","exampleCN":"选举之后，他接任了该党的领导职务。","why":"The suffix turns a person into a state: being a leader is a role that can be entered and left.","whyCN":"后缀把人变成一种状态：做领导者是一个可以进入也可以离开的角色。"},{"no":"03","title":"The group at the top","titleCN":"居于顶层的领导班子","definition":"the collective body of people who hold the highest directing roles in an organization","definitionCN":"在一个组织中占据最高指导职位的集体","example":"The leadership met behind closed doors before the vote.","exampleCN":"投票之前，领导层闭门开会。","why":"English often treats a set of office-holders as one collective noun, so the role becomes a body.","whyCN":"英语常把一群任职者当作一个集合名词，于是职位变成了一个机构。"},{"no":"04","title":"A way of leading","titleCN":"一种领导方式","definition":"a characteristic manner of directing others, such as coaching, directing or delegating","definitionCN":"指导他人的典型方式，如教练式、指挥式或授权式","example":"A coaching style of leadership improved staff retention.","exampleCN":"教练式的领导风格提高了员工留任率。","why":"Once leadership is studied, its manners are classified, and each one becomes a named style.","whyCN":"一旦领导被研究，它的做法就会被分类，每一种做法都成为一个有名称的风格。"},{"no":"05","title":"Direction at the level of government","titleCN":"政府层面的领导","definition":"the activity of setting public direction and taking responsibility for national or local decisions","definitionCN":"确定公共方向并为国家或地方决策承担责任的活动","example":"Political leadership was slow to recognize the drought.","exampleCN":"政治领导层迟迟没有认识到旱情的严重。","why":"The word moves easily from a team to a state, because both need someone to set a course.","whyCN":"这个词很容易从团队移到国家，因为两者都需要有人确定航向。"},{"no":"06","title":"Authority of ideas in an industry","titleCN":"行业中的思想权威","definition":"the reputation of shaping how an industry thinks, often built through research and public comment","definitionCN":"塑造一个行业思考方式的声誉，常通过研究与公开发言建立","example":"The firm publishes reports to establish thought leadership in the field.","exampleCN":"这家公司发布报告，以在该领域建立思想领导力。","why":"Leading need not mean commanding; whoever defines the questions can lead an industry's attention.","whyCN":"领导不必意味着命令；能界定问题的人就能引导一个行业的注意力。"},{"no":"07","title":"First place in a market","titleCN":"市场中的领先地位","definition":"the position of having the largest share or the strongest reputation in a market","definitionCN":"在市场中获得最大份额或最强声誉的位置","example":"The brand lost market leadership after the recall.","exampleCN":"召回事件之后，这个品牌失去了市场领先地位。","why":"Competition borrows the image of a race: the leader is simply the one furthest ahead.","whyCN":"竞争借用了赛跑的意象：领先者就是跑在最前面的那一个。"},{"no":"08","title":"Keeping a group together in difficulty","titleCN":"困境中维持群体的凝聚","definition":"the work of holding a group together and making it continue when conditions are hard","definitionCN":"在艰难条件下维持群体并使其继续前进的工作","example":"Leadership in a storm means keeping the group together, not walking fastest.","exampleCN":"风暴中的领导意味着让队伍保持在一起，而不是自己走得最快。","why":"The oldest image is a person walking ahead with a light; the point is not speed but that others can still follow.","whyCN":"最古老的意象是一个人举着光走在前面；重点不是速度，而是后来的人仍能跟上。"}],"etymology":{"intro":{"en":"Leadership joins leader with the noun suffix -ship. Leader comes from the verb lead, from Old English lǣdan 'to lead, guide', a causative form related to līþan 'to go, travel'. Dates are approximate.","cn":"leadership 由 leader 加名词后缀构成。leader 来自动词 lead，后者出自古英语 lǣdan「带领、引导」，是与 līþan「行走、旅行」相关的使役形式。年代均为约数。"},"items":[{"era":"OLD ENGLISH LITHAN","en":"Līþan meant 'to go, travel'. Its earlier Germanic source is reconstructed rather than directly attested.","cn":"līþan 意为「行走、旅行」。它在日耳曼语中更早的来源属于重构，而非直接有据。"},{"era":"OLD ENGLISH LADAN","en":"Lǣdan was the causative partner of līþan, meaning 'to make go, conduct, guide'.","cn":"lǣdan 是 līþan 的使役对应词，意为「使行走、引导、带领」。"},{"era":"ENGLISH LEAD","en":"The verb lead survived into Middle English and extended from guiding people to being first in a race or market.","cn":"动词 lead 进入中古英语，并从引导人扩展到在竞赛或市场中领先。"},{"era":"ENGLISH LEADER","en":"Leader named the person who conducts others, formed from the verb with an agent ending.","cn":"leader 指带领他人的人，由动词加施事后缀构成。"},{"era":"SUFFIX -SHIP","en":"The ending -ship comes from Old English -scipe, meaning 'state or condition', so leadership is the state of being a leader.","cn":"这个名词后缀来自古英语中表示「状态或境况」的相应后缀，因此 leadership 就是身为领导者的状态。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Germanic source of līþan is a reconstruction, and no exact first citation is fixed for the modern managerial sense, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：līþan 在日耳曼语之前的来源属于重构形式；现代管理义也没有确切的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the same guiding family in other grammatical roles; group two holds nouns for directing people and work.","cn":"第一组是同出「引导」词族、语法角色不同的词；第二组是指挥人与工作的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"leader","ipa":"/ˈliːdə/","tag":"the person","definition":"The person who guides a group; leadership is the role, ability or body that surrounds that person.","definitionCN":"引导群体的人；leadership 是围绕这个人的角色、能力或集体。"},{"word":"lead","ipa":"/liːd/","tag":"the verb","definition":"To guide or be first; it names the action from which the noun is built.","definitionCN":"引导或处于首位；它指构成这个名词的动作。"},{"word":"leading","ipa":"/ˈliːdɪŋ/","tag":"the participle or adjective","definition":"Means guiding or being ahead; as an adjective it describes the front position.","definitionCN":"意为「引导的」或「领先的」；作形容词时描述最前的位置。"},{"word":"mislead","ipa":"/ˌmɪsˈliːd/","tag":"the negative relative","definition":"To guide someone in the wrong direction; it shares the same walking root but adds a prefix of error.","definitionCN":"把人引向错误方向；共享同一个「行走」词根，只是加上表示错误的前缀。"}]},{"heading":"NEAR MEANING","entries":[{"word":"management","ipa":"/ˈmænɪdʒmənt/","tag":"running an organization","definition":"The activity of planning and controlling resources; leadership sets direction, management maintains the system.","definitionCN":"计划与控制资源的活动；领导确定方向，管理维持系统。"},{"word":"guidance","ipa":"/ˈɡaɪdəns/","tag":"showing the way","definition":"Advice or direction given to someone who needs to find a path; it is usually less formal than leadership.","definitionCN":"给需要找路的人以建议或方向；通常比 leadership 更不正式。"},{"word":"direction","ipa":"/dəˈrekʃən/","tag":"the course set","definition":"The course or line along which something moves; leadership is the act of setting that course.","definitionCN":"某物前进的路线或方向；leadership 是设定这条路线的行为。"},{"word":"authority","ipa":"/ɔːˈθɒrəti/","tag":"the recognized right","definition":"Recognized power to command; a leader may have authority, but leadership can exist without it.","definitionCN":"被承认的命令权；领导者可以拥有权威，但领导力也能在没有权威时存在。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real walking root, the real suffix and the real organizational phrases.","cn":"正常联想：真实的「行走」词根、真实的后缀与真实的组织搭配。"},"normal":[{"en":"The verb means 'to cause to go', so leadership is the ability to make a group go forward together.","cn":"动词意为「使行走」，因此领导力就是使一个群体共同前进的能力。"},{"en":"The suffix means 'state or condition', so leadership is literally the state of being a leader.","cn":"后缀意为「状态或境况」，因此 leadership 字面上就是身为领导者的状态。"},{"en":"The family runs lead, leader, leading, led, leadership and mislead.","cn":"同族词包括 lead、leader、leading、led、leadership 与 mislead。"},{"en":"The organizational phrases are under the leadership of, strong leadership and leadership style.","cn":"组织搭配有在……的领导下、强有力的领导与领导风格。"},{"en":"The political and business phrases are party leadership, market leadership and thought leadership.","cn":"政治与商业搭配有党的领导层、市场领先地位与思想领导力。"}],"abstract":[{"en":"Picture a torch at the front of a night column, visible just far enough to follow.","cn":"想象夜行队伍最前面的一支火把，光刚好够后面的人跟着走。"},{"en":"Picture a committee split into two rooms until one person brings both back to the same table.","cn":"想象一个委员会分裂在两个房间，直到有人把双方带回同一张桌子。"},{"en":"Picture a storm where the slowest walker sets the pace and no one is left behind.","cn":"想象一场风暴，最慢的人决定速度，没有人被落下。"}]},"examples":[{"en":"The school needs stable leadership before it can change the curriculum.","cn":"学校需要稳定的领导层，才能改变课程。"},{"en":"She studied leadership in small teams rather than in large corporations.","cn":"她研究的是小团队中的领导，而非大公司中的领导。"},{"en":"Under his leadership, the clinic doubled the number of patients it could see.","cn":"在他的领导下，诊所能够接诊的病人数量翻了一倍。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「带领」加「身份状态」——走在最前面并让后面的人跟上来 → 领导、领导力","word":"leadership"},"root":"leadership 由 leader 加名词后缀构成。leader 来自动词 lead，出自古英语 lǣdan「带领」，与 līþan「行走」相关的使役形式；这个名词后缀来自古英语中表示「状态」的相应后缀。更早的日耳曼来源属于重构形式。","sensesIntro":{"en":"Eight senses follow one image: someone walks in front with a light. The image becomes an ability, a position, a body of leaders, a manner, a government's direction, an industry's authority, a market's first place and finally the work of keeping a group together in a storm.","cn":"八个义项沿同一个意象展开：有人举着光走在前面。这个意象依次变成能力、职位、领导班子、方式、政府的方向、行业的思想权威、市场的首位，最后是在风暴中维持群体不散的工作。"},"semanticMap":{"core":{"en":"CORE IMAGE: a torch carried at the head of a night column.","cn":"核心意象：夜行队伍最前面的一支火把。"},"chain":["GO FIRST","MAKE OTHERS GO","THE OFFICE","THE GROUP AT THE TOP","THE STYLE","BEING AHEAD"],"branches":[{"senses":"01","en":"THE ABILITY: the first sense is the capacity to set a direction and keep others moving.","cn":"能力：第一个义项是确定方向并使他人持续前进的能力。"},{"senses":"02 · 08","en":"THE ROLE AND THE STORM: holding the office and holding the group together are two sides of the same walk.","cn":"职位与风暴：占据职位与维持群体不散，是同一次行走的两面。"},{"senses":"03","en":"THE BODY: a set of office-holders becomes a collective noun with its own meetings.","cn":"集体：一群任职者变成一个拥有自己会议的集合名词。"},{"senses":"04 · 06","en":"THE MANNER AND THE MIND: coaching a team and shaping an industry's questions are both ways of leading.","cn":"方式与思想：教练一个团队与塑造一个行业的问题，都是领导的方式。"},{"senses":"05 · 07","en":"THE PUBLIC RACE: a government sets a national course, and a brand runs first in its market.","cn":"公共赛跑：政府确定国家航向，品牌在其市场中跑在最前。"}]},"affixes":{"intro":{"en":"The noun can be read from an Old English verb of going, its causative partner, an agent noun and the suffix of state.","cn":"这个名词可以按表示行走的古英语动词、它的使役对应词、施事名词以及表示状态的后缀逐段读出。"},"latinIntro":{"en":"This word is native English rather than Latin: the Germanic walking root supplies lead, leader and leadership, and the state suffix comes from Old English.","cn":"这个词是英语本族词而非拉丁借词：日耳曼语中表示行走的词根衍生 lead、leader 与 leadership，表示状态的后缀来自古英语。"},"items":[{"word":"līþan","structure":"līþan (Old English verb, 'to go, travel')","meaning":"to go, travel","meaningCN":"行走；旅行","example":"The old verb named ordinary movement.","exampleCN":"这个古动词指普通的移动。"},{"word":"lǣdan","structure":"lǣdan (Old English causative verb)","meaning":"to make go, guide","meaningCN":"使行走；引导","example":"The causative verb added the idea of causing others to move.","exampleCN":"这个使役动词增添了使他人移动的意思。"},{"word":"lead","structure":"lǣdan (English verb)","meaning":"to guide; to be first","meaningCN":"带领；领先","example":"She led the group through the pass.","exampleCN":"她带队伍穿过了山口。"},{"word":"leader","structure":"lead + -er (one who acts)","meaning":"one who guides","meaningCN":"引导者；领导者","example":"The leader set the pace for the climb.","exampleCN":"领队为登山定了速度。"},{"word":"leading","structure":"lead + -ing (participle or adjective)","meaning":"guiding; being ahead","meaningCN":"引导的；领先的","example":"The leading runner never looked back.","exampleCN":"跑在最前面的选手从未回头。"},{"word":"led","structure":"lead + -ed (past tense and participle)","meaning":"guided","meaningCN":"带领过；被带领的","example":"The guide led us to the ridge.","exampleCN":"向导把我们带到山脊。"},{"word":"leadership","structure":"leader + -ship (state or condition)","meaning":"the state or activity of leading","meaningCN":"领导的状态或活动","example":"The team needed leadership after the loss.","exampleCN":"失利之后，这个团队需要领导。"},{"word":"-ship","structure":"-ship (Old English -scipe, 'state')","meaning":"state, condition, office","meaningCN":"状态；境况；职位","example":"The suffix turns a person into a role.","exampleCN":"这个后缀把一个人变成一种角色。"},{"word":"mislead","structure":"mis- + lead (wrongly guide)","meaning":"to guide in the wrong direction","meaningCN":"把……引向错误方向","example":"The sign misled drivers into the closed road.","exampleCN":"那块牌子把司机引进了封闭的道路。"}],"derivatives":[{"word":"leader","structure":"lead + -er (one who acts)","meaning":"one who guides","meaningCN":"领导者"},{"word":"lead","structure":"Old English lǣdan","meaning":"to guide","meaningCN":"带领"},{"word":"leading","structure":"lead + -ing (participle)","meaning":"guiding; ahead","meaningCN":"领先的"},{"word":"mislead","structure":"mis- + lead (wrongly guide)","meaning":"to guide wrongly","meaningCN":"误导"},{"word":"leaderless","structure":"leader + -less (without)","meaning":"having no leader","meaningCN":"没有领导的"}],"latinEntries":[]}},{"word":"leader","ipa_uk":"/ˈliːdə/","ipa_us":"/ˈliːdər/","definition_zh":"领导者；带头人；领先者；（英）社论；（钓鱼）前导线；乐团首席","definition_en":"a person or thing that guides, directs or is ahead of others","core_image":"队伍最前面的人回头看了一眼，确认后面的人都还跟着，然后继续走","scene":"出发前，队伍最前面的人回头清点人数，确认没有人掉队才继续前进。The group chose a new leader before the season began.","sceneCN":"这里指「带领群体的那个人」（第 1 个义项：群体的领导者）；句意为赛季开始前，这个团体选出了一位新的领导者。可辨识物件：队伍、背包、路口、名册、手杖。","pos":[{"tag":"n.","zh":"领导者；带头人（可数）"},{"tag":"n.","zh":"领先者；领先企业或产品"},{"tag":"n.","zh":"（英）社论；领头文章"},{"tag":"n.","zh":"（钓鱼）前导线；乐团首席"}],"collocations":[{"phrase":"team leader","zh":"团队负责人"},{"phrase":"world leader","zh":"世界领导人"},{"phrase":"market leader","zh":"市场领先者"},{"phrase":"leader of the opposition","zh":"反对党领袖"},{"phrase":"follow the leader","zh":"跟着领头的人做"},{"phrase":"a born leader","zh":"天生的领导者"}],"forms":[{"label":"可数单数","form":"leader"},{"label":"可数复数","form":"leaders"},{"label":"动词（带领）","form":"lead"},{"label":"形容词（领先的）","form":"leading"},{"label":"名词（领导力）","form":"leadership"},{"label":"过去式（带领）","form":"led"},{"label":"形容词（没有领导的）","form":"leaderless"}],"derivatives":[{"word":"lead","pos":"v./n.","zh":"带领；领先；线索"},{"word":"leading","pos":"adj.","zh":"领先的；主要的"},{"word":"leadership","pos":"n.","zh":"领导；领导力；领导层"},{"word":"led","pos":"v.","zh":"带领（过去式与过去分词）"},{"word":"mislead","pos":"v.","zh":"误导"},{"word":"leaderless","pos":"adj.","zh":"没有领导的"}],"senses":[{"no":"01","title":"The person who guides a group","titleCN":"引导群体的那个人","definition":"a person who directs the movement or activity of a group and whom others follow","definitionCN":"指引一个群体的行动或活动、并被他人跟随的人","example":"The group chose a new leader before the season began.","exampleCN":"赛季开始前，这个团体选出了一位新的领导者。","why":"The verb means 'to cause to go', and the agent ending marks the one who does the causing.","whyCN":"动词意为「使行走」，施事后缀标记的正是那个发出使动的人。"},{"no":"02","title":"The head of an organization or government","titleCN":"组织或政府的首脑","definition":"the person holding the highest office in a party, union, company or state","definitionCN":"在政党、工会、公司或国家中占据最高职位的人","example":"Union leaders met the minister on Tuesday.","exampleCN":"工会领袖们在周二会见了部长。","why":"A group large enough to have offices needs a person at the top of its chart, and that person is its leader.","whyCN":"一个大到设有办公室的群体，需要在组织图顶端有一个人，这个人就是它的领导者。"},{"no":"03","title":"The one in front of a race","titleCN":"竞赛中跑在最前的人","definition":"the competitor currently ahead of all others in a race or contest","definitionCN":"在赛跑或竞赛中目前领先于所有其他人的人","example":"The leader pulled away on the final climb.","exampleCN":"领先者在最后一段爬坡时拉开了距离。","why":"The same word covers physical position: whoever is furthest along the course is simply the one leading.","whyCN":"同一个词也覆盖物理位置：在赛道上走得最远的人，自然就是领跑者。"},{"no":"04","title":"The top firm or product","titleCN":"市场中最领先的企业或产品","definition":"the company or brand with the largest share or strongest position in a market","definitionCN":"在市场中份额最大或地位最强的公司或品牌","example":"The company is the market leader in small turbines.","exampleCN":"这家公司是小型涡轮机市场的领先者。","why":"Markets are treated as races, so the firm furthest ahead carries the name of the runner in front.","whyCN":"市场被当作赛跑，因此跑得最远的公司就带上了最前面那位选手的名称。"},{"no":"05","title":"A leading newspaper article","titleCN":"报纸的头篇评论","definition":"in British usage, the main editorial that states the paper's opinion","definitionCN":"英式用法中指表明报纸立场的主要社论","example":"The newspaper's leader criticized the plan as too costly.","exampleCN":"该报的社论批评这项计划代价过高。","why":"The article that stands at the head of the opinion page is literally the leading piece.","whyCN":"站在评论版最前面的那篇文章，字面上就是「领头的」那篇。"},{"no":"06","title":"The line between fly and fish","titleCN":"鱼线与假饵之间的前导线","definition":"in angling, the length of line attached between the main line and the hook or fly","definitionCN":"钓鱼时连接主线与鱼钩或假饵的那段线","example":"He tied a longer leader to the fly line before casting.","exampleCN":"抛竿之前，他在飞蝇线上接了一段更长的前导线。","why":"The leader goes in front of the main line and leads the fly to the fish, so angling borrowed the ordinary word.","whyCN":"前导线走在主线之前，把假饵引向鱼，钓鱼术语因此借用了这个普通词。"},{"no":"07","title":"The first chair in an orchestra","titleCN":"乐团的首席","definition":"the principal player, especially the first violinist, who leads the section and stands in for the conductor","definitionCN":"主要演奏者，尤指首席小提琴手，负责带领声部并在需要时代行指挥","example":"The orchestra's leader tuned the strings before the overture.","exampleCN":"乐团首席在序曲之前为弦乐调音。","why":"Music uses the word for the player who stands first and gives the cue to the section.","whyCN":"音乐用这个词指站在最前面、向声部发出提示的演奏者。"},{"no":"08","title":"The person who takes a group up a mountain","titleCN":"带队的登山向导","definition":"a qualified person who guides a group along a route and takes responsibility for its safety","definitionCN":"沿路线引导团队并对安全负责的合格人员","example":"The mountain leader checked every rope before the descent.","exampleCN":"登山向导在下撤之前检查了每一根绳索。","why":"Guidance on a route is the oldest sense of leading: someone who knows the way walks in front.","whyCN":"在路线上引导是「带领」最古老的义项：知道路的人走在前面。"}],"etymology":{"intro":{"en":"Leader is lead plus the agent ending -er. Lead comes from Old English lǣdan 'to lead, guide', a causative form related to līþan 'to go, travel'. Dates are approximate.","cn":"leader 由 lead 加施事后缀构成。lead 出自古英语 lǣdan「带领、引导」，是与 līþan「行走、旅行」相关的使役形式。年代均为约数。"},"items":[{"era":"OLD ENGLISH LITHAN","en":"Līþan meant 'to go, travel'. Its earlier Germanic source is reconstructed rather than directly attested.","cn":"līþan 意为「行走、旅行」。它在日耳曼语中更早的来源属于重构，而非直接有据。"},{"era":"OLD ENGLISH LADAN","en":"Lǣdan was the causative partner, meaning 'to make go, conduct, guide'.","cn":"lǣdan 是对应的使役词，意为「使行走、引导、带领」。"},{"era":"AGENT ENDING","en":"The ending -er marks the doer. English had a native agent ending, later reinforced by French -ier from Latin -arius.","cn":"这个施事后缀标记动作的执行者。英语本有本土的施事后缀，后来受到法语中源自拉丁语的相应后缀加强。"},{"era":"ENGLISH LEADER","en":"Leader named the person who conducts others, and by the seventeenth century it also named the first person in a race.","cn":"leader 指带领他人的人；到十七世纪，它也指赛跑中最前面的人。"},{"era":"SPECIALIZED SENSES","en":"Angling, music and journalism each gave the word a narrow use, from the line before the fly to the article before the editorial page.","cn":"钓鱼、音乐与新闻各自赋予这个词专门用法，从假饵之前的线，到评论版最前面的文章。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Germanic source of līþan is a reconstruction, and no exact first citation is fixed for the angling sense, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：līþan 在日耳曼语之前的来源属于重构形式；钓鱼义也没有确切的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the same guiding family; group two holds nouns for the person at the head of a group.","cn":"第一组是同出「引导」词族的词；第二组是表示群体首位者的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"lead","ipa":"/liːd/","tag":"the verb","definition":"To guide or be first; the person noun is built directly on this verb.","definitionCN":"引导或处于首位；这个表示人的名词直接由该动词构成。"},{"word":"leading","ipa":"/ˈliːdɪŋ/","tag":"the adjective","definition":"Means guiding or ahead; it describes the position rather than the person.","definitionCN":"意为「引导的」或「领先的」；描述位置，而非人。"},{"word":"leadership","ipa":"/ˈliːdəʃɪp/","tag":"the role","definition":"The ability, position or body of leaders; it surrounds the person with a role.","definitionCN":"领导能力、职位或领导层；它把这个人包在一个角色里。"},{"word":"mislead","ipa":"/ˌmɪsˈliːd/","tag":"the negative relative","definition":"To guide in the wrong direction; it shares the walking root but reverses the purpose.","definitionCN":"把人引向错误方向；共享「行走」词根，却把目的反转。"}]},{"heading":"NEAR MEANING","entries":[{"word":"head","ipa":"/hed/","tag":"the top person","definition":"The person in charge of an organization; it stresses office more than the act of guiding.","definitionCN":"一个组织的主管者；强调职位，而非引导的动作。"},{"word":"chief","ipa":"/tʃiːf/","tag":"the principal one","definition":"The highest-ranking person in a body, often in a traditional or official title.","definitionCN":"某个机构中地位最高的人，常用于传统或官方头衔。"},{"word":"pioneer","ipa":"/ˌpaɪəˈnɪə/","tag":"the first to go","definition":"A person who opens a new field or route; a leader can follow an existing path, a pioneer cannot.","definitionCN":"开辟新领域或新路线的人；领导者可以走已有的路，先驱则不能。"},{"word":"front-runner","ipa":"/ˈfrʌnt rʌnə/","tag":"the one ahead","definition":"The competitor thought most likely to win; it is close to the race sense of leader.","definitionCN":"被认为最可能获胜的竞争者；接近 leader 的赛跑义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real walking root, the real agent ending and the real institutional phrases.","cn":"正常联想：真实的「行走」词根、真实的施事后缀与真实的机构搭配。"},"normal":[{"en":"The verb means 'to cause to go', and the ending means 'the one who', so a leader is the one who makes others go.","cn":"动词意为「使行走」，后缀意为「……的人」，因此领导者就是使他人前进的人。"},{"en":"The family runs lead, leader, leading, led, leadership, mislead and leaderless.","cn":"同族词包括 lead、leader、leading、led、leadership、mislead 与 leaderless。"},{"en":"The organizational phrases are team leader, world leader and leader of the opposition.","cn":"组织搭配有团队负责人、世界领导人与反对党领袖。"},{"en":"The market phrase is market leader, and the everyday phrase is follow the leader.","cn":"市场搭配是市场领先者，日常说法是跟着领头的人做。"},{"en":"The same root appears in mislead, where the guiding is deliberately wrong.","cn":"同一词根出现在 mislead 中，那里的引导是故意走错方向。"}],"abstract":[{"en":"Picture someone at the front of a column who turns back to count the walkers.","cn":"想象队伍最前面的人回头清点人数。"},{"en":"Picture a runner whose back is the only thing the others can see.","cn":"想象一名跑者，其他人只看得见他的背影。"},{"en":"Picture a first violinist raising the bow so that an entire section know when to begin.","cn":"想象首席小提琴手举起弓，让整个声部知道何时开始。"}]},"examples":[{"en":"A good leader makes the next decision easier for everyone else.","cn":"好的领导者会让其他人做下一个决定时更容易。"},{"en":"The market leader cut prices before the smaller firms could respond.","cn":"市场领先者在较小公司来得及反应之前就降了价。"},{"en":"The newspaper's leader called for an independent inquiry.","cn":"该报的社论要求进行独立调查。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「带领」加「人」——走在最前、让别人跟着走的那个人 → 领导者、领先者","word":"leader"},"root":"leader 由 lead 加施事后缀构成。lead 出自古英语 lǣdan「带领」，与 līþan「行走」相关的使役形式；这个后缀标记执行者。更早的日耳曼来源属于重构形式。","sensesIntro":{"en":"Eight senses follow one figure: the one who goes first. The figure is a guide of people, a head of an institution, a runner in front, a top firm, a leading article, a line ahead of the fly, a first violinist and a mountain guide.","cn":"八个义项沿同一个人物展开：走在最前面的那一个。这个人物依次是人群的引导者、机构首脑、跑在前面的选手、顶尖企业、头篇评论、假饵前的线、首席小提琴手与登山向导。"},"semanticMap":{"core":{"en":"CORE IMAGE: the walker at the front who turns to check the column.","cn":"核心意象：走在最前面、回头清点队伍的人。"},"chain":["GO FIRST","CAUSE OTHERS TO GO","THE OFFICE","THE FRONT RUNNER","THE TOP BRAND","THE FIRST CHAIR"],"branches":[{"senses":"01 · 08","en":"THE GUIDE: whether on a trail or in a meeting, the leader is the one who knows the way and walks ahead.","cn":"向导：无论在林间小径上还是在会议中，领导者都是识路并走在前面的人。"},{"senses":"02","en":"THE OFFICE: a large body needs a person at the top of its chart.","cn":"职位：庞大的机构需要在组织图顶端有一个人。"},{"senses":"03 · 04","en":"THE FRONT: a race and a market both measure who is furthest ahead.","cn":"最前：赛跑与市场都在衡量谁跑得最远。"},{"senses":"05","en":"THE LEADING WORD: the article at the head of the opinion page speaks for the paper.","cn":"领头之言：评论版最前面的文章代表报纸发言。"},{"senses":"06 · 07","en":"THE FIRST IN LINE: a fishing trace and a first violin both stand ahead of the rest.","cn":"队列之首：钓鱼前导线与首席小提琴都站在其余之前。"}]},"affixes":{"intro":{"en":"The noun can be read from an Old English verb of going, its causative partner and the agent ending that marks the doer.","cn":"这个名词可以按表示行走的古英语动词、它的使役对应词以及标记执行者的施事后缀逐段读出。"},"latinIntro":{"en":"This word is native English rather than Latin: the Germanic walking root supplies the verb, and the agent ending marks the person.","cn":"这个词是英语本族词而非拉丁借词：日耳曼语中表示行走的词根提供动词，施事后缀标记人。"},"items":[{"word":"līþan","structure":"līþan (Old English verb, 'to go')","meaning":"to go, travel","meaningCN":"行走；旅行","example":"The old verb named ordinary movement.","exampleCN":"这个古动词指普通移动。"},{"word":"lǣdan","structure":"lǣdan (Old English causative verb)","meaning":"to make go, guide","meaningCN":"使行走；引导","example":"The causative verb added the idea of conducting others.","exampleCN":"这个使役动词增添了带领他人的意思。"},{"word":"lead","structure":"lǣdan (English verb)","meaning":"to guide; to be first","meaningCN":"带领；领先","example":"He led the team through the gate.","exampleCN":"他带队伍穿过大门。"},{"word":"-er","structure":"-er (agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The ending marks the person who performs the action.","exampleCN":"这个后缀标记执行动作的人。"},{"word":"leader","structure":"lead + -er","meaning":"one who guides","meaningCN":"引导者；领导者","example":"The leader waited at the fork in the path.","exampleCN":"领路人在岔路口等候。"},{"word":"leading","structure":"lead + -ing (participle)","meaning":"guiding; ahead","meaningCN":"引导的；领先的","example":"The leading car turned off the highway.","exampleCN":"领头的那辆车驶离了公路。"},{"word":"led","structure":"lead + -ed (past tense)","meaning":"guided","meaningCN":"带领过","example":"She led the group down the ridge.","exampleCN":"她带队伍沿山脊下行。"},{"word":"leadership","structure":"leader + -ship (state)","meaning":"the role of leading","meaningCN":"领导职位或领导力","example":"The team turned to her for leadership.","exampleCN":"团队向她寻求领导。"},{"word":"mislead","structure":"mis- + lead (wrongly guide)","meaning":"to guide wrongly","meaningCN":"误导","example":"A false sign misled the hikers.","exampleCN":"一块错误的牌子误导了徒步者。"},{"word":"leaderless","structure":"leader + -less (without)","meaning":"having no leader","meaningCN":"没有领导的","example":"The leaderless group drifted apart.","exampleCN":"这个没有领导的群体逐渐散开。"}],"derivatives":[{"word":"lead","structure":"Old English lǣdan","meaning":"to guide","meaningCN":"带领"},{"word":"leading","structure":"lead + -ing (participle)","meaning":"guiding; ahead","meaningCN":"领先的"},{"word":"leadership","structure":"leader + -ship (state)","meaning":"the role of leading","meaningCN":"领导；领导力"},{"word":"mislead","structure":"mis- + lead (wrongly guide)","meaning":"to guide wrongly","meaningCN":"误导"},{"word":"leaderless","structure":"leader + -less (without)","meaning":"without a leader","meaningCN":"没有领导的"}],"latinEntries":[]}},{"word":"leadership role","ipa_uk":"/ˈliːdəʃɪp rəʊl/","ipa_us":"/ˈliːdərʃɪp roʊl/","definition_zh":"领导角色；领导职位以及该职位应有的职责与行为期待","definition_en":"the position of leading a group together with the duties and behaviour that the position is expected to involve","core_image":"舞台侧面挂着一件写有职务的外套，谁穿上它，谁就要按戏里的方式说话和行动","scene":"排练前，导演把一件写着职务的外套递给替补演员，让他按主角的方式走位。She accepted the leadership role after the board vote.","sceneCN":"这里指「正式承担的领导职位」（第 1 个义项：正式领导职位）；句意为董事会投票之后，她接受了这个领导职位。可辨识物件：外套、舞台侧幕、剧本、走位标记、座椅。","pos":[{"tag":"n.","zh":"领导角色（职位与职责，常作可数）"},{"tag":"n.","zh":"领导角色（行为期待，可数或不可数）"}],"collocations":[{"phrase":"take on a leadership role","zh":"承担领导角色"},{"phrase":"assume a leadership role","zh":"就任领导职位"},{"phrase":"a leadership role in the project","zh":"项目中的领导角色"},{"phrase":"step into a leadership role","zh":"走上领导岗位"},{"phrase":"shared leadership role","zh":"共享的领导角色"},{"phrase":"leadership role expectations","zh":"对领导角色的期待"}],"forms":[{"label":"可数单数","form":"leadership role"},{"label":"可数复数","form":"leadership roles"},{"label":"名词（领导力）","form":"leadership"},{"label":"名词（角色）","form":"role"},{"label":"动词（扮演；承担角色）","form":"role-play"},{"label":"名词（领导者）","form":"leader"},{"label":"动词（带领）","form":"lead"}],"derivatives":[{"word":"leadership","pos":"n.","zh":"领导；领导力；领导层"},{"word":"role","pos":"n.","zh":"角色；职责；作用"},{"word":"leader","pos":"n.","zh":"领导者"},{"word":"lead","pos":"v.","zh":"带领"},{"word":"role-play","pos":"n./v.","zh":"角色扮演"},{"word":"role model","pos":"n.","zh":"行为榜样"}],"senses":[{"no":"01","title":"The formal position of leading","titleCN":"正式的领导职位","definition":"an official post in which a person is responsible for directing a group","definitionCN":"一个人负责指导群体的正式职位","example":"She accepted the leadership role after the board vote.","exampleCN":"董事会投票之后，她接受了这个领导职位。","why":"A role is a part written for whoever occupies it; a leadership role is the part that carries authority.","whyCN":"角色是为占据它的人写好的戏份；领导角色就是带有权威的那份戏份。"},{"no":"02","title":"What others expect of the leader","titleCN":"他人对领导者的行为期待","definition":"the set of behaviours that a group expects from the person in the leading position","definitionCN":"一个群体期待处于领导位置的人做出的那套行为","example":"The leadership role requires listening as much as deciding.","exampleCN":"领导角色要求倾听与作决定同样多。","why":"Every part comes with a script, and the group writes much of that script before anyone is cast.","whyCN":"每个角色都带着剧本，而群体在选定人选之前就已经写好了其中大部分。"},{"no":"03","title":"The part someone steps into","titleCN":"某人临时承担的领导角色","definition":"a leading part taken on in a particular situation, often without a formal title","definitionCN":"在特定情境中承担的领导角色，往往没有正式头衔","example":"In the rescue, a quiet volunteer took the leadership role.","exampleCN":"在救援中，一位安静的志愿者承担了领导角色。","why":"When a situation needs someone to give cues, a person can step into the part even without the office.","whyCN":"当情境需要有人发出提示时，即使没有职位，人也可以踏进这个角色。"},{"no":"04","title":"The rotating part in a team","titleCN":"团队中轮换的领导角色","definition":"a leading function assigned to a team member for a period and then passed on","definitionCN":"在某一时期内分配给团队成员、随后转交他人的领导职能","example":"Each project team rotates its leadership role every term.","exampleCN":"每个项目团队每学期轮换一次领导角色。","why":"If a role is a part rather than a person, it can be handed from one player to another without breaking the play.","whyCN":"如果角色是戏份而非人，它就可以从一个演员交给另一个，而戏不会中断。"},{"no":"05","title":"The part held across a long project","titleCN":"长期项目中持续承担的领导角色","definition":"responsibility for directing a multi-stage piece of work from start to finish","definitionCN":"从开始到结束指导一项多阶段工作的责任","example":"His leadership role on the bridge project lasted three years.","exampleCN":"他在桥梁项目中的领导角色持续了三年。","why":"Long work needs a continuous part, not a single cue; the role becomes a thread through the schedule.","whyCN":"长期工作需要持续的角色，而非一次提示；这个角色于是贯穿整个日程。"},{"no":"06","title":"The part recognized by a community","titleCN":"共同体认可的领导角色","definition":"an informal leading position granted by a community's trust rather than by an appointment","definitionCN":"由共同体信任而非任命授予的非正式领导位置","example":"The elder's leadership role in the village was never written down.","exampleCN":"这位长者在村庄里的领导角色从未被写下来。","why":"Some roles are written on paper and some on memory; a community can cast a part without a document.","whyCN":"有些角色写在纸上，有些写在记忆里；共同体可以在没有文件的情况下分配角色。"},{"no":"07","title":"The part demanded by a crisis","titleCN":"危机要求的领导角色","definition":"the specific leading behaviour required when a group faces urgent danger or uncertainty","definitionCN":"群体面对紧急危险或不确定时所需的特定领导行为","example":"A crisis leadership role demands clear public communication.","exampleCN":"危机中的领导角色要求清晰的公共沟通。","why":"A crisis rewrites the script overnight and asks the person in the part to speak plainly and quickly.","whyCN":"危机会在一夜之间改写剧本，要求承担角色的人说得清楚、说得及时。"},{"no":"08","title":"One part shared by several people","titleCN":"由数人共同担任的领导角色","definition":"a leading function divided among two or more people instead of held by a single chair","definitionCN":"由两人或更多人分担、而非由单一主席持有的领导职能","example":"The cooperative uses a shared leadership role instead of a single chair.","exampleCN":"这家合作社采用共享的领导角色，而不是单一主席。","why":"If the part can be written, it can also be split, so that no single actor carries every line.","whyCN":"既然角色可以被写出来，它也可以被拆开，使没有任何一个演员承担全部台词。"}],"etymology":{"intro":{"en":"Leadership role joins leadership, from Old English lǣdan 'to lead', with role, from French rôle 'a roll of paper, a part', from Latin rotulus 'small scroll', a diminutive of rota 'wheel'. Dates are approximate.","cn":"leadership role 由 leadership 与 role 组合而成。leadership 出自古英语 lǣdan「带领」；role 来自法语 rôle「纸卷、角色」，再往上出自拉丁 rotulus「小卷轴」，是 rota「轮子」的指小形式。年代均为约数。"},"items":[{"era":"OLD ENGLISH LADAN","en":"Lǣdan meant 'to lead, guide', a causative form related to līþan 'to go'. Its pre-Germanic source is reconstructed.","cn":"lǣdan 意为「带领、引导」，是与 līþan「行走」相关的使役形式。它在日耳曼语之前的来源属于重构。"},{"era":"ENGLISH LEADERSHIP","en":"Leadership was formed from leader plus the state suffix -ship, naming the condition or activity of leading.","cn":"leadership 由 leader 加表示状态的名词后缀构成，指领导的状态或活动。"},{"era":"LATIN ROTA","en":"Rota meant 'wheel'. Its deeper origin is not established; the wheel root proposed for it is a reconstruction.","cn":"rota 意为「轮子」。其更深来源未得到证明；为它提出的「轮」词根属于重构形式。"},{"era":"LATIN ROTULUS","en":"The diminutive rotulus named a small wheel and then a rolled scroll of paper.","cn":"指小形式 rotulus 先指小轮，后指卷起的纸卷。"},{"era":"FRENCH ROLE","en":"French rôle named the roll on which an actor's part was written, and English adopted it for the part itself.","cn":"法语 rôle 指写下演员台词的那卷纸，英语借用来指角色本身。"},{"era":"MODERN PHRASE","en":"The compound leadership role appeared in twentieth-century management writing, where a post is described as a part with expectations attached.","cn":"这个复合短语出现在二十世纪的管理写作中，把职位描述为一个附带行为期待的角色。"}]},"similar":{"note":{"en":"Group one holds the two components and their relatives; group two holds words for a post and its duties.","cn":"第一组是两个构词成分及其亲属词；第二组是表示职位及其职责的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"leadership","ipa":"/ˈliːdəʃɪp/","tag":"the first element","definition":"The ability or body of leaders; the phrase narrows it to one specific part.","definitionCN":"领导能力或领导层；这个短语把它收窄为某一个具体角色。"},{"word":"role","ipa":"/rəʊl/","tag":"the second element","definition":"A part played or a function performed; alone it can describe an actor as easily as a manager.","definitionCN":"扮演的角色或承担的职能；单独使用时既可指演员，也可指管理者。"},{"word":"leader","ipa":"/ˈliːdə/","tag":"the person","definition":"The individual who fills the role; the phrase names the part, not the person.","definitionCN":"填补这个角色的个人；这个短语命名的是角色，而非人。"},{"word":"lead role","ipa":"/liːd rəʊl/","tag":"the acting part","definition":"The main part in a play or film; it looks similar but belongs to casting rather than management.","definitionCN":"戏剧或电影中的主角；看起来相似，却属于选角而非管理。"}]},{"heading":"NEAR MEANING","entries":[{"word":"position","ipa":"/pəˈzɪʃən/","tag":"the post","definition":"A job or office in an organization; it names the slot rather than the behaviour expected in it.","definitionCN":"组织中的职位或岗位；指位置本身，而非对该位置的行为期待。"},{"word":"function","ipa":"/ˈfʌŋkʃən/","tag":"the duty","definition":"The purpose or duty that a person or office is meant to perform.","definitionCN":"一个人或职位应当履行的目的或职责。"},{"word":"mandate","ipa":"/ˈmændət/","tag":"the authority to act","definition":"An official instruction or authority given to someone; a role can exist without a formal mandate.","definitionCN":"授予某人的官方指示或权限；角色可以在没有正式授权的情况下存在。"},{"word":"appointment","ipa":"/əˈpɔɪntmənt/","tag":"the act of naming","definition":"The act of choosing someone for a post; it is the casting decision, not the part itself.","definitionCN":"选择某人担任职位的行为；这是选角决定，而非角色本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real walking root, the real scroll image behind role and the real management phrases.","cn":"正常联想：真实的「行走」词根、role 背后真实的纸卷意象与真实的管理搭配。"},"normal":[{"en":"The first word means the activity of leading; the second began as a paper roll holding an actor's lines, so the phrase means the part written for a leader.","cn":"第一个词指领导活动；第二个词原指写有演员台词的纸卷，因此整个短语意为「为领导者写好的那份戏份」。"},{"en":"The family runs leadership, leader, lead, role, role-play and role model.","cn":"同族词包括领导、领导者、带领、角色、角色扮演与角色榜样。"},{"en":"The management phrases are take on a leadership role, assume a leadership role and step into a leadership role.","cn":"管理搭配有承担领导角色、就任领导职位与走上领导岗位。"},{"en":"The descriptive phrases are shared leadership role and leadership role expectations.","cn":"描述性搭配有共享的领导角色与对领导角色的期待。"},{"en":"The same scroll root appears in the word for a part in a play, which still means a scripted role.","cn":"同一「纸卷」词根出现在表示戏剧角色的词中，那个词至今仍指写好的角色。"}],"abstract":[{"en":"Picture a coat hanging at the side of a stage, with a name written on its collar.","cn":"想象舞台侧边挂着一件外套，衣领上写着名字。"},{"en":"Picture a paper roll handed to an understudy, already full of lines he did not write.","cn":"想象一卷纸递给替补演员，上面早已写满他没写过的台词。"},{"en":"Picture two people holding the same coat at once, each carrying half the lines.","cn":"想象两个人同时拿着同一件外套，每人念一半台词。"}]},"examples":[{"en":"The leadership role comes with responsibility for the budget as well as the staff.","cn":"这个领导角色既带来对员工的责任，也带来对预算的责任。"},{"en":"She stepped into a leadership role when the director resigned.","cn":"主任辞职后，她走上了领导岗位。"},{"en":"The study asked how leadership roles are shared in small cooperatives.","cn":"这项研究追问小型合作社如何分担领导角色。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「领导」加「角色」——穿上这件写着职务的外套，就要按戏里的方式说话 → 领导角色、领导职位","word":"leadership role"},"root":"leadership role 由 leadership 与 role 组合而成。leadership 出自古英语 lǣdan「带领」；role 来自法语 rôle「纸卷、角色」，再往上出自拉丁 rotulus「小卷轴」，是 rota「轮子」的指小形式。rota 的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one theatrical image: a part is written, cast, stepped into, rotated, held for years, recognized by an audience, rewritten in a crisis and sometimes shared by two actors.","cn":"八个义项沿同一个戏剧意象展开：一份戏份被写好、被分配、被踏进去、被轮换、被长期持有、被观众认可、在危机中被改写，有时还由两名演员共同承担。"},"semanticMap":{"core":{"en":"CORE IMAGE: a costume hanging at the side of a stage.","cn":"核心意象：舞台侧边挂着的一件戏服。"},"chain":["THE PART IS WRITTEN","THE PART IS CAST","THE PART IS PLAYED","THE PART TURNS","THE PART ENDURES","THE PART IS SHARED"],"branches":[{"senses":"01","en":"THE CAST PART: a formal post is a role assigned to one person by decision.","cn":"被分配的角色：正式职位是通过决定分配给某个人的角色。"},{"senses":"02 · 07","en":"THE SCRIPT: expectations and crisis conditions both tell the actor which lines to say.","cn":"剧本：行为期待与危机情境都在告诉演员该念哪些台词。"},{"senses":"03","en":"THE UNDERSTUDY: someone steps into the part when the situation calls for it.","cn":"替补上场：情境需要时，有人踏进这个角色。"},{"senses":"04 · 08","en":"THE SHARED PART: the role can rotate or be split so that no single actor owns it.","cn":"共享角色：角色可以轮换或拆开，使任何单个演员都无法独占。"},{"senses":"05 · 06","en":"THE LONG RUN: a project part lasts for years, and a community part is remembered without a document.","cn":"长期上演：项目角色持续多年，共同体角色则无需文件也被记住。"}]},"affixes":{"intro":{"en":"The phrase can be read from an Old English verb of leading and a Latin noun for a scroll that became the word for a part.","cn":"这个短语可以按表示带领的古英语动词，以及由拉丁语「卷轴」演变而来、后来表示角色的名词逐段读出。"},"latinIntro":{"en":"The first element is native English; the second came through French from Latin rotulus, a small scroll, and rota, a wheel.","cn":"第一个成分是英语本族词；第二个成分经法语来自拉丁 rotulus「小卷轴」与 rota「轮子」。"},"items":[{"word":"lǣdan","structure":"lǣdan (Old English verb, 'to lead')","meaning":"to make go, guide","meaningCN":"使行走；引导","example":"The verb supplies the leading half of the phrase.","exampleCN":"这个动词提供短语中「领导」的一半。"},{"word":"leader","structure":"lead + -er (one who acts)","meaning":"one who guides","meaningCN":"引导者","example":"The leader set the pace.","exampleCN":"领导者定下速度。"},{"word":"leadership","structure":"leader + -ship (state)","meaning":"the activity or role of leading","meaningCN":"领导活动或领导职位","example":"Leadership was shared between two offices.","exampleCN":"领导职责由两个办公室分担。"},{"word":"rota","structure":"rota, rotae (Latin noun, 'wheel')","meaning":"wheel","meaningCN":"轮子","example":"The noun named a round object.","exampleCN":"这个名词指圆形物体。"},{"word":"rotulus","structure":"rota + -ulus (diminutive)","meaning":"small wheel; a roll of paper","meaningCN":"小轮；纸卷","example":"The scroll was a rotulus before it was a role.","exampleCN":"在成为角色之前，它是一卷纸。"},{"word":"rôle","structure":"rotulus through French rôle","meaning":"a roll; an actor's part","meaningCN":"纸卷；演员的角色","example":"The part was written on a roll.","exampleCN":"角色被写在一卷纸上。"},{"word":"role","structure":"rôle (English noun)","meaning":"a part or function","meaningCN":"角色；职能","example":"Every member has a role in the drill.","exampleCN":"每个人在演练中都有角色。"},{"word":"role-play","structure":"role + play (act a part)","meaning":"to act out a part","meaningCN":"角色扮演","example":"The class role-played a negotiation.","exampleCN":"班级进行了一场谈判的角色扮演。"},{"word":"role model","structure":"role + model (example of a part)","meaning":"a person whose behaviour others imitate","meaningCN":"行为榜样","example":"The coach served as a role model for the team.","exampleCN":"教练成为团队的行为榜样。"},{"word":"leadership role","structure":"leadership + role","meaning":"the part assigned to a leader","meaningCN":"分配给领导者的角色","example":"She took the leadership role in the campaign.","exampleCN":"她在活动中承担了领导角色。"}],"derivatives":[{"word":"leadership","structure":"leader + -ship (state)","meaning":"the activity of leading","meaningCN":"领导；领导力"},{"word":"role","structure":"French rôle from Latin rotulus","meaning":"a part or function","meaningCN":"角色；职能"},{"word":"role-play","structure":"role + play","meaning":"to act a part","meaningCN":"角色扮演"},{"word":"role model","structure":"role + model","meaning":"an example to imitate","meaningCN":"行为榜样"},{"word":"leader","structure":"lead + -er (one who acts)","meaning":"one who guides","meaningCN":"领导者"}],"latinEntries":[{"word":"rota","structure":"rota, rotae (f., first declension)","meaning":"wheel","meaningCN":"轮子"},{"word":"rotulus","structure":"rotulus, rotuli (m., second declension)","meaning":"small wheel; scroll","meaningCN":"小轮；卷轴"}]}},{"word":"nonconformity","ipa_uk":"/ˌnɒnkənˈfɔːməti/","ipa_us":"/ˌnɑːnkənˈfɔːrməti/","definition_zh":"不遵从；不循规蹈矩；（宗教史）不从国教；（质量管理）不符合项","definition_en":"failure or refusal to follow accepted norms, rules or standards","core_image":"一排人按同一节奏踏步，只有一个人始终慢半拍，鞋底落地的声音与队伍错开","scene":"操场上所有人按同一节奏踏步，只有一个人始终慢半拍，脚步声与队伍错开。Her nonconformity made the small town uneasy but also gave it new ideas.","sceneCN":"这里指「不遵从群体既定规范的行为」（第 1 个义项：对社会规范的不遵从）；句意为她的不循常规让这座小镇不安，却也给它带来了新想法。可辨识物件：操场、队列、脚步、节拍器、围栏。","pos":[{"tag":"n.","zh":"不遵从；不循规蹈矩（常作不可数）"},{"tag":"n.","zh":"（宗教史）不从国教；新教异议派"},{"tag":"n.","zh":"不符合项（质量管理用语，可数）"}],"collocations":[{"phrase":"social nonconformity","zh":"社会层面的不遵从"},{"phrase":"a streak of nonconformity","zh":"一股不循常规的个性"},{"phrase":"religious nonconformity","zh":"宗教上的不从国教"},{"phrase":"nonconformity report","zh":"不符合项报告"},{"phrase":"tolerate nonconformity","zh":"容忍不循常规"},{"phrase":"a nonconformity in the process","zh":"流程中的一处不符合"}],"forms":[{"label":"不可数用法（不遵从的状态）","form":"nonconformity"},{"label":"可数复数（具体不符合项）","form":"nonconformities"},{"label":"名词（遵从）","form":"conformity"},{"label":"名词（不遵从者）","form":"nonconformist"},{"label":"动词（遵从）","form":"conform"},{"label":"形容词（不遵从的）","form":"nonconforming"},{"label":"名词（遵从者）","form":"conformist"}],"derivatives":[{"word":"conformity","pos":"n.","zh":"遵从；一致；符合"},{"word":"nonconformist","pos":"n./adj.","zh":"不遵从者；不循常规的"},{"word":"conform","pos":"v.","zh":"遵从；符合"},{"word":"nonconforming","pos":"adj.","zh":"不符合的；不遵从的"},{"word":"conformist","pos":"n./adj.","zh":"遵从者；循规蹈矩的"},{"word":"conformable","pos":"adj.","zh":"符合的；顺从的"}],"senses":[{"no":"01","title":"Refusal to follow the group's norms","titleCN":"拒绝遵从群体规范","definition":"behaviour that does not follow the accepted customs or expectations of a group","definitionCN":"不遵循一个群体公认习俗或期待的行为","example":"Her nonconformity made the small town uneasy but also gave it new ideas.","exampleCN":"她的不循常规让这座小镇不安，却也给它带来了新想法。","why":"The word is built as the negative of conformity: a group has one shape, and this word names the refusal to take that shape.","whyCN":"这个词由表示「从众」的名词加否定前缀构成：群体有一个共同形状，而这个词指拒绝变成那个形状。"},{"no":"02","title":"An independent cast of mind","titleCN":"独立而不随大流的心性","definition":"a personal tendency to think and act according to one's own judgment rather than the majority","definitionCN":"按自己的判断而非多数人的做法思考与行动的个人倾向","example":"The school prized nonconformity as much as good marks.","exampleCN":"这所学校重视不随大流的品性，程度不亚于重视好成绩。","why":"A habit of refusing the common shape can become a trait, praised in one setting and punished in another.","whyCN":"拒绝共同形状的习惯可以成为一种品性，在一种环境里受赞扬，在另一种环境里受惩罚。"},{"no":"03","title":"Protestant dissent from the state church","titleCN":"新教不从国教","definition":"the historical position of British Protestants who refused to accept the established church's rules","definitionCN":"英国历史上拒绝接受国教教会规则的新教徒立场","example":"Nonconformity grew among Protestants who refused the state church.","exampleCN":"不从国教的做法在拒绝国教教会的新教徒中发展起来。","why":"The general refusal to conform acquired a capital name when an entire religious community refused one official form.","whyCN":"当整个宗教群体拒绝一种官方形式时，一般意义上的「不遵从」就获得了一个专有名称。"},{"no":"04","title":"A break with artistic convention","titleCN":"对艺术成规的突破","definition":"an artist's deliberate departure from the accepted techniques or subjects of a tradition","definitionCN":"艺术家有意偏离某一传统中被接受的手法或题材","example":"The painter's nonconformity broke every rule of the academy.","exampleCN":"这位画家的不循成规打破了学院的每一条规则。","why":"Art academies set a shape for correct work; nonconformity is the decision to paint outside it.","whyCN":"艺术学院为「正确作品」设定了形状；不循成规就是决定在这个形状之外作画。"},{"no":"05","title":"A product that fails the specification","titleCN":"未达到规格的产品","definition":"a product or batch that does not meet a stated requirement, recorded in quality control","definitionCN":"未满足规定要求、被质量控制记录下来的产品或批次","example":"The audit found three nonconformities in the welding process.","exampleCN":"审计在焊接流程中发现了三处不符合项。","why":"Industry uses the word literally: a thing that does not take the required shape is a nonconformity.","whyCN":"工业界按字面使用这个词：没有达到规定形状的东西就是一处不符合。"},{"no":"06","title":"A procedure that departs from the rule","titleCN":"偏离既定程序的做法","definition":"a documented failure to follow an agreed procedure or standard in an organization","definitionCN":"一个组织中被记录下来的、未遵循既定程序或标准的情况","example":"The supplier filed a nonconformity report after the missed inspection.","exampleCN":"供应方在漏检之后提交了一份不符合项报告。","why":"Management systems treat procedure as a mould, and any deviation from that mould must be written down.","whyCN":"管理体系把程序当作模具，任何偏离模具的做法都必须写下来。"},{"no":"07","title":"Mild departure that stops short of crime","titleCN":"尚未触犯法律的轻度越轨","definition":"a small breach of social expectations that is noticed and criticized but not legally punished","definitionCN":"对社会期待的轻微违背，会被注意和批评，却不受法律惩罚","example":"Sociologists distinguish nonconformity from outright deviance.","exampleCN":"社会学家把不循常规与彻底的越轨区分开来。","why":"The word marks the gentler end of a scale: a person steps out of line without stepping outside the law.","whyCN":"这个词标记尺度的较轻一端：人走出了队列，却没有走出法律。"},{"no":"08","title":"A gap in the geological record","titleCN":"地质记录中的不整合面","definition":"a boundary where younger sedimentary rock rests directly on older igneous or metamorphic rock","definitionCN":"较年轻的沉积岩直接覆盖在较古老的火成岩或变质岩之上的界面","example":"The cliff shows a nonconformity where sandstone rests on granite.","exampleCN":"这处悬崖显示出一个不整合面，砂岩直接覆在花岗岩上。","why":"Geology borrowed the word for layers that do not conform to the expected sequence, leaving a gap in time.","whyCN":"地质学借用这个词指不按预期顺序排列的岩层，它们在时间上留下一个缺口。"}],"etymology":{"intro":{"en":"Nonconformity is non- plus conformity. Conformity comes from Latin conformare 'to form, fashion', built on con- 'together' and formare 'to form', from forma 'shape'. Dates are approximate.","cn":"nonconformity 由 non- 与 conformity 构成。conformity 来自拉丁 conformare「使成形、塑造」，由 con-「共同」与 formare「使成形」构成，而后者出自 forma「形状」。年代均为约数。"},"items":[{"era":"LATIN FORMA","en":"Forma meant 'shape, form, mould'. Its deeper origin is not established; the link sometimes suggested to Greek morphē is a hypothesis rather than a demonstrated derivation.","cn":"forma 意为「形状、形式、模具」。其更深来源未得到证明；有人把它与希腊 morphē 联系起来，那只是假说，并非已证实的派生。"},{"era":"LATIN FORMARE","en":"Formare meant 'to give shape to, mould, fashion', built from forma.","cn":"formare 意为「使成形、塑造、制作」，由 forma 构成。"},{"era":"LATIN CONFORMARE","en":"Con- 'together' plus formare produced conformare, 'to shape together, make alike, bring into agreement'.","cn":"con-「共同」加 formare 构成 conformare「共同成形、使相像、使一致」。"},{"era":"ENGLISH CONFORMITY","en":"Conformity entered English through Old French in the fourteenth century, naming agreement with an accepted pattern.","cn":"conformity 在十四世纪经古法语进入英语，指与一种被接受的模式相一致。"},{"era":"ENGLISH NONCONFORMITY","en":"The negative form appeared in the seventeenth century, first for religious dissent and later for any refusal of accepted norms.","cn":"否定形式在十七世纪出现，最初指宗教上的异议，后来指对任何公认规范的拒绝。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of forma is unsettled, and no exact first citation is fixed for the quality-control sense, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：forma 在拉丁语之前的来源无定论；质量控制义也没有确切的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the conformity family in other forms; group two holds words for refusing an accepted pattern.","cn":"第一组是 conformity 词族的其他形式；第二组是表示拒绝公认模式的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conformity","ipa":"/kənˈfɔːməti/","tag":"the positive form","definition":"Agreement with accepted norms; nonconformity is its direct negation, not a different root.","definitionCN":"与公认规范相一致；nonconformity 是它的直接否定，并非另一个词根。"},{"word":"nonconformist","ipa":"/ˌnɒnkənˈfɔːmɪst/","tag":"the person","definition":"A person who refuses accepted norms; the abstract noun names the refusal, this one names the refuser.","definitionCN":"拒绝公认规范的人；抽象名词指拒绝本身，这个词指拒绝者。"},{"word":"conform","ipa":"/kənˈfɔːm/","tag":"the verb","definition":"To take the required shape or follow the rule; the noun describes the result of refusing to do so.","definitionCN":"采取要求的形状或遵循规则；这个名词描述拒绝这样做的结果。"},{"word":"conformist","ipa":"/kənˈfɔːmɪst/","tag":"the opposite person","definition":"A person who follows accepted norms readily; it is the personal opposite of the nonconformist.","definitionCN":"乐于遵循公认规范的人；是不从者的人格对立面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deviance","ipa":"/ˈdiːviəns/","tag":"the sociological relative","definition":"Behaviour that violates social norms; it is the broader analytical term, while nonconformity often suggests deliberate refusal.","definitionCN":"违反社会规范的行为；它是更宽泛的分析术语，而 nonconformity 常暗示有意的拒绝。"},{"word":"dissent","ipa":"/dɪˈsent/","tag":"spoken disagreement","definition":"An opinion that differs from an official or majority view; it is about stated disagreement, not behaviour.","definitionCN":"与官方或多数观点不同的意见；指表达出的不同意见，而非行为。"},{"word":"independence","ipa":"/ˌɪndɪˈpendəns/","tag":"self-direction","definition":"The quality of acting by one's own judgment; it is the admired side of nonconformity.","definitionCN":"按自己的判断行动的特质；是不循常规中受赞赏的一面。"},{"word":"heresy","ipa":"/ˈherəsi/","tag":"religious error","definition":"A belief condemned as false by an established religious authority; it is a judgement, not a neutral description.","definitionCN":"被既定宗教权威判为错误的信仰；它是一种裁决，而非中立描述。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real shape root, the real negative prefix and the real quality phrases.","cn":"正常联想：真实的「形状」词根、真实的否定前缀与真实的质量搭配。"},"normal":[{"en":"The root means 'shape', and the prefix means 'not', so the word means 'not taking the shape the group expects'.","cn":"词根意为「形状」，前缀意为「不」，因此这个词意为「不采取群体期待的那个形状」。"},{"en":"The family runs conform, conformity, conformist, nonconformist, nonconforming and conformable.","cn":"同族词包括 conform、conformity、conformist、nonconformist、nonconforming 与 conformable。"},{"en":"The social phrases are social nonconformity and a streak of nonconformity.","cn":"社会搭配有社会层面的不遵从与一股不循常规的个性。"},{"en":"The quality phrases are nonconformity report and a nonconformity in the process.","cn":"质量搭配有不符合项报告与流程中的一处不符合。"},{"en":"The historical phrase is religious nonconformity, naming Protestant dissent from the state church.","cn":"历史搭配是宗教上的不从国教，指新教徒对国教教会的异议。"}],"abstract":[{"en":"Picture a marching line where one pair of shoes lands half a beat late.","cn":"想象一支行进的队列，只有一双鞋慢了半拍落地。"},{"en":"Picture a mould for bricks and one brick that refuses to fit it.","cn":"想象一只砖模，以及一块拒绝贴合它的砖。"},{"en":"Picture a painting hung upside down in an academy that only hangs portraits upright.","cn":"想象一幅画倒挂在只正挂肖像的学院里。"}]},"examples":[{"en":"The company treats every nonconformity as a chance to fix the process.","cn":"这家公司把每一处不符合都视为修正流程的机会。"},{"en":"Religious nonconformity shaped the politics of several English towns.","cn":"宗教上的不从国教塑造了英格兰若干城镇的政治。"},{"en":"His nonconformity was not rebellion; it was a refusal to pretend to agree.","cn":"他的不循常规并非反叛，而是拒绝假装同意。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「不」加「同一形状」——别人都按一个样子长，他偏不 → 不遵从、不循常规","word":"nonconformity"},"root":"nonconformity 由否定前缀加表示「从众」的名词构成。那个名词来自拉丁 conformare「使成形」，由 con-「共同」与 formare「使成形」构成，formare 又出自 forma「形状」。forma 的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one refusal: not taking the shape that a group or standard expects. The refusal is applied to social custom, personal character, an established church, an art academy, a product specification, a procedure, the edge of criminal law and finally to rock layers.","cn":"八个义项沿同一个拒绝展开：不采取群体或标准所期待的形状。这个拒绝依次用于社会习俗、个人心性、国教教会、艺术学院、产品规格、既定程序、刑法边缘，最后用于岩层。"},"semanticMap":{"core":{"en":"CORE IMAGE: one pair of shoes landing off the common beat.","cn":"核心意象：一双鞋落在共同节拍之外。"},"chain":["ONE SHAPE","OFF THE BEAT","OWN JUDGEMENT","DISSENTING CHURCH","FAILED SPEC","MISFIT LAYER"],"branches":[{"senses":"01","en":"THE SOCIAL STEP: the first sense is a person whose behaviour misses the group's beat.","cn":"社会脚步：第一个义项是行为没有踩上群体节拍的人。"},{"senses":"02 · 04","en":"THE OWN SHAPE: an independent mind and an unconventional artist both refuse the provided mould.","cn":"自己的形状：独立的心性与不循成规的艺术家都拒绝现成的模具。"},{"senses":"03","en":"THE OTHER CHURCH: an entire community refuses one official form and receives a name for it.","cn":"另一个教会：整个群体拒绝一种官方形式，并因此获得一个名称。"},{"senses":"05 · 06","en":"THE FAILED MOULD: a product or procedure that does not fit the specification is recorded as a nonconformity.","cn":"失败的模具：不符合规格的产品或程序被记录为一处不符合。"},{"senses":"07 · 08","en":"THE GENTLE AND THE GEOLOGICAL: stepping out of line is not crime, and a layer out of sequence is a gap in time.","cn":"轻微与地质：走出队列并不等于犯罪，而顺序错乱的岩层是时间上的缺口。"}]},"affixes":{"intro":{"en":"The word can be read from a Latin noun for shape, the verb that gives shape, the prefix of agreement and the negative prefix.","cn":"这个单词可以按表示形状的拉丁名词、使成形的动词、表示共同的前缀以及否定前缀逐段读出。"},"latinIntro":{"en":"Latin forma gives form, formare and conformare; the negative non- turns conformity into its opposite.","cn":"拉丁 forma 衍生 form、formare 与 conformare；否定前缀 non- 把 conformity 变成它的反面。"},"items":[{"word":"non-","structure":"non- (negative prefix from Latin)","meaning":"not","meaningCN":"不；非","example":"The prefix reverses the noun that follows.","exampleCN":"这个前缀把后面的名词反转为否定。"},{"word":"forma","structure":"forma, formae (Latin noun, 'shape')","meaning":"shape, mould","meaningCN":"形状；模具","example":"The noun supplies the image of a mould.","exampleCN":"这个名词提供模具的意象。"},{"word":"formare","structure":"formare (Latin verb, 'to shape')","meaning":"to give shape to","meaningCN":"使成形；塑造","example":"The verb names the act of pressing material into a shape.","exampleCN":"这个动词指把材料压成形状的动作。"},{"word":"conformare","structure":"con- + formare","meaning":"to shape together; to make alike","meaningCN":"共同成形；使相像","example":"The Latin verb named bringing things into one form.","exampleCN":"这个拉丁动词指使事物进入同一种形式。"},{"word":"conform","structure":"conformare (English verb)","meaning":"to follow the accepted shape","meaningCN":"遵从；符合","example":"The housing must conform to the safety code.","exampleCN":"住房必须符合安全规范。"},{"word":"conformity","structure":"conform + -ity (state)","meaning":"agreement with a standard","meaningCN":"遵从；一致；符合","example":"The test checks conformity with the standard.","exampleCN":"这项测试检查是否符合标准。"},{"word":"nonconformity","structure":"non- + conformity","meaning":"refusal to take the common shape","meaningCN":"不遵从；不符合","example":"The auditor listed each nonconformity.","exampleCN":"审计员列出了每一处不符合。"},{"word":"nonconformist","structure":"non- + conform + -ist (person)","meaning":"one who refuses accepted norms","meaningCN":"不遵从者","example":"The nonconformist refused the official uniform.","exampleCN":"这位不遵从者拒绝穿官方制服。"},{"word":"conformist","structure":"conform + -ist (person)","meaning":"one who follows norms readily","meaningCN":"遵从者","example":"The conformist never questioned the schedule.","exampleCN":"这位遵从者从不质疑日程。"},{"word":"nonconforming","structure":"non- + conform + -ing (participle)","meaning":"not meeting the requirement","meaningCN":"不符合的；不遵从的","example":"The nonconforming batch was returned.","exampleCN":"不符合的批次被退回。"}],"derivatives":[{"word":"conformity","structure":"conform + -ity (state)","meaning":"agreement with a standard","meaningCN":"遵从；符合"},{"word":"nonconformist","structure":"non- + conform + -ist (person)","meaning":"one who refuses norms","meaningCN":"不遵从者"},{"word":"conform","structure":"Latin conformare","meaning":"to follow the accepted form","meaningCN":"遵从"},{"word":"nonconforming","structure":"non- + conform + -ing (participle)","meaning":"not meeting a requirement","meaningCN":"不符合的"},{"word":"conformist","structure":"conform + -ist (person)","meaning":"one who follows norms","meaningCN":"遵从者"}],"latinEntries":[{"word":"forma","structure":"forma, formae (f., first declension)","meaning":"shape, form","meaningCN":"形状；形式"},{"word":"formare","structure":"formare, formavi, formatum (verb, first conjugation)","meaning":"to shape, fashion","meaningCN":"使成形；塑造"},{"word":"conformare","structure":"conformare, conformavi, conformatum (verb, first conjugation)","meaning":"to shape together, make alike","meaningCN":"共同成形；使相像"}]}},{"word":"deviance","ipa_uk":"/ˈdiːviəns/","ipa_us":"/ˈdiːviəns/","definition_zh":"越轨；偏离社会规范的行为；（统计）偏差；（对标准的）偏离","definition_en":"behaviour or a value that departs from accepted norms, standards or expected patterns","core_image":"一条笔直的车辙延伸到岔路口，一辆车忽然拐出主路，压进旁边的草地","scene":"大路中间有两道笔直的车辙，一辆车在岔口忽然拐出主路，压进旁边的草地。Sociologists ask why some forms of deviance are punished and others are ignored.","sceneCN":"这里指「违反社会规范的越轨行为」（第 1 个义项：对社会规范的偏离行为）；句意为社会学家追问为什么有些越轨受到惩罚，另一些却被忽视。可辨识物件：车辙、岔路口、草地、路牌、车轮。","pos":[{"tag":"n.","zh":"越轨；偏离社会规范的行为（常作不可数）"},{"tag":"n.","zh":"偏差值（统计学，可数）"},{"tag":"n.","zh":"对标准或规格的偏离"}],"collocations":[{"phrase":"social deviance","zh":"社会越轨"},{"phrase":"deviant behaviour","zh":"越轨行为"},{"phrase":"measure deviance","zh":"测量偏差"},{"phrase":"deviance from the norm","zh":"对规范的偏离"},{"phrase":"deviance amplification","zh":"越轨放大"},{"phrase":"the study of deviance","zh":"越轨研究"}],"forms":[{"label":"不可数用法（越轨现象）","form":"deviance"},{"label":"可数用法（具体偏差值）","form":"deviances"},{"label":"形容词（越轨的）","form":"deviant"},{"label":"动词（偏离）","form":"deviate"},{"label":"名词（偏差；偏离）","form":"deviation"},{"label":"名词（越轨者）","form":"deviant"},{"label":"副词（偏离地）","form":"deviantly"}],"derivatives":[{"word":"deviant","pos":"adj./n.","zh":"越轨的；越轨者"},{"word":"deviate","pos":"v.","zh":"偏离；背离"},{"word":"deviation","pos":"n.","zh":"偏差；偏离"},{"word":"deviantly","pos":"adv.","zh":"以偏离的方式"},{"word":"devious","pos":"adj.","zh":"迂回的；狡诈的（同出「离开大路」词根）"},{"word":"deviate from","pos":"phr.","zh":"偏离……"}],"senses":[{"no":"01","title":"Behaviour that breaks a social norm","titleCN":"违反社会规范的行为","definition":"conduct that violates the accepted rules or expectations of a society or group","definitionCN":"违反一个社会或群体公认规则或期待的行为","example":"Sociologists ask why some forms of deviance are punished and others are ignored.","exampleCN":"社会学家追问为什么有些越轨受到惩罚，另一些却被忽视。","why":"The Latin verb means 'to turn off the road'; deviance is behaviour that leaves the path everyone else follows.","whyCN":"拉丁动词意为「拐离道路」；越轨就是离开众人所走那条路的行为。"},{"no":"02","title":"A statistical measure of misfit","titleCN":"统计上衡量拟合偏差的量","definition":"a quantity that measures how far a model or observation departs from an expected pattern","definitionCN":"衡量模型或观测偏离预期格局多远的量","example":"The model's deviance fell sharply after the new term was added.","exampleCN":"加入新项之后，模型的偏差值急剧下降。","why":"Statistics kept the road image: a point far from the fitted line is a car far from the tracks.","whyCN":"统计学保留了这个道路意象：远离拟合线的点，就像远离车辙的车。"},{"no":"03","title":"A breach that can clarify the rules","titleCN":"反而能澄清规范的越轨","definition":"the sociological idea that violation can mark the boundary of what a society considers normal","definitionCN":"越轨可以标出一个社会视为正常的边界这一社会学观念","example":"Durkheim argued that deviance can clarify a society's norms.","exampleCN":"涂尔干认为，越轨能够澄清一个社会的规范。","why":"A line is easiest to see when someone steps over it, so the breach itself draws the boundary.","whyCN":"有人越过界线时，界线才最容易看清，因此越轨本身把边界画了出来。"},{"no":"04","title":"A violation written into law","titleCN":"被写进法律的越轨","definition":"behaviour that breaks a formal rule carrying a legal penalty, usually called crime","definitionCN":"违反带有法律惩罚的正式规则的行为，通常称为犯罪","example":"Formal deviance includes offences written into the criminal code.","exampleCN":"正式越轨包括写进刑法典的罪行。","why":"When a society writes its norms into a code, stepping off the road becomes a punishable act.","whyCN":"当一个社会把规范写进法典，离开道路就变成可受惩罚的行为。"},{"no":"05","title":"A small breach of manners","titleCN":"对礼俗的轻微违背","definition":"a minor violation of everyday expectations that draws disapproval but no legal charge","definitionCN":"对日常期待的轻微违背，招来不满却不会带来法律指控","example":"Informal deviance, such as queue-jumping, draws stares rather than charges.","exampleCN":"非正式越轨，比如插队，招来的是白眼而不是指控。","why":"Not every departure from the road is a crime; some only cause others to look up.","whyCN":"并非每次离开道路都是犯罪；有些只让旁人抬起头看一眼。"},{"no":"06","title":"A breach amplified by attention","titleCN":"因关注而被放大的越轨","definition":"the process in which publicity and moral panic make a small deviation seem larger and more common","definitionCN":"宣传与道德恐慌使一个小的偏离显得更大、更常见的过程","example":"Sensational coverage produced deviance amplification in the following months.","exampleCN":"耸动的报道在随后几个月里造成了越轨放大。","why":"Attention works like a lens: the same small swerve can be magnified until it fills the frame.","whyCN":"关注就像镜头：同一个轻微拐弯可以被放大到填满画面。"},{"no":"07","title":"A stigmatizing label from the past","titleCN":"带有污名色彩的旧标签","definition":"an older clinical or moral label applied to behaviour that later generations regard as ordinary","definitionCN":"旧时贴在后来被视为平常的行为上的临床或道德标签","example":"The old manual used deviance to pathologize behaviour now accepted.","exampleCN":"旧手册用「越轨」把如今被接受的行为病理化。","why":"The word can be a verdict as well as a description, and old verdicts often say more about the judge than the accused.","whyCN":"这个词既可以是描述，也可以是判决，而旧判决常常更多说明判者而非被判定者。"},{"no":"08","title":"Distance from a technical standard","titleCN":"与技术标准的差距","definition":"the amount by which a measurement, product or process differs from a stated standard","definitionCN":"测量值、产品或流程与规定标准之间的差距","example":"The lab recorded any deviance from the calibration standard.","exampleCN":"实验室记录了任何与校准标准的偏离。","why":"In a laboratory the road is a calibration line, and deviance is how far the reading has wandered from it.","whyCN":"在实验室里，道路就是一条校准线，而偏差是读数偏离它多远。"}],"etymology":{"intro":{"en":"Deviance comes from Latin deviare 'to turn off the road', built on de- 'away' and via 'way, road'. The English noun was formed from deviant and established in sociology in the twentieth century. Dates are approximate.","cn":"deviance 来自拉丁 deviare「拐离道路」，由 de-「离开」与 via「道路」构成。这个英语名词由 deviant 构成，并在二十世纪的社会学中确立。年代均为约数。"},"items":[{"era":"LATIN VIA","en":"Via meant 'way, road, path'. Its deeper origin is not established; the road root proposed for it is a reconstruction.","cn":"via 意为「道路、路径」。其更深来源未得到证明；为它提出的「道路」词根属于重构形式。"},{"era":"LATIN DEVIARE","en":"De- 'away' plus via produced deviare, 'to leave the road, turn aside'.","cn":"de-「离开」加 via 构成 deviare「离开道路、拐向一旁」。"},{"era":"LATIN DEVIANS","en":"The participle devians named someone or something in the act of turning off the road.","cn":"分词 devians 指正在拐离道路的人或物。"},{"era":"ENGLISH DEVIATE AND DEVIANT","en":"English adopted the verb and adjective in the fifteenth and sixteenth centuries, first in the literal sense of straying from a route.","cn":"英语在十五与十六世纪引入动词与形容词，最初用的是「偏离路线」的字面义。"},{"era":"SOCIOLOGICAL NOUN","en":"The noun deviance was formed from deviant with the ending -ance and became a standard sociological term in the twentieth century.","cn":"名词 deviance 由 deviant 加名词后缀构成，在二十世纪成为标准的社会学术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of via is unsettled, and no exact first citation is fixed for the statistical sense, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：via 在拉丁语之前的来源无定论；统计义也没有确切的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the same off-the-road family; group two holds terms for departure from a norm or pattern.","cn":"第一组是同出「拐离道路」词族的词；第二组是表示偏离规范或格局的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deviant","ipa":"/ˈdiːviənt/","tag":"the adjective or person","definition":"Describing behaviour that departs from norms, or a person who does so; deviance names the phenomenon.","definitionCN":"描述偏离规范的行为，或这样的人；deviance 指这一现象本身。"},{"word":"deviate","ipa":"/ˈdiːvieɪt/","tag":"the verb","definition":"To depart from a route, standard or expected course; the noun is the result of doing so.","definitionCN":"偏离路线、标准或预期方向；名词是这一动作的结果。"},{"word":"deviation","ipa":"/ˌdiːviˈeɪʃən/","tag":"the neutral noun","definition":"A departure from an expected value or course; it is neutral in tone, while deviance often carries a social judgement.","definitionCN":"对预期值或路线的偏离；语气中立，而 deviance 常带社会评判。"},{"word":"devious","ipa":"/ˈdiːviəs/","tag":"same road root","definition":"Means indirect or cunning, literally 'off the main road'; it shares the root without the sociological sense.","definitionCN":"意为「迂回的、狡诈的」，字面是「离开大路」；共享词根，却无社会学含义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nonconformity","ipa":"/ˌnɒnkənˈfɔːməti/","tag":"the deliberate refusal","definition":"Refusal to take the shape a group expects; it often suggests choice, while deviance can be statistical or unintended.","definitionCN":"拒绝采取群体期待的形状；常暗示主动选择，而 deviance 可以是统计性的或非故意的。"},{"word":"delinquency","ipa":"/dɪˈlɪŋkwənsi/","tag":"youthful offence","definition":"Minor criminal behaviour, especially by young people; it is a legal category, narrower than deviance.","definitionCN":"轻微的犯罪行为，尤指青少年所为；它是法律类别，比 deviance 更窄。"},{"word":"anomaly","ipa":"/əˈnɒməli/","tag":"something that does not fit","definition":"A thing that does not match the expected pattern; it can be neutral and has no moral weight.","definitionCN":"不符合预期格局的事物；可以完全中立，不带道德重量。"},{"word":"aberration","ipa":"/ˌæbəˈreɪʃən/","tag":"a temporary departure","definition":"A single departure from normal behaviour or expectation, often brief and unusual.","definitionCN":"对正常行为或预期的一次偏离，通常短暂而少见。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real road root, the real derivatives and the real sociological phrases.","cn":"正常联想：真实的「道路」词根、真实的派生词与真实的社会学搭配。"},"normal":[{"en":"The Latin verb means 'to turn off the road', so every sense is some kind of departure from a line.","cn":"拉丁动词意为「拐离道路」，因此每个义项都是对某条线的一种偏离。"},{"en":"The family runs deviate, deviant, deviance, deviation, deviously and devious.","cn":"同族词包括 deviate、deviant、deviance、deviation、deviously 与 devious。"},{"en":"The sociological phrases are social deviance, the study of deviance and deviance amplification.","cn":"社会学搭配有社会越轨、越轨研究与越轨放大。"},{"en":"The measurement phrases are measure deviance and deviance from the norm.","cn":"测量搭配有测量偏差与对规范的偏离。"},{"en":"The adjective deviant is the person or behaviour, while the noun names the pattern they make.","cn":"形容词 deviant 指人或行为，名词则指它们形成的模式。"}],"abstract":[{"en":"Picture a car leaving two straight tracks and pressing into the grass.","cn":"想象一辆车离开两道笔直的车辙，压进草地。"},{"en":"Picture a point on a graph that sits far from every fitted line.","cn":"想象图上一个点远离所有拟合线。"},{"en":"Picture a small swerve on the evening news, magnified until it fills the screen.","cn":"想象晚间新闻里一个轻微拐弯，被放大到填满屏幕。"}]},"examples":[{"en":"The course compares deviance in different legal systems.","cn":"这门课程比较不同法律体系中的越轨现象。"},{"en":"A single deviance in the reading was enough to stop the batch.","cn":"读数中仅仅一处偏差就足以让这批产品停下。"},{"en":"The label of deviance often tells us more about who held the pen than about the person described.","cn":"「越轨」这个标签常常更多说明谁握着笔，而非被描述的人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「离开」加「道路」——别人沿大路走，他拐进草地 → 越轨、偏离","word":"deviance"},"root":"deviance 来自拉丁 deviare「拐离道路」= de-「离开」+ via「道路」；英语名词由 deviant 加名词后缀构成。via 在拉丁语之前的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one movement: leaving the expected line. The movement is applied to social norms, a statistical fit, the boundary of rules, criminal law, everyday manners, media attention, an old moral label and a technical standard.","cn":"八个义项沿同一个动作展开：离开预期的那条线。这个动作依次用于社会规范、统计拟合、规范边界、刑法、日常礼俗、媒体关注、旧道德标签与技术标准。"},"semanticMap":{"core":{"en":"CORE IMAGE: a car turning out of two straight tracks into the grass.","cn":"核心意象：一辆车从两道笔直的车辙拐进草地。"},"chain":["OFF THE ROAD","NORM BREACH","BOUNDARY MADE VISIBLE","FORMAL AND INFORMAL","AMPLIFIED","MEASURED GAP"],"branches":[{"senses":"01","en":"THE FIRST SWERVE: behaviour leaves the path that the group treats as normal.","cn":"第一次拐弯：行为离开了群体视为正常的那条路。"},{"senses":"02 · 08","en":"THE MEASURED DISTANCE: a statistical model and a calibration standard both turn the road into a number.","cn":"被测量的距离：统计模型与校准标准都把道路变成一个数字。"},{"senses":"03","en":"THE VISIBLE BOUNDARY: the breach itself shows where the line had been all along.","cn":"可见的边界：越轨本身显示出界线一直所在的位置。"},{"senses":"04 · 05","en":"THE TWO CODES: criminal law punishes the large swerve, while manners only register the small one.","cn":"两套法典：刑法惩罚大幅拐弯，礼俗只记录轻微拐弯。"},{"senses":"06 · 07","en":"THE LENS AND THE LABEL: attention magnifies the swerve, and an old label decides whose swerve it is.","cn":"镜头与标签：关注放大拐弯，旧标签则决定这是谁的拐弯。"}]},"affixes":{"intro":{"en":"The noun can be read from a Latin prefix of departure, the Latin noun for a road, the verb built on them and the derived family.","cn":"这个名词可以按表示离开的拉丁前缀、表示道路的拉丁名词、由它们构成的动词以及派生词族逐段读出。"},"latinIntro":{"en":"Latin de- and via give deviare; English built deviate, deviant and deviance on the same stem, and devious keeps the literal image of being off the road.","cn":"拉丁 de- 与 via 构成 deviare；英语在同一词干上构成 deviate、deviant 与 deviance，而 devious 保留了「离开大路」的字面意象。"},"items":[{"word":"de-","structure":"de- (Latin prefix, 'away, down')","meaning":"away; off","meaningCN":"离开；向下","example":"The prefix marks movement away from the path.","exampleCN":"这个前缀标记离开道路的移动。"},{"word":"via","structure":"via, viae (Latin noun, 'road')","meaning":"way, road","meaningCN":"道路；路径","example":"The noun supplies the image of a travelled route.","exampleCN":"这个名词提供被行走的路线意象。"},{"word":"deviare","structure":"de- + via (Latin verb)","meaning":"to turn off the road","meaningCN":"拐离道路","example":"The Latin verb named leaving the route.","exampleCN":"这个拉丁动词指离开路线。"},{"word":"deviate","structure":"deviare (English verb)","meaning":"to depart from a course","meaningCN":"偏离；背离","example":"The aircraft deviated from its flight path.","exampleCN":"飞机偏离了航线。"},{"word":"deviation","structure":"deviate + -ion (action or result)","meaning":"a departure from an expected value","meaningCN":"偏差；偏离","example":"The gauge showed a small deviation.","exampleCN":"仪表显示出一处小偏差。"},{"word":"deviant","structure":"deviare + -ant (one acting)","meaning":"departing from norms","meaningCN":"越轨的；越轨者","example":"The study followed deviant behaviour in adolescents.","exampleCN":"这项研究追踪青少年的越轨行为。"},{"word":"deviance","structure":"deviant + -ance (state)","meaning":"the state or pattern of departing from norms","meaningCN":"越轨；偏离规范的状态","example":"Deviance is defined by the group that judges it.","exampleCN":"越轨由作出评判的群体来定义。"},{"word":"deviantly","structure":"deviant + -ly (adverb ending)","meaning":"in a departing manner","meaningCN":"以偏离的方式","example":"The machine behaved deviantly under load.","exampleCN":"这台机器在负载下出现了偏离行为。"},{"word":"devious","structure":"devius (Latin, 'off the road') + -ous","meaning":"indirect; cunning","meaningCN":"迂回的；狡诈的","example":"The route was devious but safe.","exampleCN":"这条路线迂回却安全。"}],"derivatives":[{"word":"deviant","structure":"deviare + -ant (one acting)","meaning":"departing from norms","meaningCN":"越轨的"},{"word":"deviate","structure":"Latin deviare","meaning":"to depart from a course","meaningCN":"偏离"},{"word":"deviation","structure":"deviate + -ion (action or result)","meaning":"a departure","meaningCN":"偏差"},{"word":"deviously","structure":"devious + -ly (adverb ending)","meaning":"in an indirect way","meaningCN":"迂回地；狡诈地"},{"word":"devious","structure":"Latin devius + -ous","meaning":"off the road; indirect","meaningCN":"离路的；迂回的"}],"latinEntries":[{"word":"via","structure":"via, viae (f., first declension)","meaning":"way, road","meaningCN":"道路；路径"},{"word":"deviare","structure":"deviare, deviavi, deviatum (verb, first conjugation)","meaning":"to turn off the road","meaningCN":"拐离道路"},{"word":"devius","structure":"devius, -a, -um (adjective)","meaning":"off the road, remote","meaningCN":"离开道路的；偏远的"}]}},{"word":"deviant","ipa_uk":"/ˈdiːviənt/","ipa_us":"/ˈdiːviənt/","definition_zh":"偏离社会规范的；越轨的；越轨者；异常个案","definition_en":"departing from accepted norms or standards; a person or thing that so departs","core_image":"一辆车从两道笔直的车辙里拐出来，压进旁边的草地，车里的人回头看了一眼主路","scene":"课桌上的调查表画着一条笔直的路线，旁边的箭头拐向草地。The researcher marked every deviant act in the sample with a red dot.","sceneCN":"这里指「偏离社会规范的行为」（第 1 个义项：偏离群体公认规范的行为）；句意为研究者用红点标出样本中每一个越轨行为。可辨识物件：调查表、路线、箭头、草地、红点。","pos":[{"tag":"adj.","zh":"偏离社会规范的；越轨的"},{"tag":"n.","zh":"越轨者；被贴上越轨标签的人"},{"tag":"n.","zh":"异常个案；偏离标准的样本"}],"collocations":[{"phrase":"deviant behaviour","zh":"越轨行为"},{"phrase":"deviant case","zh":"异常个案"},{"phrase":"deviant subculture","zh":"越轨亚文化"},{"phrase":"labelled as deviant","zh":"被贴上越轨标签"},{"phrase":"deviant from the norm","zh":"偏离规范的"},{"phrase":"statistically deviant","zh":"统计上偏离的"}],"forms":[{"label":"形容词原级（偏离规范的）","form":"deviant"},{"label":"形容词比较级（更偏离的）","form":"more deviant"},{"label":"形容词最高级（最偏离的）","form":"most deviant"},{"label":"名词复数（越轨者）","form":"deviants"},{"label":"名词（越轨现象）","form":"deviance"},{"label":"动词（偏离）","form":"deviate"},{"label":"名词（偏差）","form":"deviation"},{"label":"副词（以偏离的方式）","form":"deviantly"}],"derivatives":[{"word":"deviance","pos":"n.","zh":"越轨；偏离规范的状态或现象"},{"word":"deviation","pos":"n.","zh":"偏差；偏离"},{"word":"deviantly","pos":"adv.","zh":"以偏离的方式"},{"word":"devious","pos":"adj.","zh":"迂回的；狡诈的（同出「离开大路」词根）"},{"word":"deviancy","pos":"n.","zh":"越轨性；偏离倾向"},{"word":"deviate","pos":"v.","zh":"偏离；背离"}],"senses":[{"no":"01","title":"Departing from a social norm","titleCN":"偏离社会规范的","definition":"describing behaviour or a trait that departs from the accepted norms of a group","definitionCN":"形容偏离一个群体公认规范的行为或特征","example":"Teachers once punished any deviant behaviour in the classroom.","exampleCN":"教师过去会惩罚课堂上任何越轨行为。","why":"The Latin verb means 'to turn off the road', and the adjective keeps that image as a quality of the behaviour.","whyCN":"拉丁动词意为「拐离道路」，这个形容词把这幅图像保留为行为的一种性质。"},{"no":"02","title":"A person judged to be outside the norm","titleCN":"被判为越轨的人","definition":"a person whose conduct or identity a group regards as departing from its accepted norms","definitionCN":"其行为或身份被一个群体视为偏离公认规范的人","example":"The village treated the artist as a deviant and stopped buying his work.","exampleCN":"村里把这位画家当成越轨者，不再买他的画。","why":"The noun ending turns the quality into a person who carries it, so the adjective can stand alone as a name for someone.","whyCN":"名词词尾把这种性质变成承载它的人，于是这个形容词可以单独用来称呼一个人。"},{"no":"03","title":"Behaviour studied as a countable pattern","titleCN":"被当作可计数模式研究的越轨行为","definition":"the behaviour itself, examined as a repeated social pattern rather than attached to one person","definitionCN":"行为本身，被当作反复出现的社会模式来考察，而不是挂在某一个人身上","example":"The course compares deviant behaviour across three cities.","exampleCN":"这门课程比较三座城市中的越轨行为。","why":"Sociology moves the word from a person back to the act, which lets researchers count how often it occurs.","whyCN":"社会学把这个词从人移回行为，使研究者能够统计它出现的频率。"},{"no":"04","title":"A case far from the fitted line","titleCN":"远离拟合线的个案","definition":"an observation or sample that sits far from the pattern predicted by a model or a comparison group","definitionCN":"远离模型或对照组所预测格局的观测值或样本","example":"One deviant case pulled the average away from the rest.","exampleCN":"一个异常个案把平均值拉离了其余数据。","why":"Statistics keeps the road as a fitted line, and a deviant case is a point that sits far from it.","whyCN":"统计学把道路保留为一条拟合线，而异常个案就是远离它的一点。"},{"no":"05","title":"An old label placed on people","titleCN":"旧时贴在人与上的标签","definition":"an older moral or clinical label applied to people whose behaviour later generations regard as ordinary","definitionCN":"旧时贴在行为后来被视为平常的人身上的道德或临床标签","example":"Old manuals called left-handed children deviant and tried to correct them.","exampleCN":"旧手册把左撇子儿童称为越轨，并试图纠正他们。","why":"The word can act as a verdict, and an old verdict often says more about the judge than about the person judged.","whyCN":"这个词可以充当判决，而旧判决常常更多说明判者，而非被判定的人。"},{"no":"06","title":"A reading off the calibration","titleCN":"偏离校准的读数","definition":"describing a measurement, product or process that falls outside a stated technical standard","definitionCN":"形容落在规定技术标准之外的测量值、产品或流程","example":"The inspector rejected the deviant sample and sent the batch back.","exampleCN":"检验员拒收了偏离标准的样本，把整批货退回。","why":"In a laboratory the road becomes a calibration curve, and deviant means off that curve.","whyCN":"在实验室里，道路变成一条校准曲线，而偏离就是指离开那条曲线。"},{"no":"07","title":"Art that breaks the academy's line","titleCN":"突破学院路线的艺术","definition":"describing art or design that departs from the rules an academy or market treats as correct","definitionCN":"形容偏离学院或市场视为正确的规则的艺术或设计","example":"The academy called the new painting deviant, and the public soon loved it.","exampleCN":"学院称这幅新画离经叛道，公众却很快爱上了它。","why":"Art academies draw a line too, and work that leaves it is first called deviant and later called influential.","whyCN":"艺术学院同样画一条线，离开这条线的作品先被称作离经叛道，后来又被称作有影响力。"},{"no":"08","title":"A form unlike the usual type","titleCN":"与常见类型不同的形态","definition":"describing a plant, animal or structure whose form departs from the typical shape of its kind","definitionCN":"形容形态偏离同类典型形状的植物、动物或构造","example":"The botanist described a deviant form with curled leaves.","exampleCN":"植物学家描述了一种叶子卷曲的异常形态。","why":"Biology applies the same word to a living shape that departs from the typical form of its species.","whyCN":"生物学把同一个词用于偏离本物种典型形态的活体形状。"}],"etymology":{"intro":{"en":"Deviant comes from Latin deviare 'to turn off the road', built on de- 'away' and via 'road'. English took the adjective from the present participle devians. Dates are approximate.","cn":"deviant 来自拉丁 deviare「拐离道路」，由 de-「离开」与 via「道路」构成。英语的形容词取自该动词的现在分词。年代均为约数。"},"items":[{"era":"LATIN VIA","en":"Via meant 'way, road, path'. Its deeper origin is not established; the root proposed for it is a reconstruction.","cn":"via 意为「道路、路径」。其更深来源未得到证明；为它提出的词根属于重构形式。"},{"era":"LATIN DEVIARE","en":"De- 'away' plus via produced deviare, 'to leave the road, turn aside'.","cn":"de-「离开」加 via 构成 deviare「离开道路、拐向一旁」。"},{"era":"LATIN DEVIANS","en":"The present participle devians described someone or something in the act of turning aside.","cn":"现在分词 devians 描述正在拐向一旁的人或物。"},{"era":"ENGLISH ADJECTIVE","en":"English adopted the adjective in the fifteenth and sixteenth centuries, at first for straying from a literal route.","cn":"英语在十五与十六世纪引入这个形容词，最初用于偏离字面意义上的路线。"},{"era":"SOCIOLOGICAL NOUN","en":"The noun deviance, formed from deviant, made the adjective a standard term in twentieth-century sociology.","cn":"由这个形容词构成的名词 deviance 在二十世纪社会学中成为标准术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): the pre-Latin source of via is unsettled, and no exact first citation is fixed for the statistical sense, so dates here are approximations.","cn":"来源不确定（更深词源与首见年代）：via 在拉丁语之前的来源无定论；统计义也没有确切的最早书证，因此这里给出的年代均为约数。"}]},"similar":{"note":{"en":"Group one holds the same off-the-road family and one look-alike from a different root; group two holds words for people or things that depart from a norm.","cn":"第一组是同出「拐离道路」词族的词，另有一个形近却不同源的词；第二组是表示偏离规范的人或事物的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deviate","ipa":"/ˈdiːvieɪt/","tag":"the verb","definition":"To leave a route, standard or expected course; the adjective describes the quality of what has left.","definitionCN":"离开路线、标准或预期方向；形容词则描述离开之后的性质。"},{"word":"deviation","ipa":"/ˌdiːviˈeɪʃən/","tag":"the neutral noun","definition":"A departure from an expected value or course; it is neutral in tone, while the adjective often carries a social judgement.","definitionCN":"对预期值或路线的偏离；语气中立，而形容词常带社会评判。"},{"word":"deviance","ipa":"/ˈdiːviəns/","tag":"the phenomenon","definition":"The pattern or state of departing from norms; the adjective names a single trait, person or case.","definitionCN":"偏离规范的模式或状态；形容词则指单一的性质、人或个案。"},{"word":"devious","ipa":"/ˈdiːviəs/","tag":"same road root","definition":"Means indirect or cunning, literally 'off the main road'; it shares the root but has no sociological sense.","definitionCN":"意为「迂回的、狡诈的」，字面是「离开大路」；共享词根，却没有社会学含义。"},{"word":"defiant","ipa":"/dɪˈfaɪənt/","tag":"look-alike, different root","definition":"Means openly resisting authority; it comes from a French verb meaning to challenge, not from the Latin word for a road.","definitionCN":"意为公开反抗权威；它来自一个表示「挑战」的法语动词，与表示道路的拉丁词无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nonconformist","ipa":"/ˌnɒnkənˈfɔːmɪst/","tag":"the deliberate refusal","definition":"A person who refuses to take the shape a group expects; the choice is often deliberate, while deviation can be unintended.","definitionCN":"拒绝采取群体期待形状的人；这种选择常是主动的，而偏离可以是非故意的。"},{"word":"aberrant","ipa":"/əˈberənt/","tag":"a rare departure","definition":"Departing sharply from what is normal or expected, often in a single unusual instance; it sounds more clinical than deviant.","definitionCN":"急剧偏离正常或预期，常指单独一次少见情形；比形容词 deviant 更像临床用语。"},{"word":"anomalous","ipa":"/əˈnɒmələs/","tag":"something that does not fit","definition":"Not matching an established pattern or rule; it can be entirely neutral and carries no moral weight.","definitionCN":"不符合既定格局或规则；可以完全中立，不带道德重量。"},{"word":"outlier","ipa":"/ˈaʊtlaɪə/","tag":"the statistical case","definition":"A value that lies far from the rest of a set; it names the data point itself, not a person or a social judgement.","definitionCN":"远离集合中其余数值的值；它指数据点本身，不指人，也不带社会评判。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real road root, the real derived family and the real phrases used in sociology and measurement.","cn":"正常联想：真实的「道路」词根、真实的派生词族，以及社会学与测量中真实使用的搭配。"},"normal":[{"en":"The Latin verb means 'to turn off the road', so the adjective describes anything that has left the expected line.","cn":"拉丁动词意为「拐离道路」，因此这个形容词描述任何离开预期路线的对象。"},{"en":"The family runs deviate, deviant, deviance, deviation and devious.","cn":"同族词包括动词偏离、形容词越轨的、名词越轨现象、名词偏差与形容词迂回的。"},{"en":"Sociology pairs the adjective with behaviour, case, subculture and group.","cn":"社会学里，这个词常与行为、个案、亚文化和群体搭配。"},{"en":"In a laboratory the same adjective marks a reading that sits off the calibration curve.","cn":"在实验室里，同一个形容词标记偏离校准曲线的读数。"},{"en":"The noun ending marks a person, while the adjective can describe a trait, a case or a form.","cn":"名词词尾标记一个人，而形容词可以描述一种性质、一个个案或一种形态。"}],"abstract":[{"en":"Picture a car leaving two straight tracks and pressing into the grass.","cn":"想象一辆车离开两道笔直的车辙，压进草地。"},{"en":"Picture a single point sitting far from the fitted line on a graph.","cn":"想象图上一个点远离拟合线。"},{"en":"Picture a leaf that curls in a way its species never does.","cn":"想象一片叶子卷成它所属物种从不出现的形状。"}]},"examples":[{"en":"The study followed deviant behaviour among teenagers in three cities.","cn":"这项研究追踪三座城市青少年的越轨行为。"},{"en":"One deviant reading was enough to stop the whole batch.","cn":"一个偏离的读数就足以让整批产品停下。"},{"en":"The label deviant says as much about the labeller as about the person labelled.","cn":"「越轨」这个标签既说明被贴标签的人，也说明贴标签的人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「离开」加「道路」——别人沿大路走，他偏拐进草地 → 越轨的、偏离的","word":"deviant"},"root":"deviant 来自拉丁 deviare「拐离道路」= de-「离开」+ via「道路」；英语形容词取自该动词的现在分词。via 在拉丁语之前的更深来源不确定。","sensesIntro":{"en":"Eight senses follow one adjective: something has left the line. The word first names a trait, then a person, then a countable pattern, then a point in the data, a verdict in old language, an engineering reading, an artist's break and a living form.","cn":"八个义项沿同一个形容词展开：某物离开了那条线。这个词先命名一种性质，再指一个人，然后指可计数的模式、数据中的点、旧语言里的判决、工程读数、艺术家的突破与活体的形态。"},"semanticMap":{"core":{"en":"CORE IMAGE: a car turning out of two straight tracks into the grass.","cn":"核心意象：一辆车从两道笔直的车辙拐进草地。"},"chain":["OFF THE ROAD","A QUALITY NAMED","A PERSON NAMED","A PATTERN COUNTED","A VERDICT PRONOUNCED","A FORM SHAPED DIFFERENTLY"],"branches":[{"senses":"01 · 03","en":"THE DEPARTURE ITSELF: the adjective names a trait, and sociology turns the same departure into a countable pattern.","cn":"偏离本身：形容词命名一种性质，社会学把同一种偏离变成可计数的模式。"},{"senses":"02 · 05","en":"THE PERSON AND THE VERDICT: a person can be called deviant, and old language often made that call a permanent label.","cn":"人与判决：一个人可以被称作越轨者，而旧时的语言常把这个称呼变成永久标签。"},{"senses":"04 · 06","en":"THE MEASURED GAP: a sample point and a product reading are both judged against a fitted line.","cn":"被测量的差距：样本点与产品读数都要对照一条拟合线来评判。"},{"senses":"07","en":"THE ACADEMY'S LINE: new art is first called deviant because it leaves the line the academy drew.","cn":"学院画的线：新艺术先被称作离经叛道，因为它离开了学院画下的那条线。"},{"senses":"08","en":"THE LIVING FORM: biology applies the same word to a shape that departs from the typical form of its kind.","cn":"活体的形态：生物学把同一个词用于偏离同类典型形态的形状。"}]},"affixes":{"intro":{"en":"The adjective can be read from a Latin prefix of departure, the Latin noun for a road, the verb built on them, the participle and the derived family.","cn":"这个形容词可以按表示离开的拉丁前缀、表示道路的拉丁名词、由它们构成的动词、现在分词以及派生词族逐段读出。"},"latinIntro":{"en":"Latin de- and via give deviare, whose present participle devians yields the English adjective; the same stem also produces deviate, deviance and deviation, while devious keeps the literal image of being off the road.","cn":"拉丁 de- 与 via 构成 deviare，其现在分词产生英语形容词；同一词干还产生动词、名词与偏差名词，而 devious 保留了「离开大路」的字面意象。"},"items":[{"word":"de-","structure":"de- (Latin prefix, 'away, down')","meaning":"away; off","meaningCN":"离开；向下","example":"The prefix marks movement away from the path.","exampleCN":"这个前缀标记离开道路的移动。"},{"word":"via","structure":"via, viae (Latin noun, 'road')","meaning":"way, road","meaningCN":"道路；路径","example":"The noun supplies the image of a travelled route.","exampleCN":"这个名词提供被行走的路线意象。"},{"word":"deviare","structure":"de- + via (Latin verb)","meaning":"to turn off the road","meaningCN":"拐离道路","example":"The Latin verb named leaving the route.","exampleCN":"这个拉丁动词指离开路线。"},{"word":"devians","structure":"deviare + -ns (present participle)","meaning":"turning off the road","meaningCN":"正在拐离道路的","example":"The participle supplied the shape of the English adjective.","exampleCN":"这个分词提供了英语形容词的形式。"},{"word":"deviant","structure":"devians (English adjective)","meaning":"departing from norms","meaningCN":"越轨的；偏离的","example":"The adjective describes behaviour, a case or a form.","exampleCN":"这个形容词可描述行为、个案或形态。"},{"word":"deviate","structure":"deviare (English verb)","meaning":"to depart from a course","meaningCN":"偏离；背离","example":"The aircraft deviated from its flight path.","exampleCN":"飞机偏离了航线。"},{"word":"deviance","structure":"deviant + -ance (state)","meaning":"the pattern of departure from norms","meaningCN":"越轨；偏离规范的状态","example":"Deviance is defined by the group that judges it.","exampleCN":"越轨由作出评判的群体来定义。"},{"word":"deviation","structure":"deviate + -ion (action or result)","meaning":"a departure from an expected value","meaningCN":"偏差；偏离","example":"The gauge showed a small deviation.","exampleCN":"仪表显示出一处小偏差。"},{"word":"devious","structure":"devius (Latin, 'off the road') + -ous","meaning":"indirect; cunning","meaningCN":"迂回的；狡诈的","example":"The route was devious but safe.","exampleCN":"这条路线迂回却安全。"},{"word":"deviantly","structure":"deviant + -ly (adverb ending)","meaning":"in a departing manner","meaningCN":"以偏离的方式","example":"The machine behaved deviantly under load.","exampleCN":"这台机器在负载下出现了偏离行为。"}],"derivatives":[{"word":"deviance","structure":"deviant + -ance (state)","meaning":"the state or pattern of departing from norms","meaningCN":"越轨；偏离规范的状态"},{"word":"deviation","structure":"deviate + -ion (action or result)","meaning":"a departure","meaningCN":"偏差；偏离"},{"word":"deviantly","structure":"deviant + -ly (adverb ending)","meaning":"in a departing manner","meaningCN":"以偏离的方式"},{"word":"deviancy","structure":"deviant + -ancy (state)","meaning":"the tendency to depart from norms","meaningCN":"越轨性；偏离倾向"},{"word":"devious","structure":"Latin devius + -ous","meaning":"off the road; indirect","meaningCN":"离路的；迂回的"}],"latinEntries":[{"word":"via","structure":"via, viae (f., first declension)","meaning":"way, road","meaningCN":"道路；路径"},{"word":"deviare","structure":"deviare, deviavi, deviatum (verb, first conjugation)","meaning":"to turn off the road","meaningCN":"拐离道路"},{"word":"devius","structure":"devius, -a, -um (adjective)","meaning":"off the road, remote","meaningCN":"离开道路的；偏远的"}]}}]);
